	public static class IsekaiBuildTitles
	{
		public class Archetype
		{
			public readonly string id;

			public readonly IsekaiStatType primary;

			public readonly bool primaryIsCaster;

			public readonly IsekaiStatType? secondary;

			public readonly bool secondaryIsCaster;

			public readonly string discipline;

			public bool IsHybrid => secondary.HasValue;

			public Archetype(string id, IsekaiStatType primary, string discipline, IsekaiStatType? secondary = null, bool secondaryIsCaster = false, bool primaryIsCaster = false)
			{
				this.id = id;
				this.primary = primary;
				this.discipline = discipline;
				this.secondary = secondary;
				this.secondaryIsCaster = secondaryIsCaster;
				this.primaryIsCaster = primaryIsCaster;
			}

			public bool LeadsOn(IsekaiStatType stat)
			{
				return primaryIsCaster ? IsCasterStat(stat) : (primary == stat);
			}

			public bool Involves(IsekaiStatType stat)
			{
				if (LeadsOn(stat))
				{
					return true;
				}
				if (!secondary.HasValue)
				{
					return false;
				}
				if (secondaryIsCaster)
				{
					return IsCasterStat(stat);
				}
				return secondary.Value == stat;
			}
		}

		public struct BuildTitle
		{
			public Archetype archetype;

			public TitleTier tier;

			public bool Exists => archetype != null && tier != TitleTier.None;
		}

		private static readonly int[] TierThresholds = new int[7] { 0, 20, 50, 100, 200, 400, 800 };

		private static readonly string[] TierWords = new string[7] { "Beginner", "Disciple", "Expert", "Saint", "King", "Emperor", "God" };

		public const TitleTier LowestTier = TitleTier.Disciple;

		public const TitleTier FirstDisciplineTier = TitleTier.Saint;

		private static readonly string[] TierColors = new string[7] { "#FFFFFF", "#FFFFFF", "#FFF9D9", "#FFF2B2", "#FFE98C", "#FFE04D", "#FFD919" };

		private const IsekaiStatType STR = IsekaiStatType.Strength;

		private const IsekaiStatType VIT = IsekaiStatType.Vitality;

		private const IsekaiStatType DEX = IsekaiStatType.Dexterity;

		private const IsekaiStatType INT = IsekaiStatType.Intelligence;

		private const IsekaiStatType WIS = IsekaiStatType.Wisdom;

		private const IsekaiStatType CHA = IsekaiStatType.Charisma;

		public static readonly List<Archetype> Archetypes = new List<Archetype>
		{
			new Archetype("Sword", IsekaiStatType.Strength, "Sword", null),
			new Archetype("Archer", IsekaiStatType.Dexterity, "Archer", null),
			new Archetype("Magic", IsekaiStatType.Intelligence, "Magic", null, secondaryIsCaster: false, primaryIsCaster: true),
			new Archetype("Voice", IsekaiStatType.Charisma, "Voice", null),
			new Archetype("Warlord", IsekaiStatType.Strength, "Warlord", IsekaiStatType.Dexterity),
			new Archetype("Warmage", IsekaiStatType.Strength, "Warmage", IsekaiStatType.Intelligence, secondaryIsCaster: true),
			new Archetype("Stormcaller", IsekaiStatType.Dexterity, "Stormcaller", IsekaiStatType.Intelligence, secondaryIsCaster: true)
		};

		private static readonly IsekaiStatType[] TitleStats = new IsekaiStatType[5]
		{
			IsekaiStatType.Strength,
			IsekaiStatType.Dexterity,
			IsekaiStatType.Intelligence,
			IsekaiStatType.Wisdom,
			IsekaiStatType.Charisma
		};

		private const float HybridShare = 0.6f;

		private static Dictionary<string, Archetype> byId;

		public static bool IsCasterStat(IsekaiStatType stat)
		{
			return stat == IsekaiStatType.Intelligence || stat == IsekaiStatType.Wisdom;
		}

		public static Archetype ById(string id)
		{
			if (id == null)
			{
				return null;
			}
			if (byId == null)
			{
				byId = new Dictionary<string, Archetype>(Archetypes.Count);
				for (int i = 0; i < Archetypes.Count; i++)
				{
					byId[Archetypes[i].id] = Archetypes[i];
				}
			}
			Archetype value;
			return byId.TryGetValue(id, out value) ? value : null;
		}

		public static BuildTitle Classify(IsekaiStatAllocation stats)
		{
			BuildTitle buildTitle = default(BuildTitle);
			buildTitle.archetype = null;
			buildTitle.tier = TitleTier.None;
			BuildTitle result = buildTitle;
			if (stats == null)
			{
				return result;
			}
			int num = 5;
			int num2 = -1;
			int num3 = -1;
			IsekaiStatType isekaiStatType = IsekaiStatType.Strength;
			IsekaiStatType y = IsekaiStatType.Strength;
			for (int i = 0; i < TitleStats.Length; i++)
			{
				int num4 = Mathf.Max(0, ValueOf(stats, TitleStats[i]) - num);
				if (num4 > num2)
				{
					num3 = num2;
					y = isekaiStatType;
					num2 = num4;
					isekaiStatType = TitleStats[i];
				}
				else if (num4 > num3)
				{
					num3 = num4;
					y = TitleStats[i];
				}
			}
			if (num2 < ThresholdFor(TitleTier.Disciple))
			{
				return result;
			}
			if ((float)num3 >= (float)num2 * 0.6f)
			{
				Archetype archetype = FindHybrid(isekaiStatType, y);
				if (archetype != null)
				{
					TitleTier titleTier = TierFor(num3);
					if (titleTier != TitleTier.None)
					{
						result.archetype = archetype;
						result.tier = titleTier;
						return result;
					}
				}
			}
			result.archetype = ForStat(isekaiStatType);
			result.tier = ((result.archetype == null) ? TitleTier.None : TierFor(num2));
			return result;
		}

		public static IsekaiStatType LeadingStat(IsekaiStatAllocation stats, out int allocated)
		{
			allocated = 0;
			IsekaiStatType result = IsekaiStatType.Strength;
			if (stats == null)
			{
				return result;
			}
			int num = 5;
			int num2 = -1;
			for (int i = 0; i < TitleStats.Length; i++)
			{
				int num3 = Mathf.Max(0, ValueOf(stats, TitleStats[i]) - num);
				if (num3 > num2)
				{
					num2 = num3;
					result = TitleStats[i];
				}
			}
			allocated = Mathf.Max(0, num2);
			return result;
		}

		private static int ValueOf(IsekaiStatAllocation stats, IsekaiStatType stat)
		{
			return stat switch
			{
				IsekaiStatType.Strength => stats.strength, 
				IsekaiStatType.Vitality => stats.vitality, 
				IsekaiStatType.Dexterity => stats.dexterity, 
				IsekaiStatType.Intelligence => stats.intelligence, 
				IsekaiStatType.Wisdom => stats.wisdom, 
				IsekaiStatType.Charisma => stats.charisma, 
				_ => 0, 
			};
		}

		public static Archetype ForStat(IsekaiStatType stat)
		{
			for (int i = 0; i < Archetypes.Count; i++)
			{
				if (!Archetypes[i].IsHybrid && Archetypes[i].LeadsOn(stat))
				{
					return Archetypes[i];
				}
			}
			return null;
		}

		public static Archetype FindHybrid(IsekaiStatType x, IsekaiStatType y)
		{
			for (int i = 0; i < Archetypes.Count; i++)
			{
				Archetype archetype = Archetypes[i];
				if (archetype.IsHybrid && (PairMatches(archetype, x, y) || PairMatches(archetype, y, x)))
				{
					return archetype;
				}
			}
			return null;
		}

		private static bool PairMatches(Archetype arc, IsekaiStatType p, IsekaiStatType s)
		{
			if (!arc.LeadsOn(p))
			{
				return false;
			}
			if (arc.secondaryIsCaster && IsCasterStat(p))
			{
				return false;
			}
			return arc.secondaryIsCaster ? IsCasterStat(s) : (arc.secondary.Value == s);
		}

		private static TitleTier TierFor(int value)
		{
			for (int num = TierThresholds.Length - 1; num >= 1; num--)
			{
				if (value >= TierThresholds[num])
				{
					return (TitleTier)num;
				}
			}
			return TitleTier.None;
		}

		public static int ThresholdFor(TitleTier tier)
		{
			return (tier >= (TitleTier)0 && (int)tier < TierThresholds.Length) ? TierThresholds[(int)tier] : 0;
		}

		public static string NameFor(Archetype archetype, TitleTier tier)
		{
			if (archetype == null || tier == TitleTier.None)
			{
				return null;
			}
			string text = TierWord(tier);
			return (text == null) ? null : (archetype.discipline + " " + text);
		}

		public static string NameFor(BuildTitle title)
		{
			return NameFor(title.archetype, title.tier);
		}

		public static string ColorFor(TitleTier tier)
		{
			return (tier >= (TitleTier)0 && (int)tier < TierColors.Length) ? TierColors[(int)tier] : TierColors[0];
		}

		public static string TierWord(TitleTier tier)
		{
			return (tier >= (TitleTier)0 && (int)tier < TierWords.Length) ? TierWords[(int)tier] : null;
		}
	}
