			Scribe_Values.Look<bool>(ref autoDistributeStats, "autoDistributeStats", false, false);
			Scribe_Values.Look<AuraDisplayMode>(ref auraDisplayMode, "auraDisplayMode", AuraDisplayMode.DefaultFlame, false);
			Scribe_Values.Look<string>(ref auraConstellation, "auraConstellation", (string)null, false);
			Scribe_Values.Look<int>(ref auraFeelCooldownTick, "auraFeelCooldownTick", 0, false);
			Scribe_Values.Look<int>(ref lastLevelUpTick, "lastLevelUpTick", 0, false);
			Scribe_Values.Look<int>(ref lastPointsGainedTick, "lastPointsGainedTick", 0, false);
			Scribe_Values.Look<int>(ref lastCombatTick, "lastCombatTick", 0, false);
			Scribe_Values.Look<bool>(ref hasKilled, "hasKilled", false, false);
			Scribe_Deep.Look<IsekaiStatAllocation>(ref stats, "isekaiStats", Array.Empty<object>());
			if (stats == null)
			{
				stats = new IsekaiStatAllocation();
			}
			Scribe_Deep.Look<IsekaiTitleTracker>(ref titles, "isekaiTitles", Array.Empty<object>());
			if (titles == null)
			{
				titles = new IsekaiTitleTracker();
			}
			Scribe_Deep.Look<PassiveTreeTracker>(ref passiveTree, "passiveTree", Array.Empty<object>());
			if (passiveTree == null)
			{
				passiveTree = new PassiveTreeTracker();
			}
			Scribe_Deep.Look<WeaponMasteryTracker>(ref weaponMastery, "weaponMastery", Array.Empty<object>());
			if (weaponMastery == null)
			{
				weaponMastery = new WeaponMasteryTracker();
			}
			statBonusesDirty = true;
		}

		public override void PostSpawnSetup(bool respawningAfterLoad)
		{
			((ThingComp)this).PostSpawnSetup(respawningAfterLoad);
			compCache[((Thing)base.parent).thingIDNumber] = this;
			try
			{
				if (Pawn?.story?.traits != null)
				{
					List<Trait> allTraits = Pawn.story.traits.allTraits;
					for (int num = allTraits.Count - 1; num >= 0; num--)
					{
						if (((Def)(allTraits[num]?.def?)).defName == "Isekai_SystemGlitch")
						{
							Pawn.story.traits.RemoveTrait(allTraits[num], false);
						}
					}
				}
			}
			catch
			{
			}
			try
			{
				VPEPsycastRankBonus.TryApply(Pawn, this);
			}
			catch
			{
			}
			try
			{
				IsekaiTitleApplier.Refresh(Pawn, this);
			}
			catch
			{
			}
			try
			{
				if (!statsInitialized)
				{
					if (currentLevel <= 1 && stats.TotalAllocatedPoints <= 0 && !ResurrectionPreserver.TryRestore(Pawn, this))
					{
						PawnStatGenerator.InitializePawnStats(Pawn, this);
					}
					statsInitialized = true;
				}
				if (!respawningAfterLoad)
				{
					ResurrectionPreserver.TryRestore(Pawn, this);
				}
				if (!traitsRolled)
				{
					IsekaiTraitHelper.RollRandomTraits(Pawn);
					traitsRolled = true;
				}
				if (passiveTree != null)
				{
					passiveTree.RetroactiveGrant(currentLevel);
				}
				if (currentLevel >= 11)
				{
					Pawn pawn = Pawn;
					if (((pawn != null) ? ((Thing)pawn).Faction : null) == null || !((Thing)Pawn).Faction.IsPlayer)
					{
						if (string.IsNullOrEmpty(passiveTree?.assignedTree))
						{
							TreeAutoAssigner.AssignTreeProgression(passiveTree, currentLevel, stats, Pawn);
						}
						else
						{
							TreeAutoAssigner.AutoSpendAccumulated(passiveTree);
						}
					}
				}
				ConstellationHediffs.Sync(Pawn, this);
			}
			catch (Exception ex)
			{
				Pawn pawn2 = Pawn;
				Log.Warning("[Isekai Leveling] PostSpawnSetup error for " + ((pawn2 != null) ? ((Entity)pawn2).LabelShort : null) + ": " + ex.Message);
			}
		}

