		{
			//IL_0003: Unknown result type (might be due to invalid IL or missing references)
			((ThingComp)this).PostDeSpawn(map, mode);
			try
			{
				int thingIDNumber = ((Thing)base.parent).thingIDNumber;
				compCache.Remove(thingIDNumber);
