		public override void CompTickRare()
		{
			((ThingComp)this).CompTickRare();
			try
			{
				if (Pawn != null && !Pawn.Dead)
				{
					FlushPendingXP();
					if (currentXP >= XPToNextLevel && currentLevel < (IsekaiMod.Settings?.MaxLevel ?? 1600))
					{
						ProcessDeferredLevelUps();
					}
					if (((Thing)Pawn).Map != null)
					{
						PassiveTreeTracker.UpdateColonistCountCache(((Thing)Pawn).Map);
					}
					IsekaiTitleApplier.Refresh(Pawn, this);
					ConstellationHediffs.Sync(Pawn, this);
				}
			}
			catch (Exception ex)
			{
				Pawn pawn = Pawn;
				Log.Warning("[Isekai Leveling] CompTickRare error for " + ((pawn != null) ? ((Entity)pawn).LabelShort : null) + ": " + ex.Message);
			}
		}

		public void AutoDistributeByClass()
		{
			if (stats.availableStatPoints <= 0)
			{
				return;
			}
			int[] array = new int[6] { 1, 1, 1, 1, 1, 1 };
			string text = passiveTree?.assignedTree;
			if (!string.IsNullOrEmpty(text))
			{
				(IsekaiStatType, IsekaiStatType)? classStatAffinity = GetClassStatAffinity(text);
				if (classStatAffinity.HasValue)
				{
					array[(int)classStatAffinity.Value.Item1] += 2;
					array[(int)classStatAffinity.Value.Item2]++;
				}
			}
			List<IsekaiStatType> list = new List<IsekaiStatType>();
			for (int i = 0; i < 6; i++)
			{
				for (int j = 0; j < array[i]; j++)
				{
					list.Add((IsekaiStatType)i);
				}
			}
			int effectiveMaxStat = IsekaiStatAllocation.GetEffectiveMaxStat();
			int num = 0;
			int num2 = stats.availableStatPoints * list.Count;
			while (stats.availableStatPoints > 0 && num2 > 0)
			{
				IsekaiStatType stat = list[num % list.Count];
				if (stats.GetStat(stat) < effectiveMaxStat)
				{
					stats.SetStat(stat, stats.GetStat(stat) + 1);
					stats.availableStatPoints--;
				}
				num++;
				num2--;
			}
			statBonusesDirty = true;
		}

		private static (IsekaiStatType primary, IsekaiStatType secondary)? GetClassStatAffinity(string className)
		{
			return className switch
			{
				"Knight" => (IsekaiStatType.Strength, IsekaiStatType.Vitality), 
				"Berserker" => (IsekaiStatType.Strength, IsekaiStatType.Strength), 
				"Duelist" => (IsekaiStatType.Dexterity, IsekaiStatType.Strength), 
				"Ranger" => (IsekaiStatType.Dexterity, IsekaiStatType.Wisdom), 
				"Paladin" => (IsekaiStatType.Vitality, IsekaiStatType.Charisma), 
				"Survivor" => (IsekaiStatType.Vitality, IsekaiStatType.Dexterity), 
				"Mage" => (IsekaiStatType.Intelligence, IsekaiStatType.Wisdom), 
				"Alchemist" => (IsekaiStatType.Intelligence, IsekaiStatType.Wisdom), 
				"Crafter" => (IsekaiStatType.Intelligence, IsekaiStatType.Dexterity), 
				"Sage" => (IsekaiStatType.Wisdom, IsekaiStatType.Intelligence), 
				"Beastmaster" => (IsekaiStatType.Wisdom, IsekaiStatType.Charisma), 
				"Leader" => (IsekaiStatType.Charisma, IsekaiStatType.Wisdom), 
				_ => null, 
			};
		}

		public void GainXP(int amount, string source = null)
		{
			Pawn pawn = Pawn;
			if (((pawn != null) ? ((Thing)pawn).Faction : null) != null && ((Thing)Pawn).Faction.IsPlayer && currentLevel < (IsekaiMod.Settings?.MaxLevel ?? 1600))
			{
				int ticksGame = Find.TickManager.TicksGame;
				if (amount < 20 && ticksGame - lastXPFlushTick < 60)
				{
					pendingXP += amount;
					return;
				}
				int rawAmount = amount + pendingXP;
				pendingXP = 0;
				lastXPFlushTick = ticksGame;
				ProcessXPGain(rawAmount, source);
			}
		}

		public void FlushPendingXP()
		{
			if (pendingXP > 0)
			{
				int rawAmount = pendingXP;
				pendingXP = 0;
				lastXPFlushTick = Find.TickManager.TicksGame;
				ProcessXPGain(rawAmount, "Combat");
			}
		}

		private void ProcessDeferredLevelUps()
		{
			int num = IsekaiMod.Settings?.MaxLevel ?? 1600;
			bool flag = IsekaiMod.Settings?.EnableXPNotifications ?? true;
			int num2 = 0;
			while (currentXP >= XPToNextLevel && currentLevel < num && num2 < 50)
			{
				LevelUp();
				num2++;
			}
		}

		private void ProcessXPGain(int rawAmount, string source)
		{
			if (rawAmount <= 0)
			{
				return;
			}
			float num = IsekaiMod.Settings?.XPMultiplier ?? 3f;
			int num2 = IsekaiMod.Settings?.MaxLevel ?? 1600;
			bool flag = IsekaiMod.Settings?.EnableXPNotifications ?? true;
			if (currentLevel >= num2)
			{
				return;
			}
			int num3 = Mathf.RoundToInt((float)rawAmount * num);
			float xPMultiplier = IsekaiTraitHelper.GetXPMultiplier(Pawn, currentLevel, source);
			if (xPMultiplier != 1f)
			{
				num3 = Mathf.RoundToInt((float)num3 * xPMultiplier);
			}
			if (rawAmount > 0 && num3 <= 0)
			{
				num3 = 1;
			}
			currentXP += num3;
			if (flag && ((Thing)Pawn).Spawned)
			{
				if (num3 >= 15)
				{
					IsekaiAnimations.PlayXPGainEffect(Pawn, num3, source);
				}
				else if (num3 >= 5)
				{
					IsekaiAnimations.PlaySmallXPEffect(Pawn, num3);
				}
			}
			int num4 = 0;
			while (currentXP >= XPToNextLevel && currentLevel < num2 && num4 < 50)
			{
				LevelUp();
				num4++;
			}
			if (isSharingBondXP || rawAmount <= 0 || Pawn?.relations == null)
			{
				return;
			}
			int num5 = Mathf.RoundToInt((float)rawAmount * 0.3f);
			if (num5 <= 0)
			{
				return;
			}
			isSharingBondXP = true;
			try
			{
				foreach (DirectPawnRelation directRelation in Pawn.relations.DirectRelations)
				{
					if (directRelation.def == PawnRelationDefOf.Bond && directRelation.otherPawn != null && !directRelation.otherPawn.Dead && !((Thing)directRelation.otherPawn).Destroyed)
					{
						ThingCompUtility.TryGetComp<MobRankComponent>((Thing)(object)directRelation.otherPawn)?.GainXP(num5, "Bond");
					}
				}
				if (!ModCompatibility.RimWorldOfMagicActive || Pawn == null)
				{
					return;
				}
				foreach (Pawn item in RoMCompatibility.GetGolemsOwnedBy(Pawn))
				{
					ThingCompUtility.TryGetComp<MobRankComponent>((Thing)(object)item)?.GainXP(num5, "Golem");
				}
			}
			finally
			{
				isSharingBondXP = false;
			}
		}

		private void LevelUp()
		{
			//IL_02a0: Unknown result type (might be due to invalid IL or missing references)
			//IL_02a7: Unknown result type (might be due to invalid IL or missing references)
			int level = currentLevel;
			currentXP -= XPToNextLevel;
			currentLevel++;
			stats.OnLevelUp();
			int bonusStatPoints = IsekaiTraitHelper.GetBonusStatPoints(Pawn, currentLevel);
			if (bonusStatPoints > 0)
			{
				stats.availableStatPoints += bonusStatPoints;
			}
			passiveTree.OnLevelUp(currentLevel, Pawn);
			statBonusesDirty = true;
			lastLevelUpTick = Find.TickManager.TicksGame;
			lastPointsGainedTick = lastLevelUpTick;
			IsekaiMoods.Gain(Pawn, "Isekai_LevelUp");
			ResurrectionPreserver.CacheSnapshot(Pawn);
			if (autoDistributeStats && stats.availableStatPoints > 0)
			{
				AutoDistributeByClass();
			}
			if (currentLevel >= 11)
			{
				Pawn pawn = Pawn;
				if (((pawn != null) ? ((Thing)pawn).Faction : null) == null || !((Thing)Pawn).Faction.IsPlayer)
				{
					if (string.IsNullOrEmpty(passiveTree.assignedTree))
					{
						TreeAutoAssigner.AssignTreeProgression(passiveTree, currentLevel, stats, Pawn);
					}
					else
					{
						TreeAutoAssigner.AutoSpendAccumulated(passiveTree);
					}
				}
			}
			if (GetRankFromLevel(level) != GetRankFromLevel(currentLevel))
			{
				PawnStatGenerator.UpdateRankTraitFromStats(Pawn, this);
				IsekaiMoods.GainRankUp(Pawn, GetRank());
			}
			if (IsekaiMod.Settings.EnableLevelUpNotifications && (currentLevel <= 10 || currentLevel % 10 == 0 || currentLevel - lastNotifiedLevel >= 10))
			{
				lastNotifiedLevel = currentLevel;
				string text = ((Entity)Pawn).LabelShort + " Leveled Up!";
				string text2 = $"{((Entity)Pawn).LabelShort} has reached level {currentLevel}!\n\n" + $"They have {stats.availableStatPoints} stat point(s) to spend.";
				if (IsekaiMod.Settings.UseLevelUpNotice)
				{
					Messages.Message(text + " (Lv" + currentLevel + ")", LookTargets.op_Implicit((Thing)(object)Pawn), MessageTypeDefOf.PositiveEvent, false);
				}
				else
				{
					Find.LetterStack.ReceiveLetter(TaggedString.op_Implicit(text), TaggedString.op_Implicit(text2), LetterDefOf.PositiveEvent, LookTargets.op_Implicit((Thing)(object)Pawn), (Faction)null, (Quest)null, (List<ThingDef>)null, (string)null, 0, true);
				}
			}
			if (((Thing)Pawn).Spawned && (currentLevel <= 10 || currentLevel % 5 == 0))
			{
				IsekaiAnimations.PlayLevelUpEffect(Pawn, currentLevel);
			}
			if (currentLevel <= 10 || currentLevel % 25 == 0 || currentLevel - lastLoggedLevel >= 25)
			{
				lastLoggedLevel = currentLevel;
				Log.Message($"[Isekai Leveling] {((Entity)Pawn).LabelShort} reached level {currentLevel}");
			}
		}

		public void DevAddLevel(int levels)
		{
			//IL_01ae: Unknown result type (might be due to invalid IL or missing references)
			//IL_01d3: Unknown result type (might be due to invalid IL or missing references)
			int level = currentLevel;
			for (int i = 0; i < levels; i++)
			{
				if (currentLevel >= IsekaiMod.Settings.MaxLevel)
				{
					break;
				}
				currentLevel++;
				stats.OnLevelUp();
				int bonusStatPoints = IsekaiTraitHelper.GetBonusStatPoints(Pawn, currentLevel);
				if (bonusStatPoints > 0)
				{
					stats.availableStatPoints += bonusStatPoints;
				}
				passiveTree.OnLevelUp(currentLevel, Pawn);
			}
			currentXP = 0;
			statBonusesDirty = true;
			if (autoDistributeStats && stats.availableStatPoints > 0)
			{
				AutoDistributeByClass();
			}
			if (currentLevel >= 11)
			{
				Pawn pawn = Pawn;
				if (((pawn != null) ? ((Thing)pawn).Faction : null) == null || !((Thing)Pawn).Faction.IsPlayer)
				{
					if (string.IsNullOrEmpty(passiveTree?.assignedTree))
					{
						TreeAutoAssigner.AssignTreeProgression(passiveTree, currentLevel, stats, Pawn);
					}
					else
					{
						TreeAutoAssigner.AutoSpendAccumulated(passiveTree);
					}
				}
			}
			if (GetRankFromLevel(level) != GetRankFromLevel(currentLevel))
			{
				PawnStatGenerator.UpdateRankTraitFromStats(Pawn, this);
			}
			if (((Thing)Pawn).Spawned)
			{
				MoteMaker.ThrowText(((Thing)Pawn).DrawPos, ((Thing)Pawn).Map, $"DEV: Level {currentLevel}", Color.green, -1f);
			}
			Log.Message($"[Isekai Leveling] DEV: {((Entity)Pawn).LabelShort} set to level {currentLevel}");
		}

		public float GetStatBonus(StatDef stat)
		{
			if (statBonusesDirty)
			{
				RecalculateStatBonuses();
			}
			float value;
			return cachedStatBonuses.TryGetValue(stat, out value) ? value : 0f;
		}

		private void RecalculateStatBonuses()
		{
			cachedStatBonuses.Clear();
			statBonusesDirty = false;
		}

		public string GetRankString()
		{
			return GetRankFromLevel(currentLevel);
		}

