		{
			return MobRankUtility.RankStringFromLevel(level);
		}

		public MobRankTier GetRank()
		{
			return MobRankUtility.TierFromLevel(currentLevel);
		}

		public override string CompInspectStringExtra()
		{
			if (!IsekaiLevelingSettings.showMobRanks)
			{
				return null;
			}
			return $"Rank: {GetRankString()} - Level {currentLevel}";
		}
	}
