	[StaticConstructorOnStartup]
	public static class IsekaiMoods
	{
		public const string LevelUp = "Isekai_LevelUp";

		public const string RankUp = "Isekai_RankUp";

		public const string NodeUnlocked = "Isekai_NodeUnlocked";

		public const string PathFound = "Isekai_PathFound";

		public const string StarTouched = "Isekai_StarTouched";

		public const string ApexReached = "Isekai_ApexReached";

		public const string NationAscended = "Isekai_NationAscended";

		public const string GiantSlayer = "Isekai_GiantSlayer";

		public const string SlewElite = "Isekai_SlewElite";

		public const string BossSlain = "Isekai_BossSlain";

		public const string FirstBlood = "Isekai_FirstBlood";

		public const string Humiliated = "Isekai_Humiliated";

		public const string Outclassed = "Isekai_Outclassed";

		public const string CrushingPresence = "Isekai_CrushingPresence";

		public const string BrokenWill = "Isekai_BrokenWill";

		public const string ForgeSuccess = "Isekai_ForgeSuccess";

		public const string ForgeDestroyed = "Isekai_ForgeDestroyed";

		public const string ForgeDowngrade = "Isekai_ForgeDowngrade";

		public const string RuneSocketed = "Isekai_RuneSocketed";

		public const string RuneShattered = "Isekai_RuneShattered";

		public const string WeaponMastery = "Isekai_WeaponMastery";

		public const string QuestComplete = "Isekai_QuestComplete";

		public const string QuestFailed = "Isekai_QuestFailed";

		public const string BountyClaimed = "Isekai_BountyClaimed";

		public const string LegendFallen = "Isekai_LegendFallen";

		private static readonly Dictionary<string, ThoughtDef> DefCache = new Dictionary<string, ThoughtDef>();

		private static ThoughtDef GetDef(string defName)
		{
			if (DefCache.TryGetValue(defName, out var value))
			{
				return value;
			}
			value = DefDatabase<ThoughtDef>.GetNamedSilentFail(defName);
			if (value == null)
			{
				Log.WarningOnce("[Isekai] Mood thought def not found: '" + defName + "'", defName.GetHashCode());
			}
			DefCache[defName] = value;
			return value;
		}

		private static bool CanFeel(Pawn pawn)
		{
			if (!IsekaiLevelingSettings.enableIsekaiMoodThoughts)
			{
				return false;
			}
			if (pawn == null || pawn.Dead)
			{
				return false;
			}
			if (pawn.needs?.mood?.thoughts?.memories == null)
			{
				return false;
			}
			return true;
		}

		public static void Gain(Pawn pawn, string defName, int stage = 0)
		{
			try
			{
				if (!CanFeel(pawn))
				{
					return;
				}
				ThoughtDef def = GetDef(defName);
				if (def == null)
				{
					return;
				}
				int num = (def.stages?.Count ?? 1) - 1;
				if (num >= 0)
				{
					if (stage < 0)
					{
						stage = 0;
					}
					else if (stage > num)
					{
						stage = num;
					}
					Thought_Memory val = ThoughtMaker.MakeThought(def, stage);
					pawn.needs.mood.thoughts.memories.TryGainMemory(val, (Pawn)null);
				}
			}
			catch (Exception ex)
			{
				Log.WarningOnce("[Isekai] Failed to apply mood '" + defName + "': " + ex.Message, defName.GetHashCode() ^ 0x47);
			}
		}

		public static void GainColonyWide(Map map, string defName, int stage = 0, Pawn except = null)
		{
			try
			{
				if (!IsekaiLevelingSettings.enableIsekaiMoodThoughts)
				{
					return;
				}
				List<Pawn> list = ((map != null) ? map.mapPawns.FreeColonistsSpawned : PawnsFinder.AllMaps_FreeColonists);
				if (list == null)
				{
					return;
				}
				for (int i = 0; i < list.Count; i++)
				{
					Pawn val = list[i];
					if (val != null && val != except)
					{
						Gain(val, defName, stage);
					}
				}
			}
			catch (Exception ex)
			{
				Log.WarningOnce("[Isekai] Colony-wide mood '" + defName + "' failed: " + ex.Message, defName.GetHashCode() ^ 0x391);
			}
		}

		public static void GainRankUp(Pawn pawn, MobRankTier newRank)
		{
			Gain(pawn, "Isekai_RankUp", (int)newRank);
			if (newRank >= MobRankTier.SSS)
			{
				Gain(pawn, "Isekai_ApexReached");
			}
			if (newRank >= MobRankTier.Nation)
			{
				GainColonyWide(((Thing)pawn).MapHeld, "Isekai_NationAscended", 0, pawn);
			}
		}

		public static void GainGiantSlayer(Pawn killer, int rankGap)
		{
			if (rankGap > 0)
			{
				int stage = ((rankGap >= 3) ? 2 : ((rankGap == 2) ? 1 : 0));
				Gain(killer, "Isekai_GiantSlayer", stage);
			}
		}

		public static void GainLegendFallen(Pawn deceased, Map preKillMap = null)
		{
			if (deceased == null)
			{
				return;
			}
			IsekaiComponent cached = IsekaiComponent.GetCached(deceased);
			if (cached != null)
			{
				MobRankTier rank = cached.GetRank();
				if (rank >= MobRankTier.B)
				{
					int stage = ((rank >= MobRankTier.S) ? 1 : 0);
					GainColonyWide(preKillMap ?? ((Thing)deceased).MapHeld, "Isekai_LegendFallen", stage, deceased);
				}
			}
		}
	}
	public enum IsekaiStatType
	{
		Strength,
		Dexterity,
		Vitality,
		Intelligence,
		Wisdom,
		Charisma
	}
	public class IsekaiStatAllocation : IExposable
	{
		public int strength = 5;

		public int dexterity = 5;

		public int vitality = 5;

		public int intelligence = 5;

		public int wisdom = 5;

		public int charisma = 5;

		public int availableStatPoints = 0;

		public const int BASE_STAT_VALUE = 5;

		public const int MAX_STAT_VALUE = 9999;

		public const int STAT_POINTS_PER_LEVEL = 3;

		public int TotalAllocatedPoints => strength - 5 + (dexterity - 5) + (vitality - 5) + (intelligence - 5) + (wisdom - 5) + (charisma - 5);

		public static int GetEffectiveMaxStat()
		{
			if (IsekaiMod.Settings == null)
			{
				return 9999;
			}
			return (IsekaiMod.Settings.MaxStatCap > 0) ? IsekaiMod.Settings.MaxStatCap : 9999;
		}

		public void ExposeData()
		{
			Scribe_Values.Look<int>(ref strength, "strength", 5, false);
			Scribe_Values.Look<int>(ref dexterity, "dexterity", 5, false);
			Scribe_Values.Look<int>(ref vitality, "vitality", 5, false);
			Scribe_Values.Look<int>(ref intelligence, "intelligence", 5, false);
			Scribe_Values.Look<int>(ref wisdom, "wisdom", 5, false);
			Scribe_Values.Look<int>(ref charisma, "charisma", 5, false);
			Scribe_Values.Look<int>(ref availableStatPoints, "availableStatPoints", 0, false);
		}

		public int GetStat(IsekaiStatType stat)
		{
			return stat switch
			{
				IsekaiStatType.Strength => strength, 
				IsekaiStatType.Dexterity => dexterity, 
				IsekaiStatType.Vitality => vitality, 
				IsekaiStatType.Intelligence => intelligence, 
				IsekaiStatType.Wisdom => wisdom, 
				IsekaiStatType.Charisma => charisma, 
				_ => 5, 
			};
		}

		public void SetStat(IsekaiStatType stat, int value)
		{
			int effectiveMaxStat = GetEffectiveMaxStat();
			value = Math.Max(1, Math.Min(effectiveMaxStat, value));
			switch (stat)
			{
			case IsekaiStatType.Strength:
				strength = value;
				break;
			case IsekaiStatType.Dexterity:
				dexterity = value;
				break;
			case IsekaiStatType.Vitality:
				vitality = value;
				break;
			case IsekaiStatType.Intelligence:
				intelligence = value;
				break;
			case IsekaiStatType.Wisdom:
				wisdom = value;
				break;
			case IsekaiStatType.Charisma:
				charisma = value;
				break;
			}
		}

		public bool AllocatePoint(IsekaiStatType stat)
		{
			if (availableStatPoints <= 0)
			{
				return false;
			}
			if (GetStat(stat) >= GetEffectiveMaxStat())
			{
				return false;
			}
			SetStat(stat, GetStat(stat) + 1);
			availableStatPoints--;
			return true;
		}

		public int AllocatePoints(IsekaiStatType stat, int amount)
		{
			int num = 0;
			int effectiveMaxStat = GetEffectiveMaxStat();
			for (int i = 0; i < amount; i++)
			{
				if (availableStatPoints <= 0)
				{
					break;
				}
				if (GetStat(stat) >= effectiveMaxStat)
				{
					break;
				}
				SetStat(stat, GetStat(stat) + 1);
				availableStatPoints--;
				num++;
			}
			return num;
		}

		public static int GetBulkAmount()
		{
			bool shift = Event.current.shift;
			bool control = Event.current.control;
			if (control && shift)
			{
				return 100;
			}
			if (control)
			{
				return 20;
			}
			if (shift)
			{
				return 5;
			}
			return 1;
		}

		public void OnLevelUp()
		{
			availableStatPoints += IsekaiLevelingSettings.skillPointsPerLevel;
		}

		public float GetStatMultiplier(IsekaiStatType stat)
		{
			int stat2 = GetStat(stat);
			return 1f + (float)(stat2 - 5) * 0.02f;
		}

		public float GetStatBonus(IsekaiStatType stat, float perPointBonus)
		{
			int stat2 = GetStat(stat);
			return (float)(stat2 - 5) * perPointBonus;
		}
	}
