		private static float SoftCapDisplay(float value, float min, float cap)
		{
			if (value < min)
			{
				return min;
			}
			if (value <= cap)
			{
				return value;
			}
			float num = Mathf.Max(0.5f, cap * 0.5f);
			return cap + num * Mathf.Log(1f + (value - cap) / num);
		}

