		public static bool HasTrait(Pawn pawn, string traitDefName)
		{
			if (pawn?.story?.traits == null)
			{
				return false;
			}
			List<Trait> allTraits = pawn.story.traits.allTraits;
			for (int i = 0; i < allTraits.Count; i++)
			{
				if (((Def)allTraits[i].def).defName == traitDefName)
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsIsekaiTrait(string defName)
		{
			return AllIsekaiTraitDefNames.Contains(defName);
		}

		public static List<string> GetIsekaiTraits(Pawn pawn)
		{
			List<string> list = new List<string>();
			if (pawn?.story?.traits == null)
			{
				return list;
			}
			List<Trait> allTraits = pawn.story.traits.allTraits;
			for (int i = 0; i < allTraits.Count; i++)
			{
				if (AllIsekaiTraitDefNames.Contains(((Def)allTraits[i].def).defName))
				{
					list.Add(((Def)allTraits[i].def).defName);
				}
			}
			return list;
		}

		public static float GetXPMultiplier(Pawn pawn, int currentLevel, string xpSource = null)
		{
			if (pawn?.story?.traits == null)
			{
				return 1f;
			}
			float num = 1f;
			if (HasTrait(pawn, "Isekai_Protagonist"))
			{
				num *= 10f;
			}
			else if (HasTrait(pawn, "Isekai_Antagonist"))
			{
				num *= 8f;
			}
			else if (HasTrait(pawn, "Isekai_Reincarnated"))
			{
				num *= 5f;
			}
			else if (HasTrait(pawn, "Isekai_Regressor"))
			{
				num *= 4f;
			}
			else if (HasTrait(pawn, "Isekai_SummonedHero"))
			{
				num *= 3f;
			}
			if (HasTrait(pawn, "Isekai_Prodigy"))
			{
				num *= 2f;
			}
			if (HasTrait(pawn, "Isekai_QuickLearner"))
			{
				num *= 1.5f;
			}
			if (HasTrait(pawn, "Isekai_SlowGrind"))
			{
				num *= 0.5f;
			}
			if (HasTrait(pawn, "Isekai_CursedLuck"))
			{
				num *= 2f;
			}
			if (HasTrait(pawn, "Isekai_EchoOfDefeat"))
			{
				num *= 1.1f;
			}
			if (HasTrait(pawn, "Isekai_EchoOfDefeat"))
			{
				IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
				if (cached != null && cached.echoOfDefeatActiveUntilTick > Find.TickManager.TicksGame)
				{
					num *= 2f;
				}
			}
			if (HasTrait(pawn, "Isekai_LateBloomer"))
			{
				num = ((currentLevel >= 101) ? (num * 3f) : ((currentLevel >= 51) ? (num * 2f) : ((currentLevel >= 26) ? (num * 1.5f) : ((currentLevel < 11) ? (num * 0.5f) : (num * 1f)))));
			}
			if (HasTrait(pawn, "Isekai_BattleManiac"))
			{
				num = ((!(xpSource == "Combat") && !(xpSource == "Kill")) ? (num * 0.1f) : (num * 3f));
			}
			if (HasTrait(pawn, "Isekai_HollowCore"))
			{
				num *= 3f;
			}
			if (HasTrait(pawn, "Isekai_FragileVessel"))
			{
				num *= 2.5f;
			}
			return num;
		}

		public static int GetBonusStatPoints(Pawn pawn, int newLevel)
		{
			if (pawn?.story?.traits == null)
			{
				return 0;
			}
			int num = 0;
			if (HasTrait(pawn, "Isekai_SummonedHero"))
			{
				num++;
			}
			if (HasTrait(pawn, "Isekai_SlowGrind"))
			{
				num += 2;
			}
			if (HasTrait(pawn, "Isekai_PowerSpike") && newLevel % 10 == 0)
			{
				num += 5;
			}
			if (HasTrait(pawn, "Isekai_SealedPower") && newLevel > 25)
			{
				num += Math.Min(2, IsekaiLevelingSettings.skillPointsPerLevel);
			}
			return num;
		}

		public static int GetStarPointsForLevel(Pawn pawn, int newLevel)
		{
			if (pawn?.story?.traits == null)
			{
				return (newLevel % 5 == 0) ? 1 : 0;
			}
			if (HasTrait(pawn, "Isekai_HollowCore"))
			{
				return 0;
			}
			if (HasTrait(pawn, "Isekai_SealedPower") && newLevel < 25)
			{
				return 0;
			}
			int num = 0;
			if (HasTrait(pawn, "Isekai_Reincarnated"))
			{
				if (newLevel % 3 == 0)
				{
					num++;
				}
			}
			else if (newLevel % 5 == 0)
			{
				num++;
			}
			if (HasTrait(pawn, "Isekai_NaturalTalent") && newLevel % 5 == 0)
			{
				num++;
			}
			if (HasTrait(pawn, "Isekai_SealedPower") && newLevel > 25 && newLevel % 5 == 0)
			{
				num += 2;
			}
			return num;
		}

		public static float GetStatEffectiveness(Pawn pawn, IsekaiStatType statType, int level)
		{
			if (pawn?.story?.traits == null)
			{
				return 1f;
			}
			float num = 1f;
			switch (statType)
			{
			case IsekaiStatType.Strength:
				if (HasTrait(pawn, "Isekai_Mighty"))
				{
					num *= 1.5f;
				}
				if (HasTrait(pawn, "Isekai_Agile"))
				{
					num *= 0.75f;
				}
				if (HasTrait(pawn, "Isekai_Genius"))
				{
					num *= 0.5f;
				}
				break;
			case IsekaiStatType.Dexterity:
				if (HasTrait(pawn, "Isekai_Agile"))
				{
					num *= 1.5f;
				}
				if (HasTrait(pawn, "Isekai_Mighty"))
				{
					num *= 0.75f;
				}
				break;
			case IsekaiStatType.Vitality:
				if (HasTrait(pawn, "Isekai_Resilient"))
				{
					num *= 1.5f;
				}
				if (HasTrait(pawn, "Isekai_Enlightened"))
				{
					num *= 0.75f;
				}
				if (HasTrait(pawn, "Isekai_Genius"))
				{
					num *= 0.5f;
				}
				if (HasTrait(pawn, "Isekai_FragileVessel"))
				{
					num *= 0.5f;
				}
				if (HasTrait(pawn, "Isekai_GlassCannon"))
				{
					num *= 0.5f;
				}
				break;
			case IsekaiStatType.Intelligence:
				if (HasTrait(pawn, "Isekai_Brilliant"))
				{
					num *= 1.5f;
				}
				if (HasTrait(pawn, "Isekai_SilverTongue"))
				{
					num *= 0.75f;
				}
				if (HasTrait(pawn, "Isekai_Genius"))
				{
					num *= 2f;
				}
				break;
			case IsekaiStatType.Wisdom:
				if (HasTrait(pawn, "Isekai_Enlightened"))
				{
					num *= 1.5f;
				}
				if (HasTrait(pawn, "Isekai_Resilient"))
				{
					num *= 0.75f;
				}
				if (HasTrait(pawn, "Isekai_Genius"))
				{
					num *= 2f;
				}
				break;
			case IsekaiStatType.Charisma:
				if (HasTrait(pawn, "Isekai_SilverTongue"))
				{
					num *= 1.5f;
				}
				if (HasTrait(pawn, "Isekai_Brilliant"))
				{
					num *= 0.75f;
				}
				break;
			}
			if (HasTrait(pawn, "Isekai_AwakenedPotential"))
			{
				num = ((level < 25) ? (num * 0.9f) : (num * 1.5f));
			}
			if (HasTrait(pawn, "Isekai_SealedPower") && level < 25)
			{
				num *= 0.7f;
			}
			return num;
		}

		public static void ApplyOneTimeEffects(Pawn pawn, string traitDefName)
		{
			IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
			if (cached == null)
			{
				return;
			}
			if (!(traitDefName == "Isekai_Reincarnated"))
			{
				if (traitDefName == "Isekai_Regressor")
				{
				}
				return;
			}
			cached.currentLevel = 1;
			cached.currentXP = 0;
			cached.stats.strength = 5;
			cached.stats.dexterity = 5;
			cached.stats.vitality = 5;
			cached.stats.intelligence = 5;
			cached.stats.wisdom = 5;
			cached.stats.charisma = 5;
			cached.stats.availableStatPoints = 0;
			if (cached.passiveTree != null)
			{
				cached.passiveTree.availablePoints += 10;
			}
		}

		public static bool AddIsekaiTrait(Pawn pawn, string traitDefName)
		{
			//IL_0134: Unknown result type (might be due to invalid IL or missing references)
			//IL_013a: Expected O, but got Unknown
			if (pawn?.story?.traits == null)
			{
				return false;
			}
			TraitDef namedSilentFail = DefDatabase<TraitDef>.GetNamedSilentFail(traitDefName);
			if (namedSilentFail == null)
			{
				Log.Warning("[Isekai Leveling] Trait def not found: " + traitDefName);
				return false;
			}
			if (HasTrait(pawn, traitDefName))
			{
				return false;
			}
			if (namedSilentFail.conflictingTraits != null)
			{
				foreach (TraitDef conflictingTrait in namedSilentFail.conflictingTraits)
				{
					if (HasTrait(pawn, ((Def)conflictingTrait).defName))
					{
						return false;
					}
				}
			}
			List<Trait> allTraits = pawn.story.traits.allTraits;
			for (int i = 0; i < allTraits.Count; i++)
			{
				if (allTraits[i].def.conflictingTraits != null && allTraits[i].def.conflictingTraits.Contains(namedSilentFail))
				{
					return false;
				}
			}
			Trait val = new Trait(namedSilentFail, 0, true);
			pawn.story.traits.GainTrait(val, false);
			ApplyOneTimeEffects(pawn, traitDefName);
			return true;
		}

		public static bool RemoveIsekaiTrait(Pawn pawn, string traitDefName)
		{
			if (pawn?.story?.traits == null)
			{
				return false;
			}
			List<Trait> allTraits = pawn.story.traits.allTraits;
			for (int num = allTraits.Count - 1; num >= 0; num--)
			{
				if (((Def)allTraits[num].def).defName == traitDefName)
				{
					pawn.story.traits.RemoveTrait(allTraits[num], false);
					return true;
				}
			}
			return false;
		}

		public static void RollRandomTraits(Pawn pawn)
		{
			if (pawn?.story?.traits == null)
			{
				return;
			}
			float value = Rand.Value;
			int num = ((!(value < 0.8f)) ? ((value < 0.95f) ? 1 : 2) : 0);
			if (num == 0)
			{
				return;
			}
			List<(string, float)> list = new List<(string, float)>();
			foreach (string rollableTrait in RollableTraits)
			{
				TraitDef namedSilentFail = DefDatabase<TraitDef>.GetNamedSilentFail(rollableTrait);
				if (namedSilentFail == null)
				{
					continue;
				}
				bool flag = false;
				if (namedSilentFail.conflictingTraits != null)
				{
					foreach (TraitDef conflictingTrait in namedSilentFail.conflictingTraits)
					{
						if (HasTrait(pawn, ((Def)conflictingTrait).defName))
						{
							flag = true;
							break;
						}
					}
				}
				if (!flag && !HasTrait(pawn, rollableTrait))
				{
					float value2;
					float item = (TraitCommonality.TryGetValue(rollableTrait, out value2) ? value2 : 0.5f);
					list.Add((rollableTrait, item));
				}
			}
			for (int i = 0; i < num; i++)
			{
				if (list.Count <= 0)
				{
					break;
				}
				float num2 = 0f;
				foreach (var item2 in list)
				{
					num2 += item2.Item2;
				}
				float num3 = Rand.Value * num2;
				float num4 = 0f;
				string text = null;
				for (int j = 0; j < list.Count; j++)
				{
					num4 += list[j].Item2;
					if (num3 <= num4)
					{
						text = list[j].Item1;
						break;
					}
				}
				if (text == null)
				{
					text = list[list.Count - 1].Item1;
				}
				if (!AddIsekaiTrait(pawn, text))
				{
					continue;
				}
				TraitDef namedSilentFail2 = DefDatabase<TraitDef>.GetNamedSilentFail(text);
				HashSet<string> conflicts = new HashSet<string>();
				conflicts.Add(text);
				if (namedSilentFail2?.conflictingTraits != null)
				{
					foreach (TraitDef conflictingTrait2 in namedSilentFail2.conflictingTraits)
					{
						conflicts.Add(((Def)conflictingTrait2).defName);
					}
				}
				list.RemoveAll(((string defName, float weight) c) => conflicts.Contains(c.defName));
			}
		}
	}
