		public static bool ClampToLevelCap(Pawn pawn, IsekaiComponent comp)
		{
			if (pawn == null || comp == null || comp.stats == null)
			{
				return false;
			}
			int num = IsekaiMod.Settings?.MaxLevel ?? 1600;
			if (comp.currentLevel <= num)
			{
				return false;
			}
			if (comp.forgeLocked)
			{
				return false;
			}
			string rank = MobRankUtility.RankStringFromLevel(num);
			PawnStatGenerator.GenerateStatsForRank(rank, comp.stats, pawn);
			comp.currentLevel = num;
			comp.stats.availableStatPoints = 0;
			comp.InvalidateStatCache();
			PawnStatGenerator.UpdateRankTraitFromStats(pawn, comp);
			return true;
		}

		public static bool TryPromoteEmpireLeader()
		{
			try
			{
				if (Find.FactionManager == null)
				{
					return false;
				}
				Faction val = null;
				foreach (Faction item in Find.FactionManager.AllFactionsListForReading)
				{
					if (item?.def == null || !(((Def)item.def).defName == "Empire"))
					{
						continue;
					}
					val = item;
					break;
				}
				if (val?.leader == null)
				{
					return false;
				}
				Pawn leader = val.leader;
				IsekaiComponent cached = IsekaiComponent.GetCached(leader);
				if (cached == null)
				{
					return false;
				}
				if (cached.currentLevel >= 800)
				{
					return false;
				}
				if (cached.forgeLocked)
				{
					return false;
				}
				int num = 800;
				int num2 = IsekaiMod.Settings?.MaxLevel ?? 1600;
				if (num > num2)
				{
					num = num2;
				}
				PawnStatGenerator.GenerateStatsForRank(MobRankUtility.RankStringFromLevel(num), cached.stats, leader);
				cached.currentLevel = num;
				cached.stats.availableStatPoints = 0;
				cached.statsInitialized = true;
				cached.InvalidateStatCache();
				PawnStatGenerator.UpdateRankTraitFromStats(leader, cached);
				Log.Message($"[Isekai Leveling] Empire leader {((Entity)leader).LabelShort} set to Nation rank (level {num}).");
				return true;
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] Empire leader promotion failed: " + ex.Message);
				return false;
			}
		}

		public static void RunOnGameLoad()
		{
			try
			{
				TryPromoteEmpireLeader();
				int num = 0;
				foreach (Pawn item in AllRelevantPawns())
				{
					IsekaiComponent cached = IsekaiComponent.GetCached(item);
					if (cached != null && ClampToLevelCap(item, cached))
					{
						num++;
					}
				}
				if (num > 0)
				{
					Log.Message($"[Isekai Leveling] Level cap: pulled {num} pawn(s) back down to {IsekaiMod.Settings?.MaxLevel ?? 1600}.");
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] Nation rank load pass failed: " + ex.Message);
			}
		}

