	public static class NumberFormatting
	{
		private static readonly (long threshold, string suffix)[] Suffixes = new(long, string)[4]
		{
			(1000000000000L, "T"),
			(1000000000L, "B"),
			(1000000L, "M"),
			(1000L, "k")
		};

		public static string FormatNum(long value)
		{
			if (value < 0)
			{
				return "-" + FormatNum(-value);
			}
			(long, string)[] suffixes = Suffixes;
			for (int i = 0; i < suffixes.Length; i++)
			{
				var (num, text) = suffixes[i];
				if (value >= num)
				{
					double num2 = (double)value / (double)num;
					if (num2 >= 100.0)
					{
						return num2.ToString("F1") + text;
					}
					if (num2 >= 10.0)
					{
						return num2.ToString("F2") + text;
					}
					return num2.ToString("F2") + text;
				}
			}
			return value.ToString("N0");
		}

		public static string FormatNum(float value)
		{
			return FormatNum((long)value);
		}

		public static string FormatNum(double value)
		{
			return FormatNum((long)value);
		}

		public static string FormatNum(int value)
		{
			return FormatNum((long)value);
		}
	}
