	public static class PawnRoleStats
	{
		private const float ROLE_SHARE = 0.75f;

		private const float PRIMARY_OF_ROLE_MIN = 0.58f;

		private const float PRIMARY_OF_ROLE_MAX = 0.7f;

		private const float ODDBALL_CHANCE = 0.15f;

		public static (IsekaiStatType primary, IsekaiStatType secondary) StatsFor(IsekaiPawnRole role)
		{
			return role switch
			{
				IsekaiPawnRole.Melee => (primary: IsekaiStatType.Strength, secondary: IsekaiStatType.Vitality), 
				IsekaiPawnRole.Ranged => (primary: IsekaiStatType.Dexterity, secondary: IsekaiStatType.Vitality), 
				IsekaiPawnRole.Speaker => (primary: IsekaiStatType.Charisma, secondary: IsekaiStatType.Wisdom), 
				IsekaiPawnRole.Healer => (primary: IsekaiStatType.Wisdom, secondary: IsekaiStatType.Intelligence), 
				_ => (primary: IsekaiStatType.Intelligence, secondary: IsekaiStatType.Wisdom), 
			};
		}

		public static IsekaiPawnRole DetectRole(Pawn pawn)
		{
			try
			{
				object obj;
				if (pawn == null)
				{
					obj = null;
				}
				else
				{
					Pawn_EquipmentTracker equipment = pawn.equipment;
					obj = ((equipment != null) ? equipment.Primary : null);
				}
				ThingWithComps val = (ThingWithComps)obj;
				if (((Thing)(val?)).def != null)
				{
					if (((Thing)val).def.IsRangedWeapon)
					{
						return IsekaiPawnRole.Ranged;
					}
					if (((Thing)val).def.IsMeleeWeapon)
					{
						return IsekaiPawnRole.Melee;
					}
				}
				bool valueOrDefault = pawn?.kindDef?.isFighter == true;
				Pawn_SkillTracker val2 = pawn?.skills;
				if (val2 != null)
				{
					int num = SkillLevel(val2, SkillDefOf.Shooting);
					int num2 = SkillLevel(val2, SkillDefOf.Melee);
					if (valueOrDefault || num >= 6 || num2 >= 6)
					{
						return (num >= num2) ? IsekaiPawnRole.Ranged : IsekaiPawnRole.Melee;
					}
					if ((pawn.kindDef != null && pawn.kindDef.trader) || (((Thing)pawn).Faction != null && ((Thing)pawn).Faction.leader == pawn))
					{
						return IsekaiPawnRole.Speaker;
					}
					int num3 = SkillLevel(val2, SkillDefOf.Social);
					int num4 = SkillLevel(val2, SkillDefOf.Medicine);
					int num5 = SkillLevel(val2, SkillDefOf.Intellectual);
					if (num4 > num5 && num4 > num3)
					{
						return IsekaiPawnRole.Healer;
					}
					if (num3 > num5 && num3 > num4)
					{
						return IsekaiPawnRole.Speaker;
					}
					return IsekaiPawnRole.Scholar;
				}
				if (valueOrDefault)
				{
					return IsekaiPawnRole.Melee;
				}
			}
			catch
			{
			}
			return IsekaiPawnRole.Scholar;
		}

		private static int SkillLevel(Pawn_SkillTracker skills, SkillDef def)
		{
			if (def == null)
			{
				return 0;
			}
			SkillRecord skill = skills.GetSkill(def);
			return (skill != null) ? skill.Level : 0;
		}

		public static bool ShouldApply(Pawn pawn, IsekaiComponent comp)
		{
			if (!IsekaiLevelingSettings.enableRoleBasedStats)
			{
				return false;
			}
			if (pawn == null || comp == null || comp.stats == null)
			{
				return false;
			}
			if (pawn.RaceProps == null || !pawn.RaceProps.Humanlike)
			{
				return false;
			}
			if (((Thing)pawn).Faction == null || ((Thing)pawn).Faction.IsPlayer)
			{
				return false;
			}
			return true;
		}

		public static void ApplyRoleDistribution(Pawn pawn, IsekaiComponent comp)
		{
			try
			{
				if ((comp != null && comp.forgeLocked) || !ShouldApply(pawn, comp))
				{
					return;
				}
				IsekaiStatAllocation stats = comp.stats;
				int totalAllocatedPoints = stats.TotalAllocatedPoints;
				if (totalAllocatedPoints <= 0 || Rand.Value < 0.15f)
				{
					return;
				}
				(IsekaiStatType, IsekaiStatType) tuple = StatsFor(DetectRole(pawn));
				int item = (int)tuple.Item1;
				int item2 = (int)tuple.Item2;
				float num = Rand.Range(0.58f, 0.7f);
				int num2 = RoundToInt((float)totalAllocatedPoints * 0.75f);
				int num3 = RoundToInt((float)num2 * num);
				int num4 = num2 - num3;
				int num5 = totalAllocatedPoints - num2;
				int[] array = new int[6];
				array[item] += num3;
				array[item2] += num4;
				if (num5 > 0)
				{
					List<int> list = new List<int>();
					for (int i = 0; i < 6; i++)
					{
						if (i != item && i != item2)
						{
							list.Add(i);
						}
					}
					if (list.Count == 0)
					{
						list.Add(item);
					}
					for (int j = 0; j < num5; j++)
					{
						array[list[j % list.Count]]++;
					}
				}
				WriteAllocation(stats, array);
				comp.InvalidateStatCache();
			}
			catch (Exception ex)
			{
				Log.WarningOnce("[Isekai] Role stat distribution failed: " + ex.Message, 2647);
			}
		}

		private static void WriteAllocation(IsekaiStatAllocation stats, int[] add)
		{
			int num = 5;
			int effectiveMaxStat = IsekaiStatAllocation.GetEffectiveMaxStat();
			int num2 = Math.Max(0, effectiveMaxStat - num);
			int num3 = 0;
			for (int i = 0; i < 6; i++)
			{
				if (add[i] > num2)
				{
					num3 += add[i] - num2;
					add[i] = num2;
				}
			}
			while (num3 > 0)
			{
				bool flag = false;
				for (int j = 0; j < 6; j++)
				{
					if (num3 <= 0)
					{
						break;
					}
					if (add[j] < num2)
					{
						int num4 = Math.Min(num2 - add[j], num3);
						add[j] += num4;
						num3 -= num4;
						flag = true;
					}
				}
				if (!flag)
				{
					break;
				}
			}
			for (int k = 0; k < 6; k++)
			{
				stats.SetStat((IsekaiStatType)k, num + add[k]);
			}
		}

		private static int RoundToInt(float v)
		{
			return (int)Math.Round(v, MidpointRounding.AwayFromZero);
		}
	}
