			}
			int val = IsekaiMod.Settings?.MaxLevel ?? 1600;
			int num = Math.Min(value.Item2, val);
			int minValue = Math.Min(value.Item1, num);
			int num2 = random.Next(minValue, num + 1);
			int num3 = IsekaiMod.Settings?.SkillPointsPerLevel ?? 1;
			int num4 = (num2 - 1) * num3;
			int effectiveMaxStat = IsekaiStatAllocation.GetEffectiveMaxStat();
