			}
			else if (num5 < 50)
			{
				DistributeSemiFocused(stats, num4, effectiveMaxStat);
			}
			else
			{
				DistributeRandom(stats, num4, effectiveMaxStat);
			}
			if (pawn != null)
			{
				IsekaiComponent comp = ((ThingWithComps)pawn).GetComp<IsekaiComponent>();
				if (comp != null && comp.stats == stats)
				{
					PawnRoleStats.ApplyRoleDistribution(pawn, comp);
