		public static int CalculateLevelFromStats(IsekaiStatAllocation stats)
		{
			int totalAllocatedPoints = stats.TotalAllocatedPoints;
			int val = IsekaiMod.Settings?.SkillPointsPerLevel ?? 1;
			int val2 = IsekaiMod.Settings?.MaxLevel ?? 1600;
			int val3 = 1 + totalAllocatedPoints / Math.Max(1, val);
			return Math.Max(1, Math.Min(val3, val2));
		}

		private static void EnforceConfigCaps(IsekaiComponent comp)
		{
			int effectiveMaxStat = IsekaiStatAllocation.GetEffectiveMaxStat();
			int val = IsekaiMod.Settings?.MaxLevel ?? 1600;
			comp.stats.strength = Math.Min(comp.stats.strength, effectiveMaxStat);
			comp.stats.dexterity = Math.Min(comp.stats.dexterity, effectiveMaxStat);
			comp.stats.vitality = Math.Min(comp.stats.vitality, effectiveMaxStat);
			comp.stats.intelligence = Math.Min(comp.stats.intelligence, effectiveMaxStat);
			comp.stats.wisdom = Math.Min(comp.stats.wisdom, effectiveMaxStat);
			comp.stats.charisma = Math.Min(comp.stats.charisma, effectiveMaxStat);
			comp.currentLevel = Math.Min(comp.currentLevel, val);
		}

