		public static string InitializePawnStats(Pawn pawn, IsekaiComponent comp)
		{
			if (!ShouldGenerateStats(pawn))
			{
				return "F";
			}
			bool flag = ShouldUseStartingLevel(pawn);
			int num = IsekaiMod.Settings?.StartingPawnLevel ?? 0;
			string text;
			if (flag && num > 0)
			{
				InitializeWithStartingLevel(comp, num);
				text = DetermineRankFromLevel(num);
			}
			else if (flag && num == 0 && IsMidSaveAddition())
			{
				int level = CalculateWealthBasedLevel();
				InitializeWithStartingLevel(comp, level);
				text = DetermineRankFromLevel(level);
			}
			else
			{
				text = RollRankForPawn(pawn);
				GenerateStatsForRank(text, comp.stats);
				comp.currentLevel = CalculateLevelFromStats(comp.stats);
				text = DetermineRankFromLevel(comp.currentLevel);
			}
			EnforceConfigCaps(comp);
			comp.stats.availableStatPoints = 0;
			AssignRankTrait(pawn, text);
			IsekaiTraitHelper.RollRandomTraits(pawn);
			comp.traitsRolled = true;
			return text;
		}

		private static bool ShouldUseStartingLevel(Pawn pawn)
		{
			if (pawn == null)
			{
				return false;
			}
			if (((Thing)pawn).Faction != null)
			{
				FactionManager factionManager = Find.FactionManager;
				Faction val = ((factionManager != null) ? factionManager.OfPlayer : null);
				if (val != null && ((Thing)pawn).Faction == val)
				{
					return true;
				}
			}
			if (!((Thing)pawn).Spawned && ((Thing)pawn).Faction == null && Current.Game != null && !GenCollection.Any<Map>(Current.Game.Maps))
			{
				return true;
			}
			return false;
		}

		private static bool IsMidSaveAddition()
		{
			try
			{
				if (Current.Game == null)
				{
					return false;
				}
				if (!GenCollection.Any<Map>(Current.Game.Maps))
				{
					return false;
				}
				if (Current.Game.tickManager.TicksGame <= 1000)
				{
					return false;
				}
				foreach (Map map in Current.Game.Maps)
				{
					object obj;
					if (map == null)
					{
						obj = null;
					}
					else
					{
						MapPawns mapPawns = map.mapPawns;
						obj = ((mapPawns != null) ? mapPawns.FreeColonists : null);
					}
					if (obj == null)
					{
						continue;
					}
					foreach (Pawn freeColonist in map.mapPawns.FreeColonists)
					{
						IsekaiComponent comp = ((ThingWithComps)freeColonist).GetComp<IsekaiComponent>();
						if (comp != null && comp.statsInitialized)
						{
							return false;
						}
					}
				}
				return true;
			}
			catch
			{
				return false;
			}
		}

		private static int CalculateWealthBasedLevel()
		{
			try
			{
				List<Map> maps = Find.Maps;
				Map val = ((maps != null) ? GenCollection.FirstOrDefault<Map>(maps, (Predicate<Map>)((Map m) => m.IsPlayerHome)) : null);
				if (val == null)
				{
					return 1;
				}
				WealthWatcher wealthWatcher = val.wealthWatcher;
				float num = ((wealthWatcher != null) ? wealthWatcher.WealthTotal : 0f);
				if (num >= 1000000f)
				{
					return random.Next(76, 101);
				}
				if (num >= 500000f)
				{
					return random.Next(51, 76);
				}
				if (num >= 250000f)
				{
					return random.Next(26, 51);
				}
				if (num >= 100000f)
				{
					return random.Next(18, 26);
				}
				if (num >= 40000f)
				{
					return random.Next(11, 18);
				}
				if (num >= 15000f)
				{
					return random.Next(6, 11);
				}
				return random.Next(1, 6);
			}
			catch
			{
				return 1;
			}
		}

		private static void InitializeWithStartingLevel(IsekaiComponent comp, int level)
		{
			comp.stats.strength = 5;
			comp.stats.dexterity = 5;
			comp.stats.vitality = 5;
			comp.stats.intelligence = 5;
			comp.stats.wisdom = 5;
			comp.stats.charisma = 5;
			int num = IsekaiMod.Settings?.SkillPointsPerLevel ?? 1;
			int num2 = (level - 1) * num;
			if (num2 > 0)
			{
				int effectiveMaxStat = IsekaiStatAllocation.GetEffectiveMaxStat();
				DistributeRandom(comp.stats, num2, effectiveMaxStat);
			}
			int val = IsekaiMod.Settings?.MaxLevel ?? 1600;
			comp.currentLevel = Math.Min(level, val);
			comp.currentXP = 0;
		}

		public static void SyncToRankTrait(Pawn pawn, IsekaiComponent comp, string rank)
		{
			if (pawn == null || comp == null || string.IsNullOrEmpty(rank))
			{
				return;
			}
			int minLevelForRank = GetMinLevelForRank(rank);
			int maxLevelForRank = GetMaxLevelForRank(rank);
			string text = DetermineRankFromLevel(comp.currentLevel);
			if (!(text == rank))
			{
				GenerateStatsForRank(rank, comp.stats, pawn);
				int val = CalculateLevelFromStats(comp.stats);
				int val2 = IsekaiMod.Settings?.MaxLevel ?? 1600;
				comp.currentLevel = Math.Max(minLevelForRank, Math.Min(val, Math.Min(maxLevelForRank, val2)));
				comp.currentXP = 0;
				comp.stats.availableStatPoints = 0;
				comp.passiveTree?.ReconcileToLevel(comp.currentLevel, pawn);
				EnforceConfigCaps(comp);
				if (Prefs.DevMode)
				{
					Log.Message($"[Isekai Leveling] Synced {((Entity)pawn).LabelShort} to rank {rank} (level {comp.currentLevel})");
				}
			}
		}

		public static int GetMinLevelForRank(string rank)
		{
			return rank switch
			{
				"Nation" => 800, 
				"SSS" => 401, 
				"SS" => 201, 
				"S" => 101, 
				"A" => 51, 
				"B" => 26, 
				"C" => 18, 
				"D" => 11, 
				"E" => 6, 
				_ => 1, 
			};
		}

		private static int GetMaxLevelForRank(string rank)
		{
			return rank switch
			{
				"F" => 5, 
				"E" => 10, 
				"D" => 17, 
				"C" => 25, 
				"B" => 50, 
				"A" => 100, 
				"S" => 200, 
				"SS" => 400, 
				_ => 9999, 
			};
		}

		private static string DetermineRankFromLevel(int level)
		{
			return GetRankFromLevel(level);
		}

		public static void AssignRankTrait(Pawn pawn, string rank)
		{
			//IL_006a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0070: Expected O, but got Unknown
			if (pawn?.story?.traits == null)
			{
				return;
			}
			string text = "Isekai_Rank_" + rank;
			TraitDef namedSilentFail = DefDatabase<TraitDef>.GetNamedSilentFail(text);
			if (namedSilentFail == null)
			{
				if (Prefs.DevMode)
				{
					Log.Warning("[Isekai Leveling] Could not find rank trait: " + text);
				}
			}
			else
			{
				RemoveExistingRankTraits(pawn);
				Trait val = new Trait(namedSilentFail, 0, true);
				pawn.story.traits.GainTrait(val, false);
			}
		}

		private static void RemoveExistingRankTraits(Pawn pawn)
		{
			if (pawn?.story?.traits == null)
			{
				return;
			}
			string[] array = new string[10] { "F", "E", "D", "C", "B", "A", "S", "SS", "SSS", "Nation" };
			List<Trait> list = new List<Trait>();
			foreach (Trait allTrait in pawn.story.traits.allTraits)
			{
				string[] array2 = array;
				foreach (string text in array2)
				{
					if (((Def)allTrait.def).defName == "Isekai_Rank_" + text)
					{
						list.Add(allTrait);
						break;
					}
				}
			}
			foreach (Trait item in list)
			{
				pawn.story.traits.RemoveTrait(item, false);
			}
		}

		public static void UpdateRankTraitFromStats(Pawn pawn, IsekaiComponent comp)
		{
			if (pawn?.story?.traits != null && comp != null)
			{
				string rankFromLevel = GetRankFromLevel(comp.currentLevel);
				AssignRankTrait(pawn, rankFromLevel);
			}
		}

		private static string GetRankFromLevel(int level)
		{
			return MobRankUtility.RankStringFromLevel(level);
		}

		public static string GetRankDescription(string rank)
		{
			return rank switch
			{
				"F" => "Novice - barely trained in combat", 
				"E" => "Apprentice - has basic training", 
				"D" => "Journeyman - competent but unremarkable", 
				"C" => "Adventurer - skilled and capable", 
				"B" => "Veteran - experienced and dangerous", 
				"A" => "Elite - among the best fighters", 
				"S" => "Hero - legendary prowess", 
				"SS" => "Demigod - transcendent power", 
				"SSS" => "Godlike - absolute apex being", 
				_ => "Unknown", 
			};
		}

		public static void CacheCharacterCreationStats(Pawn pawn, IsekaiComponent comp)
		{
			if (((pawn != null) ? pawn.Name : null) != null && comp?.stats != null)
			{
				string toStringFull = pawn.Name.ToStringFull;
				if (!string.IsNullOrEmpty(toStringFull))
				{
					characterCreationCache[toStringFull] = new CachedCharacterStats
					{
						level = comp.currentLevel,
						xp = comp.currentXP,
						strength = comp.stats.strength,
						dexterity = comp.stats.dexterity,
						vitality = comp.stats.vitality,
						intelligence = comp.stats.intelligence,
						wisdom = comp.stats.wisdom,
						charisma = comp.stats.charisma,
						availableStatPoints = comp.stats.availableStatPoints
					};
				}
			}
		}

		public static bool TryRestoreCharacterCreationStats(Pawn pawn, IsekaiComponent comp)
		{
			if (((pawn != null) ? pawn.Name : null) == null || comp?.stats == null)
			{
				return false;
			}
			string toStringFull = pawn.Name.ToStringFull;
			if (string.IsNullOrEmpty(toStringFull))
			{
				return false;
			}
			if (!characterCreationCache.TryGetValue(toStringFull, out var value))
			{
				return false;
			}
			comp.currentLevel = value.level;
			comp.currentXP = value.xp;
			comp.stats.strength = value.strength;
			comp.stats.dexterity = value.dexterity;
			comp.stats.vitality = value.vitality;
			comp.stats.intelligence = value.intelligence;
			comp.stats.wisdom = value.wisdom;
			comp.stats.charisma = value.charisma;
			comp.stats.availableStatPoints = value.availableStatPoints;
			comp.statsInitialized = true;
			UpdateRankTraitFromStats(pawn, comp);
			characterCreationCache.Remove(toStringFull);
			return true;
		}

		public static void ClearCharacterCreationCache()
		{
			characterCreationCache.Clear();
		}
	}
