				Log.Warning("[Isekai Leveling] Skipped DLC music override patch: " + ex2.Message);
			}
			try
			{
				WorldBossSizePatch.ApplyPatches(val);
			}
			catch (Exception ex3)
			{
				num2++;
				Log.Warning("[Isekai Leveling] Skipped WorldBoss size patch: " + ex3.Message);
			}
			if (num2 == 0)
			{
				Log.Message($"[Isekai Leveling] Mod initialized successfully! ({num} patches applied)");
			}
			else
			{
				Log.Warning($"[Isekai Leveling] Mod initialized with {num2} patch(es) skipped. ({num} applied)");
			}
			VerifyCriticalPatches(val);
		}

		private void VerifyCriticalPatches(Harmony harmony)
		{
			try
			{
				Dictionary<string, MethodBase> dictionary = new Dictionary<string, MethodBase>();
				dictionary.Add("BodyPartDef.GetMaxHealth (creature health)", AccessTools.Method(typeof(BodyPartDef), "GetMaxHealth", new Type[1] { typeof(Pawn) }, (Type[])null));
				dictionary.Add("Thing.TakeDamage (creature damage)", AccessTools.Method(typeof(Thing), "TakeDamage", (Type[])null, (Type[])null));
				dictionary.Add("StatWorker.GetValueUnfinalized (stat bonuses)", AccessTools.Method(typeof(StatWorker), "GetValueUnfinalized", (Type[])null, (Type[])null));
				dictionary.Add("HediffSet.BleedRateTotal (bleed reduction)", AccessTools.PropertyGetter(typeof(HediffSet), "BleedRateTotal"));
				Dictionary<string, MethodBase> dictionary2 = dictionary;
				int num = 0;
				foreach (KeyValuePair<string, MethodBase> item in dictionary2)
				{
					if (item.Value == null)
					{
						Log.Error("[Isekai Leveling] CRITICAL: Cannot find method " + item.Key + " - patch target does not exist in this RimWorld version!");
						continue;
					}
					Patches patchInfo = Harmony.GetPatchInfo(item.Value);
					if (patchInfo == null)
					{
						Log.Error("[Isekai Leveling] CRITICAL: " + item.Key + " has NO patches applied at all!");
						continue;
					}
					bool flag = false;
					foreach (Patch postfix in patchInfo.Postfixes)
					{
						if (postfix.owner == "JellyCreative.IsekaiLeveling")
						{
							flag = true;
							break;
						}
					}
					if (!flag)
					{
						foreach (Patch prefix in patchInfo.Prefixes)
						{
							if (prefix.owner == "JellyCreative.IsekaiLeveling")
							{
								flag = true;
								break;
							}
						}
					}
					if (flag)
					{
						num++;
					}
					else
					{
						Log.Error("[Isekai Leveling] CRITICAL: " + item.Key + " is patched but our patch is MISSING! Other mods may conflict.");
					}
				}
				Log.Message($"[Isekai Leveling] Critical patch verification: {num}/{dictionary2.Count} verified OK");
				Log.Message($"[Isekai Leveling] Settings: TamedRetention={Settings?.TamedAnimalBonusRetention ?? (-1f)}, " + $"HealthMult={Settings?.MobRankHealthMultiplier ?? (-1f)}, " + $"STR_MeleeDmg={Settings?.STR_MeleeDamage ?? (-1f)}, " + $"VIT_MaxHP={Settings?.VIT_MaxHealth ?? (-1f)}, " + $"VIT_DR={Settings?.VIT_DamageReduction ?? (-1f)}, " + $"ExclAnimals={Settings?.ExcludeAnimalsFromRanking ?? false}");
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] Patch verification failed: " + ex.Message);
			}
		}

		public override string SettingsCategory()
		{
