		private static string GetRankColor(int rankIndex)
		{
			return rankIndex switch
			{
				0 => "#888888", 
				1 => "#AAAAAA", 
				2 => "#55CC55", 
				3 => "#5599FF", 
				4 => "#AA55FF", 
				5 => "#FFD700", 
				6 => "#FF4444", 
				_ => "#FFFFFF", 
			};
		}

