			float num = value * 100f;
			string arg = ((defaultValue >= 0f) ? $"  <color=#888888>(Default: {defaultValue * 100f:F1}%)</color>" : "");
			listing.Label($"{label}: +{num:F1}% per point{arg}", -1f, (TipSignal?)null);
