		public string ForceChallenge(Pawn champ, TitleTier? tierOverride = null)
		{
			if (champ == null || champ.Dead)
			{
				return "No pawn selected, or the pawn is dead.";
			}
			if (((Thing)champ).Map == null || !((Thing)champ).Spawned)
			{
				return "Pawn is not spawned on a map.";
			}
			if (((Thing)champ).Faction != Faction.OfPlayer)
			{
				return "Duels are only issued against player colonists.";
			}
			IsekaiComponent cached = IsekaiComponent.GetCached(champ);
			if (cached?.stats == null)
			{
				return ((Entity)champ).LabelShortCap + " has no Isekai stats.";
			}
			TitleRead.TryGet(champ, out var text, out var titleTier);
			if (text == null)
			{
				IsekaiBuildTitles.BuildTitle buildTitle = IsekaiBuildTitles.Classify(cached.stats);
				text = (buildTitle.Exists ? buildTitle.archetype.id : (IsekaiBuildTitles.ForStat(IsekaiBuildTitles.LeadingStat(cached.stats, out var _))?.id ?? "Sword"));
			}
			TitleTier champTier = tierOverride ?? ((titleTier >= TitleTier.Saint) ? titleTier : TitleTier.Saint);
			if (state != 0)
			{
				AbortCurrent(silent: true);
				if (state != 0)
				{
					return "A duel site is still open. Leave or close that map first, then retry.";
				}
			}
			return TryStartDuel(champ, text, champTier, ((Thing)champ).Map) ? null : "Could not place a duelling ground within range. Try from a different map or tile.";
		}

		public void AbortCurrent(bool silent = false)
		{
			try
			{
				if (state == 0)
				{
					return;
				}
				if (challenger != null && ((Thing)challenger).Spawned)
				{
					((Entity)challenger).DeSpawn((DestroyMode)0);
				}
				DiscardChallenger(challenger);
				if (site != null && !((WorldObject)site).Destroyed && !((MapParent)site).HasMap)
				{
					((WorldObject)site).Destroy();
				}
				else if (site != null && !((WorldObject)site).Destroyed)
				{
					state = 3;
					challenger = null;
					if (!silent)
					{
						Messages.Message("Duel aborted; site clears when its map closes.", MessageTypeDefOf.TaskCompletion, true);
					}
					return;
				}
				Cleanup();
				if (!silent)
				{
					Messages.Message("Title duel aborted.", MessageTypeDefOf.TaskCompletion, true);
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] Duel abort failed: " + ex.Message);
				Cleanup();
			}
		}

		public string DescribeState()
		{
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine("[Isekai] Title duel state");
			stringBuilder.AppendLine($"  enabled       : {IsekaiLevelingSettings.EnableTitleDuels}");
			stringBuilder.AppendLine($"  state         : {(DuelState)state}");
			Pawn obj = champion;
			stringBuilder.AppendLine("  champion      : " + (((obj != null) ? ((Entity)obj).LabelShortCap : null) ?? "none"));
			Pawn obj2 = challenger;
			stringBuilder.AppendLine("  challenger    : " + (((obj2 != null) ? ((Entity)obj2).LabelShortCap : null) ?? "none") + ((challenger != null) ? $" (spawned: {challengerSpawned})" : ""));
			stringBuilder.AppendLine("  contested     : " + ((archetypeId != null) ? IsekaiBuildTitles.NameFor(IsekaiBuildTitles.ById(archetypeId), (TitleTier)tier) : "none"));
			stringBuilder.AppendLine($"  stake         : {silverStake} silver");
			stringBuilder.AppendLine("  site          : " + ((site == null) ? "none" : (((MapParent)site).HasMap ? "placed, map OPEN" : "placed, no map")));
			if (state == 1)
			{
				stringBuilder.AppendLine($"  days left     : {(float)Mathf.Max(0, deadlineTick - Find.TickManager.TicksGame) / 60000f:0.0}");
			}
			stringBuilder.AppendLine($"  duels so far  : {totalDuels}");
			int ticksGame = Find.TickManager.TicksGame;
			List<string> list = new List<string>();
			foreach (Map map in Find.Maps)
			{
				if (map == null || !map.IsPlayerHome)
				{
					continue;
				}
				foreach (Pawn item in map.mapPawns.FreeColonistsSpawned)
				{
					if (TitleRead.TryGet(item, out var id, out var titleTier) && titleTier >= TitleTier.Saint)
					{
						int value;
						bool flag = cooldownUntil.TryGetValue(((Thing)item).thingIDNumber, out value) && ticksGame < value;
						list.Add("    " + ((Entity)item).LabelShortCap + ": " + IsekaiBuildTitles.NameFor(IsekaiBuildTitles.ById(id), titleTier) + (flag ? $" (cooldown {(float)(value - ticksGame) / 60000f:0.0}d)" : ""));
					}
				}
			}
			stringBuilder.AppendLine((list.Count > 0) ? ("  eligible now  :\n" + string.Join("\n", list)) : "  eligible now  : none (no colonist holds a Saint or higher title)");
			return stringBuilder.ToString();
		}

