		private static bool IsBlacklistedBoss(PawnKindDef pk)
		{
			if (pk == null)
			{
				return false;
			}
			string item = ((Def)pk).defName ?? "";
			if (blacklistedBossDefNames.Contains(item))
			{
				return true;
			}
			string text = ((Def)pk).label?.ToLower() ?? "";
			if (text.Contains("nociosphere"))
			{
				return true;
			}
			return false;
		}

		public static bool TryFindBossTile(int baseTile, out int tile)
		{
			//IL_0021: Unknown result type (might be due to invalid IL or missing references)
			//IL_0050: Unknown result type (might be due to invalid IL or missing references)
