			tile = -1;
			WorldGrid worldGrid = Find.WorldGrid;
			for (int i = 0; i < 500; i++)
			{
				int num = Rand.Range(0, worldGrid.TilesCount);
				if (worldGrid.InBounds(PlanetTile.op_Implicit(num)) && !((Tile)worldGrid[num]).WaterCovered && !Find.World.Impassable(PlanetTile.op_Implicit(num)) && !Find.WorldObjects.AnyWorldObjectAt(PlanetTile.op_Implicit(num)))
				{
					float num2 = worldGrid.ApproxDistanceInTiles(PlanetTile.op_Implicit(baseTile), PlanetTile.op_Implicit(num));
					if (num2 >= 15f && num2 <= 60f)
