						tile = num;
						return true;
					}
				}
			}
			return false;
		}

		public static float CalculateWorldBossXP(float combatPower)
		{
			float num = 30f;
			try
			{
				Map anyPlayerHomeMap = Find.AnyPlayerHomeMap;
				if (anyPlayerHomeMap != null)
				{
					List<Pawn> freeColonists = anyPlayerHomeMap.mapPawns.FreeColonists;
					if (GenCollection.Any<Pawn>(freeColonists))
					{
						float num2 = 0f;
						int num3 = 0;
						foreach (Pawn item in freeColonists)
						{
							IsekaiComponent cached = IsekaiComponent.GetCached(item);
							if (cached != null)
							{
								num2 += (float)cached.currentLevel;
								num3++;
							}
						}
						if (num3 > 0)
						{
							num = num2 / (float)num3;
						}
					}
				}
			}
			catch
			{
			}
			float num4 = 0f;
			for (int i = 0; i < 15; i++)
			{
				num4 += 100f * Mathf.Pow(num + (float)i, 1.5f);
			}
			return num4 * 10f;
		}

		public static float CalculateWorldBossSilver(float combatPower)
		{
			float num = 30f * Mathf.Pow(1.8f, 9f) * 5f;
			float num2 = Mathf.Clamp(0.8f + combatPower / 150f, 0.8f, 3f);
			return num * num2;
		}

