	public class WorldBossMapComponent : MapComponent
	{
		private Pawn bossCreature;

		private PawnKindDef bossKind;

		private bool wavesTriggered;

		private bool bossDefeated;

		private int lastWaveSpawnTick = -1;

		private int wavesSpawned;

		private int nextWaveInterval;

		private List<Pawn> spawnedWaveMobs = new List<Pawn>();

		private int lastReinforcementTick = -1;

		private int reinforcementsSpawned;

		private QuestPart_WorldBoss questPart;

		private const int WAVE_MIN_INTERVAL_TICKS = 1800;

		private const int WAVE_MAX_INTERVAL_TICKS = 3600;

		private const int WAVE_MOB_COUNT_MIN = 2;

		private const int WAVE_MOB_COUNT_MAX = 3;

		private const float WAVE_TRIGGER_HP_PCT = 0.5f;

		private const int MAX_WAVES = 8;

		private const int ALLY_RETARGET_INTERVAL = 180;

		private const int REINFORCEMENT_INTERVAL = 60000;

		private const int MAX_REINFORCEMENTS = 4;

		public WorldBossMapComponent(Map map)
			: base(map)
		{
		}

		public void ReRegisterWaveMobsAfterLoad()
		{
			if (bossCreature != null && !bossCreature.Dead)
			{
				WorldBossSizePatch.RegisterWorldBoss(bossCreature);
			}
			if (spawnedWaveMobs == null)
			{
				return;
			}
			int num = 0;
			foreach (Pawn spawnedWaveMob in spawnedWaveMobs)
			{
				if (spawnedWaveMob != null && !spawnedWaveMob.Dead)
				{
					WorldBossSizePatch.RegisterWaveMob(spawnedWaveMob);
					num++;
				}
			}
			if (num > 0)
			{
				Log.Message($"[Isekai WorldBoss] Re-registered {num} wave mobs after load");
			}
		}

		public void RegisterBoss(Pawn boss, PawnKindDef kind)
		{
			bossCreature = boss;
			bossKind = kind;
			wavesTriggered = false;
			bossDefeated = false;
			wavesSpawned = 0;
			lastWaveSpawnTick = -1;
			spawnedWaveMobs = new List<Pawn>();
			nextWaveInterval = Rand.Range(1800, 3600);
			lastReinforcementTick = Find.TickManager.TicksGame;
			reinforcementsSpawned = 0;
		}

		public void SetQuestPart(QuestPart_WorldBoss qp)
		{
			questPart = qp;
		}

		public void OnBossDefeated()
		{
			bossDefeated = true;
			IsekaiMoods.GainColonyWide(base.map, "Isekai_BossSlain");
		}

		public override void MapComponentTick()
		{
			((MapComponent)this).MapComponentTick();
			if (bossDefeated || bossCreature == null || bossCreature.Dead)
			{
				return;
			}
			if (Find.TickManager.TicksGame % 180 == 0)
			{
				RetargetAlliedPawns();
			}
			if (reinforcementsSpawned < 4 && questPart != null)
			{
				int num = Find.TickManager.TicksGame - lastReinforcementTick;
				if (num >= 60000)
				{
					lastReinforcementTick = Find.TickManager.TicksGame;
					reinforcementsSpawned++;
					questPart.SpawnReinforcementFaction(base.map);
					Log.Message($"[Isekai WorldBoss] Reinforcement #{reinforcementsSpawned} arrived");
				}
			}
			if (Find.TickManager.TicksGame % 60 != 0)
			{
				return;
			}
			float summaryHealthPercent = bossCreature.health.summaryHealth.SummaryHealthPercent;
			if (!wavesTriggered && summaryHealthPercent <= 0.5f)
			{
				wavesTriggered = true;
				lastWaveSpawnTick = Find.TickManager.TicksGame;
				SpawnWave();
				Log.Message($"[Isekai WorldBoss] Wave spawning triggered! Boss at {summaryHealthPercent * 100f:F0}% HP");
			}
			if (wavesTriggered && !bossDefeated && wavesSpawned < 8)
			{
				int num2 = Find.TickManager.TicksGame - lastWaveSpawnTick;
				if (num2 >= nextWaveInterval)
