		private float AnimateHover(string id, bool isHovered)
		{
			if (!hoverStates.TryGetValue(id, out var value))
			{
				value = 0f;
			}
			float num = (isHovered ? 1f : 0f);
			value = Mathf.MoveTowards(value, num, Time.deltaTime * 10f);
			hoverStates[id] = value;
			if (hoverStates.Count > 500)
			{
				CleanupHoverStates();
			}
			return value;
		}

		public static void CleanupHoverStates()
		{
			List<string> list = new List<string>();
			foreach (KeyValuePair<string, float> hoverState in hoverStates)
			{
				if (hoverState.Value <= 0.001f)
				{
					list.Add(hoverState.Key);
				}
			}
			for (int i = 0; i < list.Count; i++)
			{
				hoverStates.Remove(list[i]);
			}
		}
	}
