		private bool CanDecrease(IsekaiStatType type)
		{
			return type switch
			{
				IsekaiStatType.Strength => pendingSTR > comp.stats.strength, 
				IsekaiStatType.Vitality => pendingVIT > comp.stats.vitality, 
				IsekaiStatType.Dexterity => pendingDEX > comp.stats.dexterity, 
				IsekaiStatType.Intelligence => pendingINT > comp.stats.intelligence, 
				IsekaiStatType.Wisdom => pendingWIS > comp.stats.wisdom, 
				IsekaiStatType.Charisma => pendingCHA > comp.stats.charisma, 
				_ => false, 
			};
		}

		private int GetOriginalStat(IsekaiStatType type)
