				IsekaiStatType.Strength => comp.stats.strength, 
				IsekaiStatType.Vitality => comp.stats.vitality, 
				IsekaiStatType.Dexterity => comp.stats.dexterity, 
				IsekaiStatType.Intelligence => comp.stats.intelligence, 
				IsekaiStatType.Wisdom => comp.stats.wisdom, 
				IsekaiStatType.Charisma => comp.stats.charisma, 
				_ => 0, 
			};
		}

