		private float AnimateHover(string id, bool isHovered)
		{
			if (!hoverStates.ContainsKey(id))
			{
				hoverStates[id] = 0f;
			}
			float num = (isHovered ? 1f : 0f);
			float num2 = hoverStates[id];
			float num3 = (isHovered ? 12f : 8f);
			hoverStates[id] = Mathf.Lerp(num2, num, Time.deltaTime * num3);
			if (isHovered && num2 < 0.1f && !shineTimers.ContainsKey(id))
			{
				shineTimers[id] = IsekaiAnimations.Now;
			}
			else if (!isHovered && shineTimers.ContainsKey(id))
			{
				shineTimers.Remove(id);
			}
			return hoverStates[id];
		}

		private float AnimateScale(string id, bool isHovered, float minScale = 1f, float maxScale = 1.05f)
		{
			if (!scaleStates.ContainsKey(id))
			{
				scaleStates[id] = minScale;
			}
			float num = (isHovered ? maxScale : minScale);
			float num2 = scaleStates[id];
			scaleStates[id] = Mathf.Lerp(num2, num, Time.deltaTime * 10f);
			return scaleStates[id];
		}

		private float GetShineProgress(string id)
		{
			if (!shineTimers.ContainsKey(id))
			{
				return 0f;
			}
			float num = IsekaiAnimations.Now - shineTimers[id];
			float num2 = 0.4f;
			if (num > num2)
			{
				return 0f;
			}
			return 1f - num / num2;
		}

