			return 1f + num2 * Mathf.Pow(t - 1f, 3f) + num * Mathf.Pow(t - 1f, 2f);
		}

		private float EaseOutElastic(float t)
		{
			if (t <= 0f)
			{
				return 0f;
			}
			if (t >= 1f)
			{
				return 1f;
			}
			float num = (float)Math.PI * 2f / 3f;
			return Mathf.Pow(2f, -10f * t) * Mathf.Sin((t * 10f - 0.75f) * num) + 1f;
		}

		private float PulseSine(float phase, float speed = 2f)
		{
			return (Mathf.Sin(phase * speed) + 1f) / 2f;
		}

