				}
				return IsekaiComponent.GetCached(val);
			}
			catch
			{
				return null;
			}
		}

		protected float GetStatValue(IsekaiComponent comp, string statName)
		{
			try
			{
				if (comp?.stats == null)
				{
					return 5f;
				}
				float num;
				IsekaiStatType statType;
				switch (statName)
				{
				case "STR":
					num = comp.stats.strength;
					statType = IsekaiStatType.Strength;
					break;
				case "DEX":
					num = comp.stats.dexterity;
					statType = IsekaiStatType.Dexterity;
					break;
				case "VIT":
					num = comp.stats.vitality;
					statType = IsekaiStatType.Vitality;
					break;
				case "INT":
					num = comp.stats.intelligence;
					statType = IsekaiStatType.Intelligence;
					break;
				case "WIS":
					num = comp.stats.wisdom;
					statType = IsekaiStatType.Wisdom;
					break;
				case "CHA":
					num = comp.stats.charisma;
					statType = IsekaiStatType.Charisma;
					break;
				default:
					return 5f;
				}
				ThingWithComps parent = ((ThingComp)comp).parent;
				Pawn val = (Pawn)(object)((parent is Pawn) ? parent : null);
				if (val != null)
				{
					float statEffectiveness = IsekaiTraitHelper.GetStatEffectiveness(val, statType, comp.currentLevel);
					if (statEffectiveness != 1f)
					{
						num = 5f + (num - 5f) * statEffectiveness;
					}
				}
				return num;
			}
			catch
			{
				return 5f;
			}
		}

		protected static float SoftCap(float value, float min, float cap)
		{
			if (value < min)
			{
				return min;
			}
			if (value <= cap)
			{
				return value;
			}
			float num = Mathf.Max(0.5f, cap * 0.5f);
			return cap + num * Mathf.Log(1f + (value - cap) / num);
		}

		protected static float SoftFloor(float value, float floor, float max)
		{
			if (value > max)
			{
				return max;
			}
			if (value >= floor)
			{
				return value;
			}
			float num = Mathf.Max(0.01f, floor * 0.5f);
			float num2 = floor - value;
			return floor - num * (1f - Mathf.Exp((0f - num2) / num));
		}

		protected float StatToMultiplier(float statValue, float multiplierPerPoint = 0.02f)
		{
			float num = 1f + (statValue - 5f) * multiplierPerPoint;
			if (float.IsNaN(num) || float.IsInfinity(num))
			{
				return 1f;
			}
			return num;
		}

		protected float ApplyTraitEffectiveness(StatRequest req, float multiplier, IsekaiStatType statType)
		{
			//IL_0034: Unknown result type (might be due to invalid IL or missing references)
			if (!((StatRequest)(ref req)).HasThing)
			{
				return multiplier;
			}
			Thing thing = ((StatRequest)(ref req)).Thing;
			Pawn val = (Pawn)(object)((thing is Pawn) ? thing : null);
			if (val == null)
			{
				return multiplier;
			}
			IsekaiComponent comp = GetComp(req);
			if (comp == null)
			{
				return multiplier;
			}
			float statEffectiveness = IsekaiTraitHelper.GetStatEffectiveness(val, statType, comp.currentLevel);
			if (statEffectiveness != 1f)
			{
				float num = multiplier - 1f;
				multiplier = 1f + num * statEffectiveness;
			}
			return multiplier;
		}

		protected float StatToOffset(float statValue, float offsetPerPoint = 0.01f)
		{
			float num = (statValue - 5f) * offsetPerPoint;
			if (float.IsNaN(num) || float.IsInfinity(num))
			{
				return 0f;
			}
			return num;
		}

		protected float GetPassiveBonus(IsekaiComponent comp, PassiveBonusType bonusType)
		{
			try
			{
				if (comp?.passiveTree == null)
				{
					return 0f;
				}
				return comp.passiveTree.GetTotalBonus(bonusType);
			}
			catch
			{
				return 0f;
			}
		}

		protected void ApplyPassiveMultiplier(IsekaiComponent comp, ref float val, PassiveBonusType bonusType)
		{
			float passiveBonus = GetPassiveBonus(comp, bonusType);
			if (passiveBonus != 0f)
			{
				val *= 1f + passiveBonus;
			}
		}

		protected void ApplyPassiveOffset(IsekaiComponent comp, ref float val, PassiveBonusType bonusType)
		{
			float passiveBonus = GetPassiveBonus(comp, bonusType);
			if (passiveBonus != 0f)
			{
				val += passiveBonus;
			}
		}

		protected string PassiveMultExplanation(IsekaiComponent comp, PassiveBonusType bonusType)
		{
			float passiveBonus = GetPassiveBonus(comp, bonusType);
			if (passiveBonus == 0f)
			{
				return "";
			}
			return $"\n  Isekai Passive: x{1f + passiveBonus:F2}";
		}

		protected string PassiveOffsetExplanation(IsekaiComponent comp, PassiveBonusType bonusType)
		{
			float passiveBonus = GetPassiveBonus(comp, bonusType);
			if (passiveBonus == 0f)
			{
				return "";
			}
			return $"\n  Isekai Passive: {passiveBonus:+0.0%;-0.0%}";
		}
	}
