	public class StatPart_IsekaiPainShock : StatPart_IsekaiBase
	{
		private const float BASE_THRESHOLD = 0.8f;

		private float GetHealthMultiplier(IsekaiComponent comp)
		{
			float num = comp.stats.vitality;
			float num2 = 1f;
			if (num > 5f)
			{
				num2 += (num - 5f) * IsekaiLevelingSettings.VIT_MaxHealth;
			}
			if (comp.passiveTree != null)
			{
				float totalBonus = comp.passiveTree.GetTotalBonus(PassiveBonusType.MaxHealth);
				if (totalBonus != 0f)
				{
					num2 += totalBonus;
				}
			}
			return Mathf.Max(num2, 1f);
		}

		protected override void TransformValueCore(StatRequest req, ref float val)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			IsekaiComponent comp = GetComp(req);
			if (comp != null)
			{
				float healthMultiplier = GetHealthMultiplier(comp);
				float num = (healthMultiplier - 1f) * 0.8f;
				val += Mathf.Max(num, 0f);
				ApplyPassiveOffset(comp, ref val, PassiveBonusType.PainThreshold);
			}
		}

		protected override string ExplanationPartCore(StatRequest req)
		{
			//IL_0002: Unknown result type (might be due to invalid IL or missing references)
			IsekaiComponent comp = GetComp(req);
			if (comp == null)
			{
				return null;
			}
			float healthMultiplier = GetHealthMultiplier(comp);
			float num = (healthMultiplier - 1f) * 0.8f;
			num = Mathf.Max(num, 0f);
			return $"Isekai VIT (x{healthMultiplier:F1} HP): {num:+0.00;-0.00}" + PassiveOffsetExplanation(comp, PassiveBonusType.PainThreshold);
		}
	}
	public class StatPart_IsekaiRestRate : StatPart_IsekaiBase
	{
