			{
				return;
			}
			float statValue = GetStatValue(comp, "VIT");
			float value = StatToMultiplier(statValue, IsekaiLevelingSettings.VIT_RestRate);
			val *= StatPart_IsekaiBase.SoftCap(value, 0.5f, 3f);
			ApplyPassiveMultiplier(comp, ref val, PassiveBonusType.RestRate);
			PassiveTreeTracker passiveTree = comp.passiveTree;
			if (passiveTree == null || !passiveTree.HasGimmick(ClassGimmickType.UnyieldingSpirit))
			{
				return;
			}
			int gimmickTierFor = comp.passiveTree.GetGimmickTierFor(ClassGimmickType.UnyieldingSpirit);
			if (gimmickTierFor > 0)
			{
				Thing thing = ((StatRequest)(ref req)).Thing;
				float num = PassiveTreeTracker.CalcUnyieldingSpirit((Pawn)(object)((thing is Pawn) ? thing : null), gimmickTierFor);
				if (num > 0f)
				{
					val *= 1f + num;
				}
			}
		}

