			if (string.IsNullOrEmpty(assignedTree))
			{
				passiveTreeDef = FindTreeForNode(nodeId);
				if (passiveTreeDef == null)
				{
					return false;
				}
				PassiveNodeRecord node = passiveTreeDef.GetNode(nodeId);
				if (node == null || node.nodeType != 0)
				{
					return false;
				}
				if (availablePoints < node.cost)
				{
					return false;
				}
				assignedTree = passiveTreeDef.treeClass;
			}
			else
			{
				passiveTreeDef = GetTreeDef();
				if (passiveTreeDef?.GetNode(nodeId) == null)
				{
					passiveTreeDef = FindTreeForNode(nodeId);
				}
			}
			if (passiveTreeDef == null)
			{
				return false;
			}
			PassiveNodeRecord node2 = passiveTreeDef.GetNode(nodeId);
			if (node2 == null)
			{
				return false;
			}
			if (!CanUnlock(nodeId, pawn))
			{
				return false;
			}
			availablePoints -= node2.cost;
			unlockedNodeIds.Add(nodeId);
			unlockedSet.Add(nodeId);
			bonusCache = null;
			cachedGimmick = null;
			gimmickTierCache = null;
			if (pawn != null && node2.nodeType == PassiveNodeType.Start && passiveTreeDef.treeClass != assignedTree)
			{
				ConsumeStarFragment(pawn);
			}
			if (pawn != null && !quiet)
			{
				IsekaiMoods.Gain(pawn, (node2.nodeType == PassiveNodeType.Start) ? "Isekai_PathFound" : "Isekai_NodeUnlocked");
			}
			return true;
		}

		public void OnLevelUp(int newLevel, Pawn pawn = null)
		{
			int starPointsForLevel = IsekaiTraitHelper.GetStarPointsForLevel(pawn, newLevel);
			if (starPointsForLevel > 0)
			{
				availablePoints += starPointsForLevel;
			}
		}

		public void ForceUnlockNode(string nodeId)
		{
			if (!unlockedSet.Contains(nodeId))
			{
				unlockedNodeIds.Add(nodeId);
				unlockedSet.Add(nodeId);
				bonusCache = null;
			}
		}

		public List<string> FindUnlockChain(string targetNodeId)
		{
			if (IsUnlocked(targetNodeId))
			{
				return null;
			}
			PassiveTreeDef passiveTreeDef = GetTreeDef();
			if (passiveTreeDef?.GetNode(targetNodeId) == null)
			{
				passiveTreeDef = FindTreeForNode(targetNodeId);
			}
			PassiveNodeRecord passiveNodeRecord = passiveTreeDef?.GetNode(targetNodeId);
			if (passiveNodeRecord == null)
			{
				return null;
			}
			if (passiveNodeRecord.requireAllConnected && passiveNodeRecord.nodeType != 0)
			{
				List<string> list = new List<string>();
				HashSet<string> hashSet = new HashSet<string>();
				foreach (string neighbor in passiveTreeDef.GetNeighbors(targetNodeId))
				{
					if (IsUnlocked(neighbor) || hashSet.Contains(neighbor))
					{
						continue;
					}
					List<string> list2 = Dijkstra(passiveTreeDef, neighbor, hashSet);
					if (list2 == null)
					{
						return null;
					}
					foreach (string item in list2)
					{
						if (hashSet.Add(item))
						{
							list.Add(item);
						}
					}
				}
				list.Add(targetNodeId);
				return list;
			}
			return Dijkstra(passiveTreeDef, targetNodeId, null);
		}

		private List<string> Dijkstra(PassiveTreeDef tree, string target, HashSet<string> virtualUnlocked)
		{
			Dictionary<string, int> dictionary = new Dictionary<string, int>();
			Dictionary<string, string> dictionary2 = new Dictionary<string, string>();
			List<string> list = new List<string>();
			bool flag = false;
			foreach (PassiveNodeRecord node2 in tree.nodes)
			{
				if (Reached(node2.nodeId))
				{
					dictionary[node2.nodeId] = 0;
					list.Add(node2.nodeId);
					flag = true;
				}
			}
			if (!flag)
			{
				foreach (PassiveNodeRecord node3 in tree.nodes)
				{
					if (node3.nodeType == PassiveNodeType.Start)
					{
						dictionary[node3.nodeId] = node3.cost;
						list.Add(node3.nodeId);
					}
				}
				if (list.Count == 0)
				{
					return null;
				}
			}
			HashSet<string> hashSet = new HashSet<string>();
			while (list.Count > 0)
			{
				string text = null;
				int num = int.MaxValue;
				foreach (string item in list)
				{
					if (dictionary[item] < num)
					{
						num = dictionary[item];
						text = item;
					}
				}
				list.Remove(text);
				if (!hashSet.Add(text))
				{
					continue;
				}
				if (text == target)
				{
					break;
				}
				foreach (string neighbor in tree.GetNeighbors(text))
				{
					if (hashSet.Contains(neighbor))
					{
						continue;
					}
					PassiveNodeRecord node = tree.GetNode(neighbor);
					if (node == null || (neighbor != target && node.requireAllConnected && !Reached(neighbor)))
					{
						continue;
					}
					int num2 = ((!Reached(neighbor)) ? node.cost : 0);
					int num3 = dictionary[text] + num2;
					if (!dictionary.TryGetValue(neighbor, out var value) || num3 < value)
					{
						dictionary[neighbor] = num3;
						dictionary2[neighbor] = text;
						if (!list.Contains(neighbor))
						{
							list.Add(neighbor);
						}
					}
				}
			}
			if (!dictionary.ContainsKey(target))
			{
				return null;
			}
			List<string> list2 = new List<string>();
			string text2 = target;
			while (text2 != null)
			{
				if (!Reached(text2))
				{
					list2.Add(text2);
				}
				dictionary2.TryGetValue(text2, out var value2);
				if (value2 == null)
				{
					break;
				}
				text2 = value2;
			}
			list2.Reverse();
			return (list2.Count > 0) ? list2 : null;
			bool Reached(string id)
			{
				return IsUnlocked(id) || (virtualUnlocked != null && virtualUnlocked.Contains(id));
			}
		}

		public int ChainCost(List<string> chain)
		{
			if (chain == null)
			{
				return 0;
			}
			int num = 0;
			foreach (string item in chain)
			{
				PassiveNodeRecord passiveNodeRecord = GetTreeDef()?.GetNode(item) ?? FindTreeForNode(item)?.GetNode(item);
				if (passiveNodeRecord != null)
				{
					num += passiveNodeRecord.cost;
				}
			}
			return num;
		}

		public int TryUnlockChain(string targetNodeId, Pawn pawn, out int pointsSpent, out string failReason)
		{
			pointsSpent = 0;
			failReason = null;
			List<string> list = FindUnlockChain(targetNodeId);
			if (list == null || list.Count == 0)
			{
				failReason = "noroute";
				return 0;
			}
			int num = ChainCost(list);
			if (num > availablePoints)
			{
				failReason = num + "|" + list.Count;
				return 0;
			}
			int num2 = availablePoints;
			int num3 = 0;
			for (int i = 0; i < list.Count; i++)
			{
				bool flag = i == list.Count - 1;
				if (!Unlock(list[i], pawn, !flag))
				{
					failReason = "gate";
					break;
				}
				num3++;
			}
			pointsSpent = num2 - availablePoints;
			return num3;
		}

		public void Respec()
		{
			int num = 0;
			List<string> list = new List<string>();
			foreach (string unlockedNodeId in unlockedNodeIds)
			{
				PassiveNodeRecord passiveNodeRecord = FindNodeInAnyTree(unlockedNodeId);
				if (passiveNodeRecord != null && passiveNodeRecord.nodeType == PassiveNodeType.Start)
				{
					list.Add(unlockedNodeId);
				}
				else
				{
					num += passiveNodeRecord?.cost ?? 1;
				}
			}
			unlockedNodeIds = list;
			unlockedSet = new HashSet<string>(list);
			availablePoints += num;
			bonusCache = null;
			cachedGimmick = null;
			gimmickTierCache = null;
			ResetGimmickState();
			respecCount++;
		}

		public int FullRespec()
		{
			int num = 0;
			int num2 = 0;
			foreach (string unlockedNodeId in unlockedNodeIds)
			{
				PassiveNodeRecord passiveNodeRecord = FindNodeInAnyTree(unlockedNodeId);
				num += passiveNodeRecord?.cost ?? 1;
				if (passiveNodeRecord != null && passiveNodeRecord.nodeType == PassiveNodeType.Start && !string.IsNullOrEmpty(assignedTree))
				{
					PassiveTreeDef passiveTreeDef = FindTreeForNode(unlockedNodeId);
					if (passiveTreeDef != null && passiveTreeDef.treeClass != assignedTree)
					{
						num2++;
					}
				}
			}
			unlockedNodeIds.Clear();
			unlockedSet.Clear();
			assignedTree = null;
			availablePoints += num;
			starFragmentsAbsorbed += num2;
			bonusCache = null;
			cachedGimmick = null;
			gimmickTierCache = null;
			ResetGimmickState();
			return num;
		}

		public bool ReconcileToLevel(int level, Pawn pawn = null)
		{
			if (pawn != null)
			{
				if (((Thing)pawn).Faction != null && ((Thing)pawn).Faction.IsPlayer)
				{
					return false;
				}
				IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
				if (cached != null && cached.forgeLocked)
				{
					return false;
				}
			}
			int num = Mathf.Max(0, level / 5) + Mathf.Max(0, starFragmentsAbsorbed) * 5;
			bool flag = level >= 11;
			int num2 = 0;
			for (int i = 0; i < unlockedNodeIds.Count; i++)
			{
				num2 += FindNodeInAnyTree(unlockedNodeIds[i])?.cost ?? 1;
			}
			if (num2 <= num && (flag || unlockedNodeIds.Count == 0))
			{
				return false;
			}
			FullRespec();
			if (!flag)
			{
				assignedTree = null;
				availablePoints = 0;
				return true;
			}
			availablePoints = num;
			return true;
		}

		private void ResetGimmickState()
		{
			retributionStoredDamage = 0;
			counterStrikeCharges = 0;
			frenzyStacks = 0;
			lastFrenzyKillTick = -1;
			huntMarkTargetId = -1;
			huntMarkStacks = 0;
			lastHitTick = -1;
			eurekaInsightStacks = 0;
			lastEurekaTendTick = -1;
		}

		public float GetTotalBonus(PassiveBonusType type)
		{
			if (string.IsNullOrEmpty(assignedTree))
			{
				return 0f;
			}
			if (bonusCache != null && bonusCache.TryGetValue(type, out var value))
			{
				if (type == PassiveBonusType.ClassGimmickTier)
				{
					return value;
				}
				return value * (IsekaiMod.Settings?.ConstellationBonusMultiplier ?? 1f);
			}
			if (bonusCache == null)
			{
				bonusCache = new Dictionary<PassiveBonusType, float>();
				foreach (string unlockedNodeId in unlockedNodeIds)
				{
					PassiveNodeRecord passiveNodeRecord = FindNodeInAnyTree(unlockedNodeId);
					if (passiveNodeRecord?.bonuses == null)
					{
						continue;
					}
					foreach (PassiveBonus bonuse in passiveNodeRecord.bonuses)
					{
						if (!bonusCache.ContainsKey(bonuse.bonusType))
						{
							bonusCache[bonuse.bonusType] = 0f;
						}
						bonusCache[bonuse.bonusType] += bonuse.value;
					}
				}
			}
			if (!bonusCache.TryGetValue(type, out var value2))
			{
				return 0f;
			}
			if (type == PassiveBonusType.ClassGimmickTier)
			{
				return value2;
			}
			return value2 * (IsekaiMod.Settings?.ConstellationBonusMultiplier ?? 1f);
		}

		public void RetroactiveGrant(int currentLevel)
		{
			if (availablePoints == 0 && unlockedNodeIds.Count == 0 && currentLevel > 1)
			{
				availablePoints = currentLevel / 5;
			}
		}

		public ClassGimmickType GetActiveGimmick()
		{
			if (cachedGimmick.HasValue)
			{
				return cachedGimmick.Value;
			}
			cachedGimmick = GetTreeDef()?.classGimmick ?? ClassGimmickType.None;
			return cachedGimmick.Value;
		}

		public bool HasGimmick(ClassGimmickType type)
		{
			if (type == ClassGimmickType.None)
			{
				return false;
			}
			EnsureGimmickTierCache();
			return gimmickTierCache.ContainsKey(type);
		}

		public List<ClassGimmickType> GetActiveGimmicks()
		{
			EnsureGimmickTierCache();
			return new List<ClassGimmickType>(gimmickTierCache.Keys);
		}

		public int GetGimmickTierFor(ClassGimmickType type)
		{
			if (type == ClassGimmickType.None)
			{
				return 0;
			}
			EnsureGimmickTierCache();
			int value;
			return gimmickTierCache.TryGetValue(type, out value) ? value : 0;
		}

		private void EnsureGimmickTierCache()
		{
			if (gimmickTierCache != null)
			{
				return;
			}
			gimmickTierCache = new Dictionary<ClassGimmickType, int>();
			foreach (PassiveTreeDef allDef in DefDatabase<PassiveTreeDef>.AllDefs)
			{
				if (allDef.classGimmick == ClassGimmickType.None || !HasEnteredTree(allDef))
				{
					continue;
				}
				int num = 0;
				foreach (string unlockedNodeId in unlockedNodeIds)
				{
					PassiveNodeRecord node = allDef.GetNode(unlockedNodeId);
					if (node?.bonuses == null)
					{
						continue;
					}
					foreach (PassiveBonus bonuse in node.bonuses)
					{
						if (bonuse.bonusType == PassiveBonusType.ClassGimmickTier)
						{
							num += Mathf.RoundToInt(bonuse.value);
						}
					}
				}
				gimmickTierCache[allDef.classGimmick] = Mathf.Clamp(num, 0, 4);
			}
		}

		public int GetGimmickTier()
		{
			float totalBonus = GetTotalBonus(PassiveBonusType.ClassGimmickTier);
			return Mathf.Clamp(Mathf.RoundToInt(totalBonus), 0, 4);
		}

		public static float CalcWrathOfTheFallen(Pawn pawn, int gimmickTier)
		{
			if (gimmickTier <= 0)
			{
				return 0f;
			}
			if (pawn?.health?.hediffSet == null)
			{
				return 0f;
			}
			SummaryHealthHandler summaryHealth = pawn.health.summaryHealth;
			float num = ((summaryHealth != null) ? summaryHealth.SummaryHealthPercent : 1f);
			float num2;
			float num3;
			switch (gimmickTier)
			{
			case 1:
				num2 = 0.5f;
				num3 = 0.25f;
				break;
			case 2:
				num2 = 0.5f;
				num3 = 0.35f;
				break;
			case 3:
				num2 = 0.5f;
				num3 = 0.5f;
				break;
			default:
				num2 = 0.5f;
				num3 = 0.75f;
				break;
			}
			if (num >= num2)
			{
				return 0f;
			}
			float num4 = 1f - num / num2;
			float num5 = num4 * num3;
			return Mathf.Clamp(num5, 0f, num3);
		}

		public float CalcWrathOfTheFallen(Pawn pawn)
		{
			return CalcWrathOfTheFallen(pawn, GetGimmickTier());
		}

		public static float CalcArcaneOverflow(Pawn pawn, int gimmickTier)
		{
			if (gimmickTier <= 0)
			{
				return 0f;
			}
			if (pawn?.psychicEntropy == null)
			{
				return 0f;
			}
			float currentPsyfocus = pawn.psychicEntropy.CurrentPsyfocus;
			float num;
			float num2;
			switch (gimmickTier)
			{
			case 1:
				num = 0.5f;
				num2 = 0.2f;
				break;
			case 2:
				num = 0.4f;
				num2 = 0.35f;
				break;
			case 3:
				num = 0.3f;
				num2 = 0.55f;
				break;
			default:
				num = 0.2f;
				num2 = 0.8f;
				break;
			}
			if (currentPsyfocus <= num)
			{
				return 0f;
			}
			float num3 = (currentPsyfocus - num) / (1f - num);
			return Mathf.Clamp(num3 * num2, 0f, num2);
		}

		public float CalcArcaneOverflow(Pawn pawn)
		{
			return CalcArcaneOverflow(pawn, GetGimmickTier());
		}

		public static float CalcDivineRetribution(int storedDamage, int gimmickTier)
		{
			if (gimmickTier <= 0 || storedDamage <= 0)
			{
				return 0f;
			}
			int num;
			float num2;
			switch (gimmickTier)
			{
			case 1:
				num = 50;
				num2 = 0.15f;
				break;
			case 2:
				num = 75;
				num2 = 0.3f;
				break;
			case 3:
				num = 100;
				num2 = 0.45f;
				break;
			default:
				num = 150;
				num2 = 0.6f;
				break;
			}
			float num3 = Mathf.Clamp01((float)storedDamage / (float)num);
			return num3 * num2;
		}

		public float CalcDivineRetribution()
		{
			return CalcDivineRetribution(retributionStoredDamage, GetGimmickTier());
		}

		public void AccumulateRetribution(int incomingDamage)
		{
			int gimmickTier = GetGimmickTier();
			if (gimmickTier > 0)
			{
				retributionStoredDamage = Mathf.Min(retributionStoredDamage + incomingDamage, gimmickTier switch
				{
					1 => 50, 
					2 => 75, 
					3 => 100, 
					_ => 150, 
				});
			}
		}

		public int ConsumeRetribution()
		{
			int result = retributionStoredDamage;
			retributionStoredDamage = 0;
			return result;
		}

		public void ResetCalmTimer()
		{
			if (HasGimmick(ClassGimmickType.InnerCalm))
			{
				TickManager tickManager = Find.TickManager;
				lastHitTick = ((tickManager != null) ? tickManager.TicksGame : 0);
