		public static float CalcInnerCalm(int lastHitTick, int gimmickTier)
		{
			if (gimmickTier <= 0)
			{
				return 0f;
			}
			int num;
			if (lastHitTick < 0)
			{
				num = 1073741823;
			}
			else
			{
				TickManager tickManager = Find.TickManager;
				num = ((tickManager != null) ? tickManager.TicksGame : 0) - lastHitTick;
			}
			int num2;
			float num3;
			switch (gimmickTier)
			{
			case 1:
				num2 = 10000;
				num3 = 0.2f;
				break;
			case 2:
				num2 = 7500;
				num3 = 0.35f;
				break;
			case 3:
				num2 = 5000;
				num3 = 0.55f;
				break;
			default:
				num2 = 2500;
				num3 = 0.8f;
				break;
			}
			float num4 = Mathf.Clamp01((float)Mathf.Max(0, num) / (float)num2);
			return num4 * num3;
		}

		public float CalcInnerCalm()
		{
			return CalcInnerCalm(lastHitTick, GetGimmickTier());
		}

		public void StackPredatorFocus(Thing target)
		{
			if (target == null)
			{
				return;
			}
			int gimmickTier = GetGimmickTier();
			if (gimmickTier > 0)
			{
				int num = gimmickTier switch
				{
					1 => 3, 
					2 => 4, 
					3 => 5, 
					_ => 7, 
				};
				int thingIDNumber = target.thingIDNumber;
				if (thingIDNumber == huntMarkTargetId)
				{
					huntMarkStacks = Mathf.Min(huntMarkStacks + 1, num);
					return;
				}
				huntMarkTargetId = thingIDNumber;
				huntMarkStacks = 1;
			}
		}

		public static float CalcPredatorFocus(int stacks, int gimmickTier)
		{
			if (gimmickTier <= 0 || stacks <= 0)
			{
				return 0f;
			}
			return (float)stacks * gimmickTier switch
			{
				1 => 0.04f, 
				2 => 0.05f, 
				3 => 0.06f, 
				_ => 0.07f, 
			};
		}

		public float CalcPredatorFocus()
		{
			return CalcPredatorFocus(huntMarkStacks, GetGimmickTier());
		}

