		public static float CalcMasterworkInsight(Pawn pawn, int gimmickTier)
		{
			if (gimmickTier <= 0)
			{
				return 0f;
			}
			if (pawn?.skills == null)
			{
				return 0f;
			}
			SkillRecord skill = pawn.skills.GetSkill(SkillDefOf.Crafting);
			if (skill == null)
			{
				return 0f;
			}
			float num = skill.Level;
			float num2 = gimmickTier switch
			{
				1 => 0.15f, 
				2 => 0.3f, 
				3 => 0.5f, 
				_ => 0.75f, 
			};
