		public static float CalcPackAlpha(Pawn pawn, int gimmickTier)
		{
			if (gimmickTier <= 0)
			{
				return 0f;
			}
			if (pawn?.relations == null || ((Thing)pawn).Map == null)
			{
				return 0f;
			}
			int num = 0;
			foreach (DirectPawnRelation directRelation in pawn.relations.DirectRelations)
			{
				if (directRelation.def == PawnRelationDefOf.Bond && directRelation.otherPawn != null && !directRelation.otherPawn.Dead && ((Thing)directRelation.otherPawn).Map == ((Thing)pawn).Map)
				{
					num++;
				}
			}
			if (num <= 0)
			{
				return 0f;
			}
			float num2;
			int num3;
			switch (gimmickTier)
			{
			case 1:
				num2 = 0.03f;
				num3 = 3;
				break;
			case 2:
				num2 = 0.04f;
				num3 = 5;
				break;
			case 3:
				num2 = 0.05f;
				num3 = 7;
				break;
			default:
				num2 = 0.06f;
				num3 = 10;
				break;
			}
			int num4 = Mathf.Min(num, num3);
			return (float)num4 * num2;
		}

		public float CalcPackAlpha(Pawn pawn)
		{
			return CalcPackAlpha(pawn, GetGimmickTier());
		}
	}
