		private const double ROLE_FIT_CHANCE = 0.85;

		public static void AssignTreeProgression(PassiveTreeTracker tracker, int level, IsekaiStatAllocation stats = null, Pawn pawn = null)
		{
			if (tracker == null || level < 11 || !string.IsNullOrEmpty(tracker.assignedTree))
			{
				return;
			}
			if (pawn != null)
			{
				IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
				if (cached != null && cached.forgeLocked)
				{
					return;
				}
			}
			int num = level / 5;
			bool flag = false;
			float num2 = 0f;
			if (level >= 401)
			{
				flag = rng.NextDouble() < 0.75;
				num2 = 0.45f;
			}
			else if (level >= 201)
			{
				flag = rng.NextDouble() < 0.5;
				num2 = 0.4f;
			}
			else if (level >= 101)
			{
				flag = rng.NextDouble() < 0.25;
				num2 = 0.3f;
			}
			(string, float)[] pool = RolePoolFor(pawn);
			string text = PickClass(null, stats, pool);
			string text2 = (flag ? PickClass(text, stats, RolePoolFor(pawn)) : null);
			int num3 = (flag ? ((int)((float)num * num2)) : 0);
			int budget = num - num3;
			PassiveTreeDef passiveTreeDef = FindTree(text);
			if (passiveTreeDef == null)
			{
				return;
			}
			tracker.assignedTree = text;
			SpendPointsOnTree(tracker, passiveTreeDef, budget);
			if (flag && text2 != null)
			{
				PassiveTreeDef passiveTreeDef2 = FindTree(text2);
				if (passiveTreeDef2 != null)
				{
					SpendPointsOnTree(tracker, passiveTreeDef2, num3);
				}
			}
			tracker.availablePoints = 0;
		}

		public static void AutoSpendAccumulated(PassiveTreeTracker tracker)
		{
			if (tracker != null && !string.IsNullOrEmpty(tracker.assignedTree) && tracker.availablePoints > 0)
			{
				PassiveTreeDef passiveTreeDef = FindTree(tracker.assignedTree);
				if (passiveTreeDef != null)
				{
					int availablePoints = tracker.availablePoints;
					SpendPointsOnTree(tracker, passiveTreeDef, availablePoints);
					tracker.availablePoints = 0;
				}
			}
		}

		private static (string cls, float weight)[] RolePoolFor(Pawn pawn)
		{
			try
			{
				if (pawn == null)
				{
					return null;
				}
				if (!IsekaiLevelingSettings.enableRoleBasedStats)
				{
					return null;
				}
				if (((Thing)pawn).Faction == null || ((Thing)pawn).Faction.IsPlayer)
				{
					return null;
				}
				if (rng.NextDouble() >= 0.85)
				{
					return null;
				}
				(string, float)[] value;
				return RoleClassPools.TryGetValue(PawnRoleStats.DetectRole(pawn), out value) ? value : null;
			}
			catch
			{
				return null;
			}
		}

		private static string PickClass(string exclude, IsekaiStatAllocation stats, (string cls, float weight)[] pool = null)
		{
			string[] array = ImplementedClasses;
			Dictionary<string, float> dictionary = null;
			if (pool != null && pool.Length != 0)
			{
				(string, float)[] array2 = pool.Where(((string cls, float weight) e) => e.cls != exclude).ToArray();
				if (array2.Length != 0)
				{
					array = pool.Select(((string cls, float weight) e) => e.cls).ToArray();
					dictionary = pool.ToDictionary(((string cls, float weight) e) => e.cls, ((string cls, float weight) e) => e.weight);
				}
			}
			string[] array3 = ((exclude == null) ? array : array.Where((string c) => c != exclude).ToArray());
			if (array3.Length == 0)
			{
				return ImplementedClasses[0];
			}
			if (stats == null)
			{
				return array3[rng.Next(array3.Length)];
			}
			int num = 10;
			int num2 = 5;
			float[] array4 = new float[array3.Length];
			float num3 = 0f;
			for (int i = 0; i < array3.Length; i++)
			{
				float num4 = num;
				if (ClassStatAffinity.TryGetValue(array3[i], out (IsekaiStatType, IsekaiStatType) value))
				{
					int stat = stats.GetStat(value.Item1);
					int stat2 = stats.GetStat(value.Item2);
					num4 += (float)Math.Max(0, stat - num2) * 3f;
					num4 += (float)Math.Max(0, stat2 - num2) * 1f;
				}
				if (dictionary != null && dictionary.TryGetValue(array3[i], out var value2))
				{
					num4 *= value2;
				}
				array4[i] = num4;
				num3 += num4;
			}
			double num5 = rng.NextDouble() * (double)num3;
			float num6 = 0f;
			for (int j = 0; j < array3.Length; j++)
			{
				num6 += array4[j];
				if (num5 < (double)num6)
				{
					return array3[j];
				}
			}
			return array3[array3.Length - 1];
		}

		internal static PassiveTreeDef FindTree(string treeClass)
		{
			return DefDatabase<PassiveTreeDef>.AllDefs.FirstOrDefault((PassiveTreeDef t) => t.treeClass == treeClass);
		}

		internal static void SpendPointsOnTree(PassiveTreeTracker tracker, PassiveTreeDef tree, int budget)
		{
			if (tree?.nodes == null || tree.nodes.Count == 0)
			{
				return;
			}
			PassiveNodeRecord startNode = tree.GetStartNode();
			if (startNode == null)
			{
				return;
			}
			if (!tracker.IsUnlocked(startNode.nodeId))
			{
				int cost = startNode.cost;
				if (budget < cost)
				{
					return;
				}
				ForceUnlock(tracker, startNode.nodeId);
				budget -= cost;
			}
			if (budget <= 0)
			{
				return;
			}
			int num = tree.nodes.Count + 10;
			for (int i = 0; i < num; i++)
			{
				if (budget <= 0)
				{
					break;
				}
				List<PassiveNodeRecord> list = BuildFrontier(tracker, tree);
				if (list.Count == 0)
				{
					break;
				}
				Shuffle(list);
				bool flag = false;
				foreach (PassiveNodeRecord item in list)
				{
					if (budget < item.cost || !CanUnlockForAutoAssign(tracker, tree, item))
					{
						continue;
					}
					ForceUnlock(tracker, item.nodeId);
					budget -= item.cost;
					flag = true;
					break;
				}
				if (!flag)
				{
					break;
				}
			}
		}

		private static List<PassiveNodeRecord> BuildFrontier(PassiveTreeTracker tracker, PassiveTreeDef tree)
		{
			List<PassiveNodeRecord> list = new List<PassiveNodeRecord>();
			foreach (PassiveNodeRecord node in tree.nodes)
			{
				if (tracker.IsUnlocked(node.nodeId) || node.nodeType == PassiveNodeType.Start)
				{
					continue;
				}
				List<string> neighbors = tree.GetNeighbors(node.nodeId);
				if (neighbors.Count == 0)
				{
					continue;
				}
				if (node.requireAllConnected)
				{
					bool flag = true;
					foreach (string item in neighbors)
					{
						if (!tracker.IsUnlocked(item))
						{
							flag = false;
							break;
						}
					}
					if (flag)
					{
						list.Add(node);
					}
					continue;
				}
				foreach (string item2 in neighbors)
				{
					if (tracker.IsUnlocked(item2))
					{
						list.Add(node);
						break;
					}
				}
			}
			return list;
		}

		private static bool CanUnlockForAutoAssign(PassiveTreeTracker tracker, PassiveTreeDef tree, PassiveNodeRecord node)
		{
			if (tracker.IsUnlocked(node.nodeId))
			{
				return false;
			}
			List<string> neighbors = tree.GetNeighbors(node.nodeId);
			if (node.requireAllConnected)
			{
				foreach (string item in neighbors)
				{
					if (!tracker.IsUnlocked(item))
					{
						return false;
					}
				}
				return true;
			}
			foreach (string item2 in neighbors)
			{
				if (tracker.IsUnlocked(item2))
				{
					return true;
				}
			}
			return false;
		}

		private static void ForceUnlock(PassiveTreeTracker tracker, string nodeId)
		{
			tracker.ForceUnlockNode(nodeId);
		}

		private static void Shuffle<T>(List<T> list)
		{
			for (int num = list.Count - 1; num > 0; num--)
			{
				int index = rng.Next(num + 1);
				T value = list[num];
				list[num] = list[index];
				list[index] = value;
			}
		}
	}
