{
	[StaticConstructorOnStartup]
	public static class GuildQuestSettings
	{
		static GuildQuestSettings()
		{
			ApplySettings();
		}

		public static void ApplySettings()
		{
			IncidentDef namedSilentFail = DefDatabase<IncidentDef>.GetNamedSilentFail("Isekai_HuntSpawn");
			if (namedSilentFail == null || IsekaiMod.Settings == null)
			{
				return;
			}
			if (!IsekaiMod.Settings.EnableGuildQuests)
			{
				namedSilentFail.baseChance = 0f;
				if (Prefs.DevMode)
				{
					Log.Message("[Isekai] Guild quests DISABLED");
				}
				return;
			}
			namedSilentFail.baseChance = 0.1f;
			namedSilentFail.minRefireDays = 0.1f;
			if (Prefs.DevMode)
			{
				Log.Message($"[Isekai] Guild quest frequency set to: every {IsekaiMod.Settings.GuildQuestFrequency} days");
			}
		}
	}
