			//IL_0291: Unknown result type (might be due to invalid IL or missing references)
			HashSet<Thing> visited = new HashSet<Thing>();
			List<Thing> broken = new List<Thing>();
			foreach (Map map in Find.Maps)
			{
				foreach (Thing item in map.listerThings.AllThings.ToList())
				{
					Check(item);
				}
			}
			foreach (Caravan caravan in Find.WorldObjects.Caravans)
			{
				foreach (Thing item2 in CaravanInventoryUtility.AllInventoryItems(caravan))
				{
					Check(item2);
				}
			}
			if (broken.Count == 0)
			{
				Log.Message($"[Isekai] Broken-stuff scan: clean. Checked {visited.Count} things, none has an invalid material.");
				return;
			}
			StringBuilder stringBuilder = new StringBuilder();
			stringBuilder.AppendLine($"[Isekai] Broken-stuff scan: found {broken.Count} item(s) whose material is NOT a valid stuff (stuffProps == null).");
			stringBuilder.AppendLine("This is what makes vanilla StatWorker.GetValueUnfinalized throw during the wealth recount.");
			stringBuilder.AppendLine("The mod owning the MATERIAL below is the one to report this to:");
			foreach (IGrouping<string, Thing> item3 in from t in broken
				group t by ((Def)t.def).defName + "|" + ((Def)t.Stuff).defName)
			{
				Thing val = item3.First();
				object arg = item3.Count();
				string defName = ((Def)val.def).defName;
				ModContentPack modContentPack = ((Def)val.def).modContentPack;
				stringBuilder.AppendLine(string.Format("  x{0}  item {1} (mod: {2})", arg, defName, ((modContentPack != null) ? modContentPack.Name : null) ?? "unknown"));
				string[] obj = new string[5]
				{
					"        material ",
					((Def)val.Stuff).defName,
					" (mod: ",
					null,
					null
				};
				ModContentPack modContentPack2 = ((Def)val.Stuff).modContentPack;
				obj[3] = ((modContentPack2 != null) ? modContentPack2.Name : null) ?? "unknown";
				obj[4] = ") has no stuffProps";
				stringBuilder.AppendLine(string.Concat(obj));
				object obj2;
				if (!val.Spawned)
				{
					obj2 = "not spawned (in a container/caravan)";
				}
				else
				{
					IntVec3 position = val.Position;
					obj2 = ((object)(IntVec3)(ref position)/*cast due to .constrained prefix*/).ToString();
				}
				stringBuilder.AppendLine("        example location: " + (string)obj2);
			}
			Log.Error(stringBuilder.ToString());
			void Check(Thing t)
			{
				if (t != null && visited.Add(t))
				{
					if (t.Stuff != null && t.Stuff.stuffProps == null)
					{
						broken.Add(t);
					}
					MinifiedThing val2 = (MinifiedThing)(object)((t is MinifiedThing) ? t : null);
					if (val2 != null)
					{
						Check(val2.InnerThing);
					}
					IThingHolder val3 = (IThingHolder)(object)((t is IThingHolder) ? t : null);
					if (val3 != null)
					{
						foreach (Thing item4 in ThingOwnerUtility.GetAllThingsRecursively(val3, true))
						{
							Check(item4);
						}
					}
				}
			}
		}
	}
