		}

		public static void RegisterBountyPawn(Pawn pawn)
		{
			if (pawn != null)
			{
				bountyPawnIds.Add(((Thing)pawn).thingIDNumber);
			}
		}

		public static void UnregisterBountyPawn(Pawn pawn)
		{
			if (pawn != null)
			{
				bountyPawnIds.Remove(((Thing)pawn).thingIDNumber);
			}
		}

		public static string GetQuestTypeSuffix(QuestRank rank, bool isBounty = false)
		{
			if (isBounty)
			{
				return "_Bounty";
			}
			if (rank >= QuestRank.S)
			{
				return "_Raid";
			}
			if (rank >= QuestRank.B)
			{
				return "_Expedition";
			}
			return "_Hunt";
		}

		public static int GetBountyPackSize(QuestRank rank)
		{
			return rank switch
			{
				QuestRank.B => Rand.RangeInclusive(3, 5), 
				QuestRank.A => Rand.RangeInclusive(5, 8), 
				_ => 1, 
			};
		}

		public static string GetQuestTypeName(QuestRank rank, bool isBounty = false)
		{
			//IL_000b: Unknown result type (might be due to invalid IL or missing references)
			//IL_002a: Unknown result type (might be due to invalid IL or missing references)
			//IL_005b: Unknown result type (might be due to invalid IL or missing references)
			//IL_0049: Unknown result type (might be due to invalid IL or missing references)
			if (isBounty)
			{
				return TaggedString.op_Implicit(Translator.Translate("Isekai_QuestType_Bounty"));
			}
			if (rank >= QuestRank.S)
			{
				return TaggedString.op_Implicit(Translator.Translate("Isekai_QuestType_Raid"));
			}
			if (rank >= QuestRank.B)
			{
				return TaggedString.op_Implicit(Translator.Translate("Isekai_QuestType_Expedition"));
			}
			return TaggedString.op_Implicit(Translator.Translate("Isekai_QuestType_Hunt"));
		}

		protected override bool CanFireNowSub(IncidentParms parms)
		{
			if (IsekaiMod.Settings != null && !IsekaiMod.Settings.EnableGuildQuests)
			{
				return false;
			}
			IIncidentTarget target = parms.target;
			Map val = (Map)(object)((target is Map) ? target : null);
			if (val == null)
			{
				return false;
			}
			if (!GenCollection.Any<Pawn>(val.mapPawns.FreeColonists, (Predicate<Pawn>)((Pawn p) => ((ThingWithComps)p).GetComp<IsekaiComponent>() != null)))
			{
				return false;
			}
			return true;
		}

		protected override bool TryExecuteWorker(IncidentParms parms)
		{
			if (IsekaiMod.Settings != null && !IsekaiMod.Settings.EnableGuildQuests)
			{
				return false;
			}
			IIncidentTarget target = parms.target;
			Map val = (Map)(object)((target is Map) ? target : null);
			if (val == null)
			{
				return false;
			}
			QuestRank questRank = DetermineRankForColony(val);
			int num = IsekaiMod.Settings?.MinQuestRank ?? 0;
			if (num > 0 && (int)questRank < num)
			{
				questRank = (QuestRank)num;
			}
			if (questRank >= QuestRank.C && Rand.Chance(0.4f))
			{
				PawnKindDef val2 = SelectHostilePawnForRank(questRank);
				if (val2 != null)
				{
					float xpReward = CalculateXPReward(questRank, val2.combatPower);
					float silverReward = CalculateSilverReward(questRank, val2.combatPower);
					CreateHuntQuest(val2, questRank, xpReward, silverReward, val, isBounty: true);
					return true;
				}
				Log.Warning("[Isekai Hunt] No suitable hostile pawn found for bounty, falling back to creature hunt");
				bool flag = false;
			}
			PawnKindDef val3 = SelectCreatureForRank(questRank, parms.points);
			if (val3 == null)
			{
				Log.Warning("[Isekai Hunt] No suitable creature found");
				return false;
			}
			float xpReward2 = CalculateXPReward(questRank, val3.combatPower);
			float silverReward2 = CalculateSilverReward(questRank, val3.combatPower);
			CreateHuntQuest(val3, questRank, xpReward2, silverReward2, val);
			return true;
		}

