		private static int GetMinDistance(QuestRank rank)
		{
			return rank switch
			{
				QuestRank.B => 1, 
				QuestRank.A => 2, 
				QuestRank.S => 3, 
				QuestRank.SS => 4, 
				QuestRank.SSS => 5, 
				_ => 0, 
			};
		}

		private static int GetMaxDistance(QuestRank rank)
		{
			return rank switch
			{
				QuestRank.B => 3, 
				QuestRank.A => 4, 
				QuestRank.S => 5, 
				QuestRank.SS => 6, 
				QuestRank.SSS => 8, 
				_ => 2, 
			};
		}

		private static int GetQuestDifficulty(QuestRank rank)
		{
			switch (rank)
			{
			case QuestRank.F:
			case QuestRank.E:
				return 1;
			case QuestRank.D:
			case QuestRank.C:
				return 2;
			case QuestRank.B:
			case QuestRank.A:
				return 3;
			case QuestRank.S:
			case QuestRank.SS:
				return 4;
			case QuestRank.SSS:
				return 5;
			default:
				return 1;
			}
		}

