		private static int GetRuneItemRank(string defName)
		{
			if (defName.EndsWith("_V"))
			{
				return 5;
			}
			if (defName.EndsWith("_IV"))
			{
				return 4;
			}
			if (defName.EndsWith("_III"))
			{
				return 3;
			}
			if (defName.EndsWith("_II"))
			{
				return 2;
			}
			return 1;
		}

