		public static string GetRankColor(QuestRank rank)
		{
			if (rank <= QuestRank.D)
			{
				return "#FFFFFF";
			}
			if (rank >= QuestRank.C && rank <= QuestRank.A)
			{
				return "#5599FF";
			}
			if (rank == QuestRank.S)
			{
				return "#FFD700";
			}
			if (rank >= QuestRank.SS)
			{
				return "#FF4444";
			}
			return "#FFFFFF";
		}

