			float num2 = isekaiPawnsOnMap.Max((Pawn p) => IsekaiComponent.GetCached(p)?.Level ?? 1);
			float num3 = Mathf.Max(num, num2 * 0.75f);
			float wealthTotal = map.wealthWatcher.WealthTotal;
			int num4 = ((!(wealthTotal < 50000f)) ? ((wealthTotal < 150000f) ? 1 : ((wealthTotal < 300000f) ? 2 : ((wealthTotal < 500000f) ? 3 : ((wealthTotal < 800000f) ? 4 : ((wealthTotal < 1200000f) ? 5 : ((wealthTotal < 2000000f) ? 6 : ((wealthTotal < 3000000f) ? 7 : 8))))))) : 0);
			QuestRank questRank = ((num3 >= 150f) ? QuestRank.SSS : ((num3 >= 80f) ? QuestRank.SS : ((num3 >= 50f) ? QuestRank.S : ((num3 >= 35f) ? QuestRank.A : ((num3 >= 22f) ? QuestRank.B : ((num3 >= 14f) ? QuestRank.C : ((num3 >= 11f) ? QuestRank.D : ((num3 >= 6f) ? QuestRank.E : QuestRank.F))))))));
			if (num4 >= 6 && questRank < QuestRank.SSS)
			{
				questRank++;
			}
			Dictionary<QuestRank, float> dictionary = new Dictionary<QuestRank, float>();
			for (int i = 0; i <= (int)questRank; i++)
			{
				QuestRank questRank2 = (QuestRank)i;
				float num5 = questRank2 switch
				{
					QuestRank.F => 50f, 
					QuestRank.E => 45f, 
					QuestRank.D => 40f, 
					QuestRank.C => 35f, 
					QuestRank.B => 30f, 
					QuestRank.A => 25f, 
					QuestRank.S => 20f, 
					QuestRank.SS => 15f, 
					QuestRank.SSS => 10f, 
					_ => 50f, 
				};
				if (questRank2 >= QuestRank.C)
				{
					float num6 = 1f + (float)num4 * 0.25f;
					num5 *= num6;
				}
				else if (num4 >= 4)
				{
					float num7 = 1f - (float)(num4 - 3) * 0.12f;
					num5 *= Mathf.Max(0.15f, num7);
				}
				dictionary[questRank2] = num5;
			}
			float num8 = dictionary.Values.Sum();
			float num9 = Rand.Range(0f, num8);
			float num10 = 0f;
			foreach (KeyValuePair<QuestRank, float> item in dictionary.OrderBy((KeyValuePair<QuestRank, float> x) => x.Key))
			{
				num10 += item.Value;
				if (num9 <= num10)
				{
					return item.Key;
				}
			}
			return questRank;
		}

		private static bool IsVehicleDef(ThingDef def)
		{
			if (def == null)
			{
				return false;
			}
			Type type = def.thingClass;
			while (type != null)
			{
				string text = type.FullName ?? "";
				if (text.IndexOf("Vehicle", StringComparison.OrdinalIgnoreCase) >= 0)
				{
					return true;
				}
				if (text.StartsWith("SRTS", StringComparison.OrdinalIgnoreCase))
				{
					return true;
				}
				type = type.BaseType;
			}
			string text2 = ((Def)def).defName ?? "";
			if (text2.StartsWith("VVE_", StringComparison.OrdinalIgnoreCase) || text2.IndexOf("Vehicle", StringComparison.OrdinalIgnoreCase) >= 0 || text2.StartsWith("DVVE_", StringComparison.OrdinalIgnoreCase) || text2.StartsWith("SRTS_", StringComparison.OrdinalIgnoreCase))
			{
				return true;
			}
			string text3 = ((Def)def).label?.ToLower() ?? "";
			if (text3.Contains("vehicle") || text3.Contains("shuttle") || text3.Contains("transport pod"))
			{
				return true;
			}
			if (def.comps != null)
			{
				foreach (CompProperties comp in def.comps)
				{
					string text4 = comp?.compClass?.FullName ?? "";
					if (text4.IndexOf("Vehicle", StringComparison.OrdinalIgnoreCase) >= 0 || text4.StartsWith("SRTS", StringComparison.OrdinalIgnoreCase))
					{
						return true;
					}
				}
			}
			ModContentPack modContentPack = ((Def)def).modContentPack;
			string text5 = ((modContentPack == null) ? null : modContentPack.PackageId?.ToLower()) ?? "";
			if (text5.Contains("vehicles") || text5.Contains("srts"))
			{
				return true;
			}
			return false;
		}

