		public static PawnKindDef SelectCreatureForRank(QuestRank rank, float points = 0f)
		{
			//IL_03b1: Unknown result type (might be due to invalid IL or missing references)
			List<PawnKindDef> list = (from pk in DefDatabase<PawnKindDef>.AllDefs
				where pk?.race != null && pk.RaceProps != null && !pk.RaceProps.Humanlike && !pk.RaceProps.Dryad && pk.combatPower > 0f && !IsVehicleDef(pk.race) && !IsTransformingCreature(pk) && !IsFactionDisabled(pk) && !IsAnomalyEntity(pk) && !IsRoMCreature(pk) && !IsSuicidalMech(pk) && !IsUserBlacklistedMod(pk) && IsUserWhitelistedMod(pk)
				orderby pk.combatPower
				select pk).ToList();
			if (!GenCollection.Any<PawnKindDef>(list))
			{
				Log.Warning("[Isekai Hunt] No suitable creatures found!");
				return null;
			}
			MobRankTier target = (MobRankTier)rank;
			var source = (from pk in list
				select new
				{
					kind = pk,
					tier = MobRankCalculator.RankForKind(pk)
				} into x
				where x.tier < MobRankTier.Nation
				select x).ToList();
			List<PawnKindDef> list2 = (from x in source
				where x.tier == target
				select x.kind).ToList();
			int floor = (int)(target - 1);
			while (list2.Count < 3 && floor >= 0)
			{
				list2 = (from x in source
					where x.tier <= target && (int)x.tier >= floor
					select x.kind).ToList();
				floor--;
			}
			list2 = list2.OrderBy((PawnKindDef pk) => pk.combatPower).ToList();
			if (rank >= QuestRank.S && list2.Count > 1)
			{
				List<PawnKindDef> list3 = list2.Where((PawnKindDef pk) => pk.RaceProps.predator || pk.RaceProps.manhunterOnDamageChance > 0.3f || pk.RaceProps.manhunterOnTameFailChance > 0.3f || ((Def)(pk.RaceProps.FleshType?)).defName == "Mechanoid" || ((Def)(pk.RaceProps.FleshType?)).defName == "Insectoid" || pk.RaceProps.Insect).ToList();
				if (GenCollection.Any<PawnKindDef>(list3))
				{
					list2 = list3;
				}
			}
			if (!GenCollection.Any<PawnKindDef>(list2))
			{
				Log.Warning($"[Isekai Hunt] Nothing ranked {target} or below is huntable, using the weakest available.");
				list2 = (from x in source
					where x.tier <= target
					select x.kind into pk
					orderby pk.combatPower
					select pk).ToList();
				if (!GenCollection.Any<PawnKindDef>(list2))
				{
					list2 = (from x in source
						select x.kind into pk
						orderby pk.combatPower
						select pk).ToList();
				}
			}
			int count = list2.Count;
			List<PawnKindDef> list4;
			if (rank >= QuestRank.S)
			{
				int count2 = count * 40 / 100;
				list4 = list2.Skip(count2).ToList();
			}
			else if (rank >= QuestRank.B)
			{
				int num = count * 10 / 100;
				int num2 = count * 90 / 100;
				list4 = list2.Skip(num).Take(Mathf.Max(num2 - num, 1)).ToList();
			}
			else
			{
				list4 = list2;
			}
			if (!GenCollection.Any<PawnKindDef>(list4))
			{
				list4 = list2;
			}
			PawnKindDef val = GenCollection.RandomElement<PawnKindDef>((IEnumerable<PawnKindDef>)list4);
			Log.Message($"[Isekai Hunt] Selected '{((Def)val).LabelCap}' (CP:{val.combatPower:F0}, " + $"rank {MobRankCalculator.RankForKind(val)}) for a {rank} contract " + $"from a pool of {list4.Count}.");
			return val;
		}

		public static PawnKindDef SelectHostilePawnForRank(QuestRank rank)
		{
			//IL_050d: Unknown result type (might be due to invalid IL or missing references)
			List<Faction> first = Find.FactionManager.AllFactions.Where((Faction f) => f != null && f != Faction.OfPlayer && FactionUtility.HostileTo(f, Faction.OfPlayer) && !f.defeated && !f.Hidden).ToList();
			List<Faction> second = Find.FactionManager.AllFactions.Where((Faction f) => f != null && f != Faction.OfPlayer && !f.defeated && !f.Hidden && (f.def.permanentEnemy || ((Def)f.def).defName.Contains("Pirate") || ((Def)f.def).defName.Contains("Rough"))).ToList();
			List<Faction> list = first.Union(second).Distinct().ToList();
			if (!GenCollection.Any<Faction>(list))
			{
				Faction ofAncientsHostile = Faction.OfAncientsHostile;
				if (ofAncientsHostile != null)
				{
					list.Add(ofAncientsHostile);
				}
			}
			HashSet<PawnKindDef> hashSet = new HashSet<PawnKindDef>();
			foreach (Faction item in list)
			{
				if (item.def.pawnGroupMakers == null)
				{
					continue;
				}
				foreach (PawnGroupMaker pawnGroupMaker in item.def.pawnGroupMakers)
				{
					if (pawnGroupMaker.options != null)
					{
						foreach (PawnGenOption option in pawnGroupMaker.options)
						{
							PawnKindDef kind = option.kind;
							if (kind != null)
							{
								RaceProperties raceProps = kind.RaceProps;
								if (((raceProps != null) ? new bool?(raceProps.Humanlike) : ((bool?)null)) == true && option.kind.combatPower > 0f)
								{
									hashSet.Add(option.kind);
								}
							}
						}
					}
					if (pawnGroupMaker.traders != null)
					{
						foreach (PawnGenOption trader in pawnGroupMaker.traders)
						{
							PawnKindDef kind2 = trader.kind;
							if (kind2 != null)
							{
								RaceProperties raceProps2 = kind2.RaceProps;
								if (((raceProps2 != null) ? new bool?(raceProps2.Humanlike) : ((bool?)null)) == true && trader.kind.combatPower > 0f)
								{
									hashSet.Add(trader.kind);
								}
							}
						}
					}
					if (pawnGroupMaker.guards == null)
					{
						continue;
					}
					foreach (PawnGenOption guard in pawnGroupMaker.guards)
					{
						PawnKindDef kind3 = guard.kind;
						if (kind3 != null)
						{
							RaceProperties raceProps3 = kind3.RaceProps;
							if (((raceProps3 != null) ? new bool?(raceProps3.Humanlike) : ((bool?)null)) == true && guard.kind.combatPower > 0f)
							{
								hashSet.Add(guard.kind);
							}
						}
					}
				}
			}
			if (!GenCollection.Any<PawnKindDef>(hashSet))
			{
				Log.Warning("[Isekai Hunt] No hostile humanlike pawn kinds found for bounty quest");
				return null;
			}
			hashSet.RemoveWhere((PawnKindDef pk) => !IsUserWhitelistedMod(pk));
			if (!GenCollection.Any<PawnKindDef>(hashSet))
			{
				Log.Warning("[Isekai Hunt] No hostile humanlike pawn kinds passed the quest creature whitelist");
				return null;
			}
			float minCP;
			float maxCP;
			switch (rank)
			{
			case QuestRank.SSS:
				minCP = 200f;
				maxCP = 9999f;
				break;
			case QuestRank.SS:
				minCP = 150f;
				maxCP = 9999f;
				break;
			case QuestRank.S:
				minCP = 120f;
				maxCP = 9999f;
				break;
			case QuestRank.A:
				minCP = 80f;
				maxCP = 250f;
				break;
			case QuestRank.B:
				minCP = 50f;
				maxCP = 150f;
				break;
			case QuestRank.C:
				minCP = 30f;
				maxCP = 100f;
				break;
			default:
				minCP = 0f;
				maxCP = 80f;
				break;
			}
			List<PawnKindDef> list2 = hashSet.Where((PawnKindDef pk) => pk.combatPower >= minCP && pk.combatPower <= maxCP).ToList();
			if (!GenCollection.Any<PawnKindDef>(list2))
			{
				list2 = hashSet.Where((PawnKindDef pk) => pk.combatPower >= minCP).ToList();
				if (!GenCollection.Any<PawnKindDef>(list2))
				{
					list2 = hashSet.ToList();
				}
			}
			PawnKindDef val = GenCollection.RandomElement<PawnKindDef>((IEnumerable<PawnKindDef>)list2);
			Log.Message($"[Isekai Hunt] Selected bounty target '{((Def)val).LabelCap}' (CP:{val.combatPower:F0}) for {rank} rank from pool of {list2.Count} hostile pawns");
			return val;
		}

		public static Faction GetHostileFactionForBounty()
		{
			List<Faction> list = Find.FactionManager.AllFactions.Where((Faction f) => f != null && !f.defeated && !f.Hidden && f != Faction.OfPlayer && (f.def.permanentEnemy || ((Def)f.def).defName.Contains("Pirate"))).ToList();
			if (GenCollection.Any<Faction>(list))
			{
				return GenCollection.RandomElement<Faction>((IEnumerable<Faction>)list);
			}
			List<Faction> list2 = Find.FactionManager.AllFactions.Where((Faction f) => f != null && !f.defeated && !f.Hidden && f != Faction.OfPlayer && FactionUtility.HostileTo(f, Faction.OfPlayer)).ToList();
			if (GenCollection.Any<Faction>(list2))
			{
				return GenCollection.RandomElement<Faction>((IEnumerable<Faction>)list2);
			}
			return Faction.OfAncientsHostile;
		}

		public static void ForceBountyPawnRank(Pawn pawn, QuestRank questRank)
		{
			if (pawn == null || !pawn.RaceProps.Humanlike)
			{
				return;
			}
			string text = questRank.ToString();
			IsekaiComponent comp = ((ThingWithComps)pawn).GetComp<IsekaiComponent>();
			if (comp != null)
			{
				if (comp.stats == null)
				{
					comp.stats = new IsekaiStatAllocation();
				}
				PawnStatGenerator.GenerateStatsForRank(text, comp.stats, pawn);
				comp.currentLevel = PawnStatGenerator.CalculateLevelFromStats(comp.stats);
				comp.currentXP = 0;
				int minLevelForRank = PawnStatGenerator.GetMinLevelForRank(text);
				if (comp.currentLevel < minLevelForRank)
				{
					comp.currentLevel = minLevelForRank;
				}
				comp.statsInitialized = true;
				PawnStatGenerator.AssignRankTrait(pawn, text);
				RegisterBountyPawn(pawn);
				Log.Message($"[Isekai Hunt] Forced bounty pawn {((Entity)pawn).LabelCap} to {text}-Rank (level {comp.currentLevel})");
			}
			else
			{
				Log.Warning("[Isekai Hunt] Could not force rank on " + ((Entity)pawn).LabelCap + ": IsekaiComponent is null");
			}
			if (IsekaiLevelingSettings.EnableForgeSystem)
			{
				ApplyForgeEnhancementsForRank(pawn, questRank);
			}
		}

		public static void ApplyForgeEnhancementsForRank(Pawn pawn, QuestRank rank)
		{
			int maxRefinement;
			float runeChance;
			int maxRuneRank;
			switch (rank)
			{
			case QuestRank.SSS:
				maxRefinement = 10;
				runeChance = 1f;
				maxRuneRank = 5;
				break;
			case QuestRank.SS:
				maxRefinement = 9;
				runeChance = 0.85f;
				maxRuneRank = 4;
				break;
			case QuestRank.S:
				maxRefinement = 8;
				runeChance = 0.75f;
				maxRuneRank = 3;
				break;
			case QuestRank.A:
				maxRefinement = 6;
				runeChance = 0.65f;
				maxRuneRank = 3;
				break;
			case QuestRank.B:
				maxRefinement = 4;
				runeChance = 0.5f;
				maxRuneRank = 2;
				break;
			case QuestRank.C:
				maxRefinement = 3;
				runeChance = 0.35f;
				maxRuneRank = 1;
				break;
			case QuestRank.D:
				maxRefinement = 2;
				runeChance = 0.2f;
				maxRuneRank = 1;
				break;
			default:
				maxRefinement = 1;
				runeChance = 0.1f;
				maxRuneRank = 1;
