		private Dictionary<int, HuntData> activeHunts = new Dictionary<int, HuntData>();

		private int lastQuestTick = -1;

		private const int TicksPerDay = 60000;

		private HashSet<int> paidQuests = new HashSet<int>();

		public IsekaiHuntTracker(Game game)
		{
		}

		private int GetTicksBetweenQuests()
		{
			float num = IsekaiMod.Settings?.GuildQuestFrequency ?? 1f;
			return (int)(num * 60000f);
		}

		public override void GameComponentTick()
		{
			((GameComponent)this).GameComponentTick();
			if ((IsekaiMod.Settings != null && !IsekaiMod.Settings.EnableGuildQuests) || Find.TickManager.TicksGame % 250 != 0)
			{
				return;
			}
			QuestPart_IsekaiLocalHunt.TryResolvePendingSpawns();
			CheckForStuckQuests();
			if (lastQuestTick < 0)
			{
				lastQuestTick = Find.TickManager.TicksGame;
				return;
			}
			int ticksBetweenQuests = GetTicksBetweenQuests();
			int num = Find.TickManager.TicksGame - lastQuestTick;
			if (num >= ticksBetweenQuests)
			{
				TrySpawnDailyHuntQuest();
			}
		}

		private void TrySpawnDailyHuntQuest()
		{
			if (IsekaiMod.Settings != null && !IsekaiMod.Settings.EnableGuildQuests)
			{
				return;
			}
			Map val = GenCollection.FirstOrDefault<Map>(Find.Maps, (Predicate<Map>)((Map m) => m.IsPlayerHome && GenCollection.Any<Pawn>(m.mapPawns.FreeColonists, (Predicate<Pawn>)((Pawn p) => ((ThingWithComps)p).GetComp<IsekaiComponent>() != null))));
			if (val == null)
			{
				return;
			}
			IncidentDef namedSilentFail = DefDatabase<IncidentDef>.GetNamedSilentFail("Isekai_HuntSpawn");
			if (namedSilentFail == null)
			{
				Log.Warning("[Isekai Hunt] Could not find Isekai_HuntSpawn incident def for scheduled quest");
				return;
			}
			IncidentParms val2 = StorytellerUtility.DefaultParmsNow(namedSilentFail.category, (IIncidentTarget)(object)val);
			val2.target = (IIncidentTarget)(object)val;
			IncidentWorker_IsekaiHunt incidentWorker_IsekaiHunt = namedSilentFail.Worker as IncidentWorker_IsekaiHunt;
			bool flag = false;
			if (incidentWorker_IsekaiHunt != null)
			{
				flag = ((IncidentWorker)incidentWorker_IsekaiHunt).TryExecute(val2);
			}
			float num = IsekaiMod.Settings?.GuildQuestFrequency ?? 1f;
			if (flag)
			{
				lastQuestTick = Find.TickManager.TicksGame;
				if (Prefs.DevMode)
				{
					Log.Message($"[Isekai Hunt] Quest spawned at tick {lastQuestTick}. Next in {num} days.");
				}
				return;
			}
			int num2 = GetTicksBetweenQuests() / 4;
			lastQuestTick = Find.TickManager.TicksGame - GetTicksBetweenQuests() + num2;
			if (Prefs.DevMode)
			{
				Log.Warning($"[Isekai Hunt] Quest failed to spawn, will retry in {(float)num2 / 60000f:F2} days");
			}
		}

		private void CheckForStuckQuests()
		{
			//IL_0033: Unknown result type (might be due to invalid IL or missing references)
			//IL_0039: Invalid comparison between Unknown and I4
			try
			{
				if (Find.QuestManager == null)
				{
					return;
				}
				foreach (Quest item in Find.QuestManager.QuestsListForReading)
				{
					if ((int)item.State != 1)
					{
						continue;
					}
					foreach (QuestPart item2 in item.PartsListForReading)
					{
						if (item2 is QuestPart_IsekaiLocalHunt questPart_IsekaiLocalHunt)
						{
							questPart_IsekaiLocalHunt.CheckSafetyNet();
						}
						else if (item2 is QuestPart_IsekaiWorldHunt questPart_IsekaiWorldHunt)
						{
							questPart_IsekaiWorldHunt.CheckSafetyNet();
						}
						else if (item2 is QuestPart_WorldBoss questPart_WorldBoss)
						{
							questPart_WorldBoss.CheckSafetyNet();
						}
					}
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Hunt] Safety net check error: " + ex.Message);
			}
		}

		private bool TryClaimPayout(int questId, string path)
		{
			if (questId < 0)
			{
				return true;
			}
			if (paidQuests == null)
			{
				paidQuests = new HashSet<int>();
			}
			if (paidQuests.Add(questId))
			{
				return true;
			}
			Log.Error($"[Isekai Hunt] BLOCKED a duplicate payout for quest {questId} " + "(path: " + path + "). The quest had already been paid. This is the reward loop guard doing its job - please report the preceding log lines.");
			return false;
		}

		private void PurgeQuestEntries(int questId, int exceptThingId)
		{
			if (questId < 0)
			{
				return;
			}
			List<int> list = null;
			foreach (KeyValuePair<int, HuntData> activeHunt in activeHunts)
			{
				if (activeHunt.Value.questId == questId && activeHunt.Key != exceptThingId)
				{
					(list ?? (list = new List<int>())).Add(activeHunt.Key);
				}
			}
			if (list != null)
			{
				for (int i = 0; i < list.Count; i++)
				{
					activeHunts.Remove(list[i]);
				}
				Log.Message($"[Isekai Hunt] Cleared {list.Count} sibling pack entries for quest {questId} after payout.");
			}
		}

