		private void AwardXP(float totalXP, Pawn killer = null, Pawn creature = null, Map questSiteMap = null)
		{
			List<Pawn> list = null;
			Map val = questSiteMap ?? ((killer != null) ? ((Thing)killer).Map : null) ?? ((creature != null) ? ((Thing)creature).MapHeld : null) ?? ((creature != null) ? ((Thing)creature).Map : null);
			if (val != null)
			{
				list = IsekaiComponent.GetIsekaiPawnsOnMap(val);
			}
			if (list == null || !GenCollection.Any<Pawn>(list))
			{
				list = IsekaiComponent.GetIsekaiPawnsAllMaps();
			}
			if (!GenCollection.Any<Pawn>(list))
			{
				list = IsekaiComponent.GetIsekaiPawnsInCaravans();
			}
			if (!GenCollection.Any<Pawn>(list))
			{
				return;
			}
			float num = IsekaiMod.Settings?.XPMultiplier ?? 3f;
			if (num <= 0f)
			{
				num = 1f;
			}
			int num2 = Mathf.RoundToInt(totalXP / num / (float)list.Count);
			foreach (Pawn item in list)
			{
				IsekaiComponent.GetCached(item)?.GainXP(num2, "HuntReward");
			}
			int num3 = 0;
			Map val2 = val ?? Find.AnyPlayerHomeMap;
			if (val2 != null)
			{
				foreach (Pawn item2 in val2.mapPawns.SpawnedPawnsInFaction(Faction.OfPlayer))
				{
					if (!item2.RaceProps.Humanlike && (!item2.RaceProps.Animal || IsCombatPet(item2)))
					{
						MobRankComponent mobRankComponent = ThingCompUtility.TryGetComp<MobRankComponent>((Thing)(object)item2);
						if (mobRankComponent != null)
						{
							mobRankComponent.GainXP(num2, "HuntReward");
							num3++;
						}
					}
				}
			}
			Log.Message(string.Format("[Isekai Hunt] Awarded {0} XP to {1} colonists and {2} creatures (quest site map: {3})", num2, list.Count, num3, ((object)val)?.ToString() ?? "none"));
		}

		public static bool IsBondedToColonist(Pawn animal)
		{
			if (animal?.relations == null)
			{
				return false;
			}
			foreach (DirectPawnRelation directRelation in animal.relations.DirectRelations)
			{
				if (directRelation.def == PawnRelationDefOf.Bond && directRelation.otherPawn != null && !directRelation.otherPawn.Dead)
				{
					return true;
				}
			}
			return false;
		}

		public static bool IsCombatPet(Pawn animal)
		{
			if (animal == null)
			{
				return false;
			}
			if (IsBondedToColonist(animal))
			{
				return true;
			}
			try
			{
				if (animal.training != null && TrainableDefOf.Release != null && animal.training.HasLearned(TrainableDefOf.Release))
				{
					return true;
				}
			}
			catch
			{
			}
			Pawn_PlayerSettings playerSettings = animal.playerSettings;
			if (((playerSettings != null) ? playerSettings.Master : null) != null && !animal.playerSettings.Master.Dead)
			{
				return true;
			}
			return false;
		}

