			if (quest == null || string.IsNullOrEmpty(quest.name))
			{
				return null;
			}
			string name = quest.name;
			if (name.Contains("Raid") || name.Contains("SSS-Rank") || name.Contains("SS-Rank") || name.Contains("S-Rank"))
			{
				return RaidIcon;
			}
			if (name.Contains("Expedition") || name.Contains("A-Rank") || name.Contains("B-Rank"))
			{
				return ExpeditionIcon;
			}
			if (name.Contains("Hunt") || name.Contains("F-Rank") || name.Contains("E-Rank") || name.Contains("D-Rank") || name.Contains("C-Rank"))
			{
				return HuntIcon;
			}
			return null;
		}

		public static bool IsIsekaiQuest(Quest quest)
		{
			if (quest == null)
			{
				return false;
			}
			foreach (QuestPart item in quest.PartsListForReading)
			{
				if (item is QuestPart_IsekaiLocalHunt || item is QuestPart_IsekaiWorldHunt || item is QuestPart_IsekaiXPReward)
				{
					return true;
				}
			}
			if (quest.name != null && quest.name.Contains("-Rank") && (quest.name.Contains("Hunt") || quest.name.Contains("Expedition") || quest.name.Contains("Raid")))
			{
				return true;
			}
			return false;
		}
	}
