	public class IsekaiStackData : IExposable
	{
		public int currentLevel = 1;

		public int currentXP = 0;

		public bool statsInitialized = false;

		public int strength = 5;

		public int dexterity = 5;

		public int vitality = 5;

		public int intelligence = 5;

		public int wisdom = 5;

		public int charisma = 5;

		public int availableStatPoints = 0;

		public string assignedTree;

		public int availablePoints = 0;

		public int respecCount = 0;

		public List<string> unlockedNodeIds = new List<string>();

		public List<IsekaiTitleDef> earnedTitles = new List<IsekaiTitleDef>();

		public IsekaiTitleDef activeTitle;

		public void CopyFrom(IsekaiComponent comp)
		{
			currentLevel = comp.currentLevel;
			currentXP = comp.currentXP;
			statsInitialized = comp.statsInitialized;
			if (comp.stats != null)
			{
				strength = comp.stats.strength;
				dexterity = comp.stats.dexterity;
				vitality = comp.stats.vitality;
				intelligence = comp.stats.intelligence;
				wisdom = comp.stats.wisdom;
				charisma = comp.stats.charisma;
				availableStatPoints = comp.stats.availableStatPoints;
			}
			if (comp.passiveTree != null)
			{
				assignedTree = comp.passiveTree.assignedTree;
				availablePoints = comp.passiveTree.availablePoints;
				respecCount = comp.passiveTree.respecCount;
				unlockedNodeIds = ((comp.passiveTree.unlockedNodeIds != null) ? new List<string>(comp.passiveTree.unlockedNodeIds) : new List<string>());
			}
			if (comp.titles != null)
			{
				earnedTitles = ((comp.titles.earnedTitles != null) ? new List<IsekaiTitleDef>(comp.titles.earnedTitles) : new List<IsekaiTitleDef>());
				activeTitle = comp.titles.activeTitle;
			}
		}

		public void ApplyTo(IsekaiComponent comp)
		{
			comp.currentLevel = currentLevel;
			comp.currentXP = currentXP;
			comp.statsInitialized = true;
			if (comp.stats != null)
			{
				comp.stats.strength = strength;
				comp.stats.dexterity = dexterity;
				comp.stats.vitality = vitality;
				comp.stats.intelligence = intelligence;
				comp.stats.wisdom = wisdom;
				comp.stats.charisma = charisma;
				comp.stats.availableStatPoints = availableStatPoints;
			}
			if (comp.passiveTree != null)
			{
				comp.passiveTree.assignedTree = assignedTree;
				comp.passiveTree.availablePoints = availablePoints;
				comp.passiveTree.respecCount = respecCount;
				comp.passiveTree.unlockedNodeIds = ((unlockedNodeIds != null) ? new List<string>(unlockedNodeIds) : new List<string>());
				comp.passiveTree.RebuildUnlockedSet();
			}
			if (comp.titles != null)
			{
				comp.titles.earnedTitles = ((earnedTitles != null) ? new List<IsekaiTitleDef>(earnedTitles) : new List<IsekaiTitleDef>());
				comp.titles.activeTitle = activeTitle;
			}
			PawnStatGenerator.UpdateRankTraitFromStats(comp.Pawn, comp);
			comp.InvalidateStatCache();
		}

		public IsekaiStackData Clone()
		{
			return new IsekaiStackData
			{
				currentLevel = currentLevel,
				currentXP = currentXP,
				statsInitialized = statsInitialized,
				strength = strength,
				dexterity = dexterity,
				vitality = vitality,
				intelligence = intelligence,
				wisdom = wisdom,
				charisma = charisma,
				availableStatPoints = availableStatPoints,
				assignedTree = assignedTree,
				availablePoints = availablePoints,
				respecCount = respecCount,
				unlockedNodeIds = ((unlockedNodeIds != null) ? new List<string>(unlockedNodeIds) : new List<string>()),
				earnedTitles = ((earnedTitles != null) ? new List<IsekaiTitleDef>(earnedTitles) : new List<IsekaiTitleDef>()),
				activeTitle = activeTitle
			};
		}

		public void ExposeData()
		{
			Scribe_Values.Look<int>(ref currentLevel, "currentLevel", 1, false);
			Scribe_Values.Look<int>(ref currentXP, "currentXP", 0, false);
			Scribe_Values.Look<bool>(ref statsInitialized, "statsInitialized", false, false);
			Scribe_Values.Look<int>(ref strength, "str", 5, false);
			Scribe_Values.Look<int>(ref dexterity, "dex", 5, false);
			Scribe_Values.Look<int>(ref vitality, "vit", 5, false);
			Scribe_Values.Look<int>(ref intelligence, "intl", 5, false);
			Scribe_Values.Look<int>(ref wisdom, "wis", 5, false);
			Scribe_Values.Look<int>(ref charisma, "cha", 5, false);
			Scribe_Values.Look<int>(ref availableStatPoints, "availableStatPoints", 0, false);
			Scribe_Values.Look<string>(ref assignedTree, "assignedTree", (string)null, false);
			Scribe_Values.Look<int>(ref availablePoints, "availablePoints", 0, false);
			Scribe_Values.Look<int>(ref respecCount, "respecCount", 0, false);
			Scribe_Collections.Look<string>(ref unlockedNodeIds, "unlockedNodeIds", (LookMode)1, Array.Empty<object>());
			Scribe_Collections.Look<IsekaiTitleDef>(ref earnedTitles, "earnedTitles", (LookMode)4, Array.Empty<object>());
			Scribe_Defs.Look<IsekaiTitleDef>(ref activeTitle, "activeTitle");
			if (unlockedNodeIds == null)
			{
				unlockedNodeIds = new List<string>();
			}
			if (earnedTitles == null)
			{
				earnedTitles = new List<IsekaiTitleDef>();
			}
			earnedTitles.RemoveAll((IsekaiTitleDef t) => t == null);
		}
	}
