	[HarmonyPatch(typeof(PawnGenerator), "GeneratePawn", new Type[] { typeof(PawnGenerationRequest) })]
	public static class Patch_AssignRankTraitAfterGeneration
	{
		[HarmonyPostfix]
		public static void Postfix(Pawn __result)
		{
			try
			{
				if (__result == null || __result.RaceProps == null || !__result.RaceProps.Humanlike || __result.story == null || __result.story.traits == null || __result.story.traits.allTraits == null)
				{
					return;
				}
				IsekaiComponent comp = ((ThingWithComps)__result).GetComp<IsekaiComponent>();
				if (comp == null || comp.stats == null)
				{
					return;
				}
				if (PawnStatGenerator.IsNewborn(__result) && !IsekaiLevelingSettings.NewbornsUseRankRolling)
				{
					PawnStatGenerator.ResetToNewborn(__result, comp);
					return;
				}
				if (!comp.statsInitialized || (comp.currentLevel <= 1 && comp.stats.TotalAllocatedPoints <= 0))
				{
					PawnStatGenerator.InitializePawnStats(__result, comp);
					comp.statsInitialized = true;
				}
				PawnRoleStats.ApplyRoleDistribution(__result, comp);
				if (PawnStatGenerator.TryRestoreCharacterCreationStats(__result, comp))
				{
					return;
				}
				string text = null;
				string[] array = new string[10] { "F", "E", "D", "C", "B", "A", "S", "SS", "SSS", "Nation" };
				foreach (Trait allTrait in __result.story.traits.allTraits)
				{
					if (((Def)(allTrait?.def?)).defName == null)
					{
						continue;
					}
					string[] array2 = array;
					foreach (string text2 in array2)
					{
						if (((Def)allTrait.def).defName == "Isekai_Rank_" + text2)
						{
							text = text2;
							break;
						}
					}
					if (text == null)
					{
						continue;
					}
					break;
				}
				if (text != null)
				{
					PawnStatGenerator.SyncToRankTrait(__result, comp, text);
				}
				else
				{
					PawnStatGenerator.UpdateRankTraitFromStats(__result, comp);
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] Error in rank trait assignment: " + ex.Message);
			}
		}
	}
