			{
				return;
			}
			string pawnRank = GetPawnRank(__result);
			if (pawnRank == null)
			{
				if (Prefs.DevMode)
				{
					Log.Message($"[Isekai Forge] Skipping {((Entity)__result).LabelCap}: no rank found (comp={((ThingWithComps)__result).GetComp<IsekaiComponent>() != null}, level={((ThingWithComps)__result).GetComp<IsekaiComponent>()?.currentLevel ?? (-1)})");
				}
				return;
			}
			if (!GetEnhancementParams(pawnRank, out var maxRef, out var runeChance, out var maxRuneRank, out var equipChance))
			{
				if (Prefs.DevMode)
				{
					Log.Message("[Isekai Forge] Skipping " + ((Entity)__result).LabelCap + ": rank " + pawnRank + " has no enhancement params (F/E rank)");
				}
				return;
			}
			if (!Rand.Chance(equipChance))
			{
				if (Prefs.DevMode)
				{
					Log.Message($"[Isekai Forge] Skipping {((Entity)__result).LabelCap}: failed equipChance roll ({equipChance:P0}) for rank {pawnRank}");
				}
				return;
			}
			if (Prefs.DevMode)
			{
				Log.Message($"[Isekai Forge] Enhancing {((Entity)__result).LabelCap} (rank {pawnRank}): maxRef={maxRef}, runeChance={runeChance:P0}, maxRuneRank={maxRuneRank}");
			}
			Pawn_EquipmentTracker equipment = __result.equipment;
			if (((equipment != null) ? equipment.Primary : null) != null)
			{
				ForgeItemGenerator.TryApplyRandomEnhancement((Thing)(object)__result.equipment.Primary, maxRef, runeChance, maxRuneRank);
			}
			Pawn_ApparelTracker apparel = __result.apparel;
			if (((apparel != null) ? apparel.WornApparel : null) == null)
			{
				return;
			}
			foreach (Apparel item in __result.apparel.WornApparel)
			{
				if (Rand.Chance(equipChance))
				{
					ForgeItemGenerator.TryApplyRandomEnhancement((Thing)(object)item, maxRef, runeChance, maxRuneRank);
				}
			}
		}

		private static string GetPawnRank(Pawn pawn)
		{
			IsekaiComponent comp = ((ThingWithComps)pawn).GetComp<IsekaiComponent>();
			if (comp != null && comp.currentLevel > 0)
			{
				return GetRankFromLevel(comp.currentLevel);
			}
			if (pawn.story?.traits?.allTraits != null)
			{
				string[] array = new string[10] { "Nation", "SSS", "SS", "S", "A", "B", "C", "D", "E", "F" };
				foreach (Trait allTrait in pawn.story.traits.allTraits)
				{
					if (((Def)(allTrait?.def?)).defName == null)
					{
						continue;
					}
					string[] array2 = array;
					foreach (string text in array2)
					{
						if (((Def)allTrait.def).defName == "Isekai_Rank_" + text)
						{
							return text;
						}
					}
				}
			}
			return null;
		}

		private static string GetRankFromLevel(int level)
		{
			return MobRankUtility.RankStringFromLevel(level);
		}

		private static bool GetEnhancementParams(string rank, out int maxRef, out float runeChance, out int maxRuneRank, out float equipChance)
		{
			switch (rank)
			{
			case "F":
				maxRef = 1;
				runeChance = 0.05f;
				maxRuneRank = 1;
				equipChance = 0.1f;
				return true;
			case "E":
				maxRef = 1;
				runeChance = 0.1f;
				maxRuneRank = 1;
				equipChance = 0.2f;
				return true;
			case "D":
