				runeChance = 0.35f;
				maxRuneRank = 1;
				equipChance = 0.55f;
				return true;
			case "B":
				maxRef = 4;
				runeChance = 0.5f;
				maxRuneRank = 2;
				equipChance = 0.7f;
				return true;
			case "A":
				maxRef = 6;
				runeChance = 0.65f;
				maxRuneRank = 3;
				equipChance = 0.85f;
				return true;
			case "S":
				maxRef = 8;
				runeChance = 0.75f;
				maxRuneRank = 3;
				equipChance = 0.95f;
				return true;
			case "SS":
				maxRef = 9;
				runeChance = 0.85f;
				maxRuneRank = 4;
				equipChance = 1f;
				return true;
			case "SSS":
