	public static class ResurrectionPreserver
	{
		private static readonly Dictionary<int, IsekaiStackData> deathCache = new Dictionary<int, IsekaiStackData>();

		private static readonly Dictionary<string, IsekaiStackData> nameCache = new Dictionary<string, IsekaiStackData>();

		private const int MAX_CACHE_SIZE = 200;

		public static void CacheOnDeath(Pawn pawn)
		{
			CacheSnapshot(pawn);
		}

		public static void CacheSnapshot(Pawn pawn)
		{
			if (pawn == null || pawn.RaceProps == null || !pawn.RaceProps.Humanlike)
			{
				return;
			}
			IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
			if (cached != null && cached.currentLevel > 1)
			{
				IsekaiStackData isekaiStackData = new IsekaiStackData();
				isekaiStackData.CopyFrom(cached);
				deathCache[((Thing)pawn).thingIDNumber] = isekaiStackData;
				string nameKey = GetNameKey(pawn);
				if (nameKey != null)
				{
					nameCache[nameKey] = isekaiStackData;
				}
				if (deathCache.Count > 200)
				{
					deathCache.Clear();
					nameCache.Clear();
				}
			}
		}

		public static bool TryRestore(Pawn pawn, IsekaiComponent comp)
		{
			if (pawn == null || comp == null)
			{
				return false;
			}
			if (deathCache.TryGetValue(((Thing)pawn).thingIDNumber, out var value))
			{
				if (comp.currentLevel < value.currentLevel)
				{
					value.ApplyTo(comp);
					deathCache.Remove(((Thing)pawn).thingIDNumber);
					string nameKey = GetNameKey(pawn);
					if (nameKey != null)
					{
						nameCache.Remove(nameKey);
					}
					Log.Message($"[Isekai Leveling] Restored level {value.currentLevel} for {((Entity)pawn).LabelShort} after resurrection (ID match).");
					return true;
				}
				CacheSnapshot(pawn);
				return false;
			}
			string nameKey2 = GetNameKey(pawn);
			if (nameKey2 != null && nameCache.TryGetValue(nameKey2, out var value2))
			{
				if (comp.currentLevel < value2.currentLevel)
				{
					value2.ApplyTo(comp);
					CacheSnapshot(pawn);
					Log.Message($"[Isekai Leveling] Restored level {value2.currentLevel} for {((Entity)pawn).LabelShort} after resurrection (name match).");
					return true;
				}
				CacheSnapshot(pawn);
			}
			return false;
		}

		public static void ClearAll()
		{
			deathCache.Clear();
			nameCache.Clear();
		}

		private static string GetNameKey(Pawn pawn)
		{
			object obj;
			if (pawn == null)
			{
				obj = null;
			}
			else
			{
				Name name = pawn.Name;
				obj = ((name != null) ? name.ToStringFull : null);
			}
			string text = (string)obj;
			return string.IsNullOrEmpty(text) ? null : text;
		}
	}
