	public static class DamageTracker
	{
		private static Dictionary<int, Dictionary<int, float>> damageRecords = new Dictionary<int, Dictionary<int, float>>();

		private static int lastCleanupTick = 0;

		private const int CLEANUP_INTERVAL = 2500;

		private const int RECORD_EXPIRY_TICKS = 15000;

		private static Dictionary<int, int> recordTimestamps = new Dictionary<int, int>();

		public static void RegisterDamage(Thing target, Pawn attacker, float damage)
		{
			if (target == null || attacker == null || damage <= 0f)
			{
				return;
			}
			int thingIDNumber = target.thingIDNumber;
			int thingIDNumber2 = ((Thing)attacker).thingIDNumber;
			if (IsekaiLevelingSettings.EnableMechanitorXP && MechanitorHelper.IsControlledMech(attacker))
			{
				Pawn mechanitor = MechanitorHelper.GetMechanitor(attacker);
				if (mechanitor != null)
				{
					RegisterDamageForPawn(thingIDNumber, ((Thing)mechanitor).thingIDNumber, damage);
				}
			}
			RegisterDamageForPawn(thingIDNumber, thingIDNumber2, damage);
			Dictionary<int, int> dictionary = recordTimestamps;
			TickManager tickManager = Find.TickManager;
			dictionary[thingIDNumber] = ((tickManager != null) ? tickManager.TicksGame : 0);
			TickManager tickManager2 = Find.TickManager;
			int num = ((tickManager2 != null) ? tickManager2.TicksGame : 0);
			if (num - lastCleanupTick > 2500)
			{
				CleanupOldRecords(num);
				lastCleanupTick = num;
