		public static void ClearRecords(Thing target)
		{
			if (target != null)
			{
				int thingIDNumber = target.thingIDNumber;
				damageRecords.Remove(thingIDNumber);
				recordTimestamps.Remove(thingIDNumber);
			}
		}

		private static void CleanupOldRecords(int currentTick)
		{
			List<int> list = new List<int>();
			foreach (KeyValuePair<int, int> recordTimestamp in recordTimestamps)
			{
				if (currentTick - recordTimestamp.Value > 15000)
				{
					list.Add(recordTimestamp.Key);
				}
			}
			foreach (int item in list)
			{
				damageRecords.Remove(item);
				recordTimestamps.Remove(item);
			}
		}

		public static void ClearAll()
		{
			damageRecords.Clear();
			recordTimestamps.Clear();
			lastCleanupTick = 0;
		}
	}
