				{
					num = (int)((float)num * 1.5f);
				}
				return num;
			}
			if (target.RaceProps.Humanlike)
			{
				IsekaiComponent cached = IsekaiComponent.GetCached(target);
				if (cached != null)
				{
					int level = cached.Level;
					return 50 + level * 10;
				}
				return 300;
			}
			if (target.RaceProps.IsMechanoid)
			{
				return 400;
			}
			if (target.RaceProps.predator)
			{
				return 200;
			}
			if (target.RaceProps.baseBodySize >= 2f)
