				return 250;
			}
			return 150;
		}

		private static int GetXPForRank(MobRankTier rank)
		{
			return rank switch
			{
				MobRankTier.SSS => 2000, 
				MobRankTier.SS => 1200, 
				MobRankTier.S => 800, 
				MobRankTier.A => 500, 
				MobRankTier.B => 300, 
				MobRankTier.C => 180, 
				MobRankTier.D => 100, 
				MobRankTier.E => 60, 
				MobRankTier.F => 30, 
				_ => 50, 
			};
		}

		private static float CalculateRankDifferenceBonus(IsekaiComponent attackerComp, Pawn target)
		{
			if (attackerComp == null || target == null)
			{
				return 1f;
			}
			int num = RankTierToInt(attackerComp.GetRank());
			int num2 = 0;
			MobRankComponent comp = ((ThingWithComps)target).GetComp<MobRankComponent>();
			if (comp != null && comp.IsInitialized)
			{
				num2 = RankTierToInt(comp.Rank);
			}
			else
			{
				IsekaiComponent cached = IsekaiComponent.GetCached(target);
				if (cached == null)
				{
					return 1f;
				}
				num2 = RankTierToInt(cached.GetRank());
			}
			int num3 = num2 - num;
			if (num3 > 0)
			{
				return Mathf.Min(3f, 1f + (float)num3 * 0.25f);
			}
			if (num3 < 0)
			{
				return Mathf.Max(0.5f, 1f + (float)num3 * 0.1f);
			}
			return 1f;
		}

		private static int RankTierToInt(MobRankTier tier)
		{
			return tier switch
			{
				MobRankTier.F => 0, 
				MobRankTier.E => 1, 
				MobRankTier.D => 2, 
				MobRankTier.C => 3, 
				MobRankTier.B => 4, 
				MobRankTier.A => 5, 
				MobRankTier.S => 6, 
				MobRankTier.SS => 7, 
				MobRankTier.SSS => 8, 
				_ => 0, 
			};
		}
	}
