namespace IsekaiLeveling.MobRanking
{
	public static class AuthoredCreatureRanks
	{
		private static readonly Dictionary<string, MobRankTier> ranks = new Dictionary<string, MobRankTier>();

		private static bool scanned;

		public static int Count
		{
			get
			{
				EnsureScanned();
				return ranks.Count;
			}
		}

		public static void Register(string raceDefName, MobRankTier tier)
		{
			if (!string.IsNullOrEmpty(raceDefName))
			{
				ranks[raceDefName] = tier;
			}
		}

		public static bool TryGet(string raceDefName, out MobRankTier tier)
		{
			tier = MobRankTier.F;
			if (string.IsNullOrEmpty(raceDefName))
			{
				return false;
			}
			EnsureScanned();
			return ranks.TryGetValue(raceDefName, out tier);
		}

		private static void EnsureScanned()
		{
			if (scanned)
			{
				return;
			}
			scanned = true;
			try
			{
				Type type = AccessTools.TypeByName("IsekaiCreatures.IsekaiCreatureRanks");
				if (type == null)
				{
					return;
				}
				FieldInfo field = type.GetField("ForcedRanks", BindingFlags.Static | BindingFlags.Public | BindingFlags.FlattenHierarchy);
				if (field == null || !(field.GetValue(null) is Dictionary<string, MobRankTier> dictionary))
				{
					return;
				}
				int num = 0;
				foreach (KeyValuePair<string, MobRankTier> item in dictionary)
				{
					if (!ranks.ContainsKey(item.Key))
					{
						ranks[item.Key] = item.Value;
						num++;
					}
				}
				if (Prefs.DevMode && num > 0)
				{
					Log.Message($"[Isekai Leveling] Picked up {num} authored creature ranks from IsekaiCreatures.");
				}
			}
			catch (Exception ex)
			{
				Log.WarningOnce("[Isekai Leveling] Could not read authored creature ranks; falling back to combat power for every creature. " + ex.Message, 22940178);
			}
		}
	}
	[StaticConstructorOnStartup]
	public static class MechScalingSystem
	{
		public static bool IsPlayerMech(Pawn pawn)
		{
			if (pawn == null)
			{
				return false;
			}
			if (!ModsConfig.BiotechActive)
			{
				return false;
			}
			if (!pawn.RaceProps.IsMechanoid)
			{
				return false;
			}
			if (((Thing)pawn).Faction == null || !((Thing)pawn).Faction.IsPlayer)
			{
				return false;
			}
			return MechanitorUtility.GetOverseer(pawn) != null;
		}

		public static IsekaiComponent GetMechanitorComp(Pawn mech)
		{
			if (mech == null)
			{
				return null;
			}
			if (!ModsConfig.BiotechActive)
			{
				return null;
			}
			Pawn overseer = MechanitorUtility.GetOverseer(mech);
			if (overseer == null)
			{
				return null;
			}
			return ((ThingWithComps)overseer).GetComp<IsekaiComponent>();
		}

		public static float GetMechHealthMultiplier(Pawn mech)
		{
			IsekaiComponent mechanitorComp = GetMechanitorComp(mech);
			if (mechanitorComp?.stats == null)
			{
				return 1f;
			}
			int currentLevel = mechanitorComp.currentLevel;
			int vitality = mechanitorComp.stats.vitality;
			float num = (float)currentLevel * 0.01f;
			float num2 = (float)Math.Max(0, vitality - 5) * 0.005f;
			return 1f + num + num2;
		}

		public static float GetMechDamageMultiplier(Pawn mech)
		{
			IsekaiComponent mechanitorComp = GetMechanitorComp(mech);
			if (mechanitorComp?.stats == null)
			{
				return 1f;
			}
			int currentLevel = mechanitorComp.currentLevel;
			int intelligence = mechanitorComp.stats.intelligence;
			float num = (float)currentLevel * 0.005f;
			float num2 = (float)Math.Max(0, intelligence - 5) * 0.003f;
			return 1f + num + num2;
		}

		public static float GetMechArmorOffset(Pawn mech)
		{
			IsekaiComponent mechanitorComp = GetMechanitorComp(mech);
			if (mechanitorComp?.stats == null)
			{
				return 0f;
			}
			int currentLevel = mechanitorComp.currentLevel;
			int intelligence = mechanitorComp.stats.intelligence;
			float num = (float)currentLevel * 0.003f;
			float num2 = (float)Math.Max(0, intelligence - 5) * 0.002f;
			return num + num2;
		}

		public static float GetMechSpeedMultiplier(Pawn mech)
		{
			IsekaiComponent mechanitorComp = GetMechanitorComp(mech);
			if (mechanitorComp?.stats == null)
			{
				return 1f;
			}
			int dexterity = mechanitorComp.stats.dexterity;
			float num = (float)Math.Max(0, dexterity - 5) * 0.005f;
			return 1f + num;
		}

		public static float GetMechShootingOffset(Pawn mech)
		{
			IsekaiComponent mechanitorComp = GetMechanitorComp(mech);
			if (mechanitorComp?.stats == null)
			{
				return 0f;
			}
			int dexterity = mechanitorComp.stats.dexterity;
			return (float)Math.Max(0, dexterity - 5) * IsekaiLevelingSettings.DEX_ShootingAccuracy;
		}
	}
	[HarmonyPatch(typeof(StatWorker), "GetValueUnfinalized")]
	[HarmonyAfter(new string[] { "JellyCreative.IsekaiLeveling" })]
	public static class MechStatScaling_Patch
	{
		[HarmonyPostfix]
		public static void Postfix(ref float __result, StatRequest req, StatDef ___stat)
		{
			try
			{
				if (!((StatRequest)(ref req)).HasThing || !IsekaiLevelingSettings.EnableMechanitorXP)
				{
					return;
				}
				Thing thing = ((StatRequest)(ref req)).Thing;
				Pawn val = (Pawn)(object)((thing is Pawn) ? thing : null);
				if (val != null && MechScalingSystem.IsPlayerMech(val))
				{
					if (___stat == StatDefOf.MeleeDamageFactor || ___stat == StatDefOf.MeleeHitChance)
					{
						float mechDamageMultiplier = MechScalingSystem.GetMechDamageMultiplier(val);
						__result *= mechDamageMultiplier;
					}
					else if (___stat == StatDefOf.MoveSpeed)
					{
						float mechSpeedMultiplier = MechScalingSystem.GetMechSpeedMultiplier(val);
						__result *= mechSpeedMultiplier;
					}
					else if (___stat == StatDefOf.ShootingAccuracyPawn)
					{
						__result += MechScalingSystem.GetMechShootingOffset(val);
					}
					else if (___stat == StatDefOf.ArmorRating_Sharp || ___stat == StatDefOf.ArmorRating_Blunt || ___stat == StatDefOf.ArmorRating_Heat)
					{
						float mechArmorOffset = MechScalingSystem.GetMechArmorOffset(val);
						__result += mechArmorOffset;
					}
				}
			}
			catch
			{
			}
		}
	}
	[HarmonyPatch(typeof(BodyPartDef), "GetMaxHealth")]
	[HarmonyAfter(new string[] { "JellyCreative.IsekaiLeveling" })]
	public static class MechHealthScaling_Patch
	{
		[HarmonyPostfix]
		public static void Postfix(ref float __result, Pawn pawn)
		{
			try
			{
				if (pawn != null && IsekaiLevelingSettings.EnableMechanitorXP && MechScalingSystem.IsPlayerMech(pawn))
				{
					float mechHealthMultiplier = MechScalingSystem.GetMechHealthMultiplier(pawn);
					__result *= mechHealthMultiplier;
					__result = Mathf.Max(1f, Mathf.Round(__result));
				}
			}
			catch
			{
			}
		}
	}
