		public static MobRankTier TierFromLevel(int level)
		{
			(int, MobRankTier)[] levelLadder = LevelLadder;
			for (int i = 0; i < levelLadder.Length; i++)
			{
				var (num, result) = levelLadder[i];
				if (level >= num)
				{
					return result;
				}
			}
			return MobRankTier.F;
		}

