		{
			(int, MobRankTier)[] levelLadder = LevelLadder;
			for (int i = 0; i < levelLadder.Length; i++)
			{
				var (result, mobRankTier) = levelLadder[i];
				if (mobRankTier == tier)
				{
					return result;
				}
			}
			return 1;
		}

