		public static MobRankTier CalculateBaseRankFromThreatScore(float threatScore)
		{
			if (threatScore >= 1500f)
			{
				return MobRankTier.S;
			}
			if (threatScore >= 800f)
			{
				return MobRankTier.A;
			}
			if (threatScore >= 400f)
			{
				return MobRankTier.B;
			}
			if (threatScore >= 200f)
			{
				return MobRankTier.C;
			}
			if (threatScore >= 100f)
			{
				return MobRankTier.D;
			}
			if (threatScore >= 40f)
			{
				return MobRankTier.E;
			}
			if (threatScore >= 15f)
			{
				return MobRankTier.F;
			}
			return MobRankTier.F;
		}

		public static MobRankTier ApplyRandomVariation(MobRankTier baseRank, int seed, float threatScore)
		{
			Random random = new Random(seed);
			float num = (float)random.NextDouble();
			int maxUpgrade = GetMaxUpgrade(threatScore);
			int num2 = 0;
			if (num > 0.95f && maxUpgrade >= 3)
			{
				num2 = 3;
			}
			else if (num > 0.85f && maxUpgrade >= 2)
			{
				num2 = 2;
			}
			else if (num > 0.6f && maxUpgrade >= 1)
			{
				num2 = 1;
			}
			return (MobRankTier)Mathf.Min((int)(baseRank + num2), 8);
		}

		private static int GetMaxUpgrade(float threatScore)
		{
			if (threatScore >= 1500f)
			{
				return 2;
			}
			if (threatScore >= 800f)
			{
				return 2;
			}
			if (threatScore >= 400f)
			{
				return 2;
			}
			if (threatScore >= 200f)
			{
				return 2;
			}
			if (threatScore >= 100f)
			{
				return 2;
			}
			if (threatScore >= 40f)
			{
				return 2;
			}
			if (threatScore >= 15f)
			{
				return 2;
			}
			return 1;
		}

