		public static string GenerateEliteName(Pawn pawn, MobRankTier rank)
		{
			//IL_0024: Unknown result type (might be due to invalid IL or missing references)
			//IL_0029: Unknown result type (might be due to invalid IL or missing references)
			//IL_0049: Unknown result type (might be due to invalid IL or missing references)
			//IL_004e: Unknown result type (might be due to invalid IL or missing references)
			if (pawn == null)
			{
				return "Unknown";
			}
			PawnKindDef kindDef = pawn.kindDef;
			object obj;
			TaggedString labelCap;
			if (kindDef == null)
			{
				obj = null;
			}
			else
			{
				labelCap = ((Def)kindDef).LabelCap;
				obj = ((object)(TaggedString)(ref labelCap)/*cast due to .constrained prefix*/).ToString();
			}
			if (obj == null)
			{
				ThingDef def = ((Thing)pawn).def;
				if (def == null)
				{
					obj = null;
				}
				else
				{
					labelCap = ((Def)def).LabelCap;
					obj = ((object)(TaggedString)(ref labelCap)/*cast due to .constrained prefix*/).ToString();
				}
				if (obj == null)
				{
					obj = "Beast";
				}
			}
			string text = (string)obj;
			Random random = new Random(((Thing)pawn).thingIDNumber + 31337);
			string[] eliteAdjectivesForRank = GetEliteAdjectivesForRank(rank);
			string text2 = eliteAdjectivesForRank[random.Next(eliteAdjectivesForRank.Length)];
			return text2 + " the " + text;
		}

		private static string[] GetEliteAdjectivesForRank(MobRankTier tier)
		{
			switch (tier)
			{
			case MobRankTier.SSS:
			case MobRankTier.Nation:
				return new string[5] { "Worldrender", "Skyeater", "Doomspeaker", "Voidmaw", "Ashking" };
			case MobRankTier.SS:
				return new string[4] { "Bonecrusher", "Stormfang", "Direhorn", "Nightreaver" };
			case MobRankTier.S:
				return new string[4] { "Ironhide", "Bloodmane", "Frostclaw", "Shadowstalker" };
			case MobRankTier.A:
				return new string[4] { "Grimjaw", "Sharpfang", "Wildhowl", "Brokentusk" };
			case MobRankTier.B:
				return new string[4] { "Scarred", "Cunning", "Restless", "Old" };
			case MobRankTier.C:
				return new string[4] { "Mean", "Stubborn", "Wary", "Limping" };
			default:
				return new string[3] { "Strange", "Quiet", "Lone" };
			}
		}

