	public static class MobRankCalculator
	{
		private static readonly (float power, MobRankTier tier)[] RankBands = new(float, MobRankTier)[8]
		{
			(600f, MobRankTier.SSS),
			(300f, MobRankTier.SS),
			(220f, MobRankTier.S),
			(150f, MobRankTier.A),
			(110f, MobRankTier.B),
			(80f, MobRankTier.C),
			(55f, MobRankTier.D),
			(35f, MobRankTier.E)
		};

		public static MobRankTier RankFor(Pawn pawn)
		{
			return TierForPower(PowerOf(pawn));
		}

		public static float PowerOf(Pawn pawn)
		{
			float num = pawn?.kindDef?.combatPower ?? (-1f);
			if (num >= 0f)
			{
				return num;
			}
			return CalculateThreatScore(pawn) / 2.5f;
		}

		public static MobRankTier RankForKind(PawnKindDef kind)
		{
			if (kind == null)
			{
				return MobRankTier.F;
			}
			if (kind.race != null && AuthoredCreatureRanks.TryGet(((Def)kind.race).defName, out var tier))
			{
				return tier;
			}
			return TierForPower((kind.combatPower >= 0f) ? kind.combatPower : 0f);
		}

		public static MobRankTier TierForPower(float combatPower)
		{
			for (int i = 0; i < RankBands.Length; i++)
			{
				if (combatPower >= RankBands[i].power)
				{
					return RankBands[i].tier;
				}
			}
			return MobRankTier.F;
		}

		public static float CalculateThreatScore(Pawn pawn)
		{
			if (((pawn != null) ? pawn.RaceProps : null) == null)
			{
				return 0f;
			}
			float num = 0f;
			num += CalculateHealthScore(pawn);
			num += CalculateCombatScore(pawn);
			num += CalculateMobilityScore(pawn);
			num += CalculateSpecialScore(pawn);
			num += CalculateAnomalyBonus(pawn);
			float num2 = pawn.kindDef?.combatPower ?? 0f;
			if (num2 > 0f)
			{
				float num3 = num2 * 2.5f;
				num = Mathf.Max(num, num3);
			}
			float baseStatValue = GetBaseStatValue(((Thing)pawn).def, StatDefOf.MarketValue);
			if (baseStatValue > 500f)
			{
				float num4 = baseStatValue * 0.3f;
				num = Mathf.Max(num, num4);
			}
			return Mathf.Max(1f, num);
		}

		private static float GetBaseStatValue(ThingDef def, StatDef stat)
		{
			if (((BuildableDef)(def?)).statBases == null)
			{
				return 0f;
			}
			foreach (StatModifier statBasis in ((BuildableDef)def).statBases)
			{
				if (statBasis.stat == stat)
				{
					return statBasis.value;
				}
			}
			return 0f;
		}

		private static float CalculateHealthScore(Pawn pawn)
		{
			float baseHealthScale = pawn.RaceProps.baseHealthScale;
			float baseBodySize = pawn.RaceProps.baseBodySize;
			return baseHealthScale * baseBodySize * 15f;
		}

		private static float CalculateCombatScore(Pawn pawn)
		{
			float num = 0f;
			float num2 = 0f;
			num2 = ((!pawn.RaceProps.Humanlike) ? CalculateMeleeDPS(pawn) : (pawn.RaceProps.baseBodySize * 3f));
			num += num2 * 3f;
			float num3 = 0f;
			float num4 = 0f;
			if (((BuildableDef)((Thing)pawn).def).statBases != null)
			{
				foreach (StatModifier statBasis in ((BuildableDef)((Thing)pawn).def).statBases)
				{
					if (statBasis.stat == StatDefOf.ArmorRating_Blunt)
					{
						num3 = statBasis.value;
					}
					else if (statBasis.stat == StatDefOf.ArmorRating_Sharp)
					{
						num4 = statBasis.value;
					}
				}
			}
			num += (num3 + num4) * 20f;
			if (pawn.RaceProps.predator)
			{
				num *= 1.5f;
			}
			if (pawn.RaceProps.packAnimal)
			{
				num *= 0.7f;
			}
			return num;
		}

		private static float CalculateMeleeDPS(Pawn pawn)
		{
			float num = 0f;
			try
			{
				VerbTracker verbTracker = pawn.VerbTracker;
				List<Verb> list = ((verbTracker != null) ? verbTracker.AllVerbs : null);
				if (list != null)
				{
					foreach (Verb item in list)
					{
						if (item.IsMeleeAttack && item.verbProps != null)
						{
							float num2 = item.verbProps.AdjustedMeleeDamageAmount(item, pawn);
							float num3 = item.verbProps.AdjustedCooldown(item, pawn);
							if (num3 > 0f)
							{
								num += num2 / num3;
							}
						}
					}
				}
			}
			catch
			{
			}
			if (num <= 0f)
			{
				num = CalculateToolDPS(((Thing)pawn).def);
			}
			return Mathf.Max(num, pawn.RaceProps.baseBodySize * 1.5f);
		}

		private static float CalculateToolDPS(ThingDef def)
		{
			if (def?.tools == null || def.tools.Count == 0)
			{
				return 0f;
			}
			float num = 0f;
			foreach (Tool tool in def.tools)
			{
				float power = tool.power;
				float num2 = ((tool.cooldownTime > 0f) ? tool.cooldownTime : 2f);
				num += power / num2;
			}
			return num;
		}

		private static float CalculateMobilityScore(Pawn pawn)
		{
			float num = 0f;
			float num2 = 4.6f;
			if (((BuildableDef)((Thing)pawn).def).statBases != null)
			{
				foreach (StatModifier statBasis in ((BuildableDef)((Thing)pawn).def).statBases)
				{
					if (statBasis.stat == StatDefOf.MoveSpeed)
					{
						num2 = statBasis.value;
						break;
					}
				}
			}
			else
			{
				num2 = ((pawn.RaceProps.baseBodySize > 1f) ? 3f : 4f);
			}
			num += num2 * 2f;
			float baseBodySize = pawn.RaceProps.baseBodySize;
			if (baseBodySize >= 4f)
			{
				return num + 150f;
			}
			if (baseBodySize >= 3f)
			{
				return num + 80f;
			}
			if (baseBodySize >= 2f)
			{
				return num + 40f;
			}
			if (baseBodySize >= 1.5f)
			{
				return num + 20f;
			}
			if (baseBodySize >= 1f)
			{
				return num + 10f;
			}
			if (baseBodySize >= 0.5f)
			{
				return num + 3f;
			}
			return num + 1f;
		}

		private static float CalculateSpecialScore(Pawn pawn)
		{
			float num = 0f;
			if (pawn.RaceProps.manhunterOnTameFailChance > 0f)
			{
				num += pawn.RaceProps.manhunterOnTameFailChance * 50f;
			}
			if (pawn.RaceProps.manhunterOnDamageChance > 0f)
			{
				num += pawn.RaceProps.manhunterOnDamageChance * 30f;
			}
			if (pawn.RaceProps.Insect)
			{
				num += 30f;
			}
			TrainabilityDef trainability = pawn.RaceProps.trainability;
			bool? obj;
			if (trainability == null)
			{
				obj = null;
			}
			else
			{
				string defName = ((Def)trainability).defName;
				obj = ((defName != null) ? new bool?(!defName.Contains("Advanced")) : ((bool?)null));
			}
			if (obj ?? true)
			{
				num += 15f;
			}
			float num2 = pawn.kindDef?.combatPower ?? 0f;
			return num + num2 * 0.5f;
		}

		private static float CalculateAnomalyBonus(Pawn pawn)
		{
			float num = 0f;
			try
			{
				string text = ((Def)((Thing)pawn).def).defName.ToLower();
				if (text.Contains("sightsteal") || text.Contains("revenant"))
				{
					num += 800f;
				}
				else if (text.Contains("shambler") || text.Contains("gorehulk"))
				{
					num += 400f;
				}
				else if (text.Contains("fleshmass") || text.Contains("chimera"))
				{
					num += 300f;
				}
				else if (text.Contains("entity") || text.Contains("horror"))
				{
					num += 200f;
				}
				else if (text.Contains("void") || text.Contains("dark"))
				{
					num += 150f;
				}
				ModContentPack modContentPack = ((Def)((Thing)pawn).def).modContentPack;
				if (modContentPack != null && modContentPack.Name?.Contains("Anomaly") == true)
				{
					num += 100f;
				}
			}
			catch
			{
			}
			return num;
		}

		public static float EstimateThreatScoreFromDef(ThingDef def)
		{
			if (def?.race == null)
			{
				return 0f;
			}
			float num = 0f;
			RaceProperties race = def.race;
			num += race.baseHealthScale * 100f * race.baseBodySize * 0.5f;
			num = ((race.baseBodySize >= 3f) ? (num + 200f) : ((race.baseBodySize >= 2f) ? (num + 100f) : ((!(race.baseBodySize >= 1f)) ? (num + 10f) : (num + 40f))));
			if (race.predator)
			{
				num *= 1.4f;
			}
			if (race.Insect)
			{
				num += 30f;
			}
			num += race.manhunterOnDamageChance * 40f;
			num += race.manhunterOnTameFailChance * 60f;
			float num2 = CalculateToolDPS(def);
			num += num2 * 3f;
			float num3 = 0f;
			try
			{
				foreach (PawnKindDef item in DefDatabase<PawnKindDef>.AllDefsListForReading)
				{
					if (item.race == def && item.combatPower > num3)
					{
						num3 = item.combatPower;
					}
				}
			}
			catch
			{
			}
			if (num3 > 0f)
			{
				num = Mathf.Max(num, num3 * 2.5f);
			}
			float baseStatValue = GetBaseStatValue(def, StatDefOf.MarketValue);
			if (baseStatValue > 500f)
			{
				num = Mathf.Max(num, baseStatValue * 0.3f);
			}
			return Mathf.Max(1f, num);
		}
	}
	public class MobRankComponent : ThingComp
	{
		private MobRankTier cachedRank = MobRankTier.F;

		private MobRankTier cachedBaseRank = MobRankTier.F;

		private bool cachedIsElite = false;

		private bool isInitialized = false;

		private int rankSystemVersion = 0;

		private const int CurrentRankSystemVersion = 1;

		public int currentLevel = 1;

		public int currentXP = 0;

		public IsekaiStatAllocation stats = new IsekaiStatAllocation();

		public bool statsInitialized = false;

		private int lastNotifiedLevel = 0;

		private int lastLoggedLevel = 0;

		private bool hasRankOverride = false;

		private MobRankTier overriddenRank = MobRankTier.F;

		private bool overriddenElite = false;

		public bool IsInitialized => isInitialized;

		public MobRankTier Rank
		{
			get
			{
				EnsureInitialized();
				return cachedRank;
			}
		}

		public MobRankTier BaseRank
		{
			get
			{
				EnsureInitialized();
				return cachedBaseRank;
			}
		}

		public bool IsElite
		{
			get
			{
				EnsureInitialized();
				return cachedIsElite;
			}
		}

		public int RankBonus => Rank - BaseRank;

		public string RankString => MobRankUtility.GetRankString(Rank);

		public Color RankColor => MobRankUtility.GetRankColor(Rank);

		public string RankTitle => MobRankUtility.GetRankTitle(Rank);

		public Pawn Pawn
		{
			get
			{
				ThingWithComps parent = base.parent;
				return (Pawn)(object)((parent is Pawn) ? parent : null);
			}
		}

		public int XPToNextLevel => Mathf.Max(100, Mathf.RoundToInt(100f * Mathf.Pow((float)currentLevel, 1.5f)));

		public float LevelProgress => (float)currentXP / (float)Mathf.Max(1, XPToNextLevel);

		private void EnsureInitialized()
		{
			if (!isInitialized)
			{
				RecalculateRank();
			}
		}

		public void RecalculateRank()
		{
			if (Pawn == null)
			{
				return;
			}
			if (!hasRankOverride && MobRankInjector.IsExcludedFromRanking(Pawn))
			{
				isInitialized = true;
				return;
			}
			MobRankStatPatches.SetCalculatingRank(value: true);
			try
			{
				if (hasRankOverride)
				{
					cachedRank = overriddenRank;
					cachedBaseRank = overriddenRank;
					cachedIsElite = overriddenElite;
					EnsureStatsInitialized();
				}
				else if (!statsInitialized)
				{
					cachedRank = MobRankCalculator.RankFor(Pawn);
					cachedBaseRank = cachedRank;
					cachedIsElite = false;
					float eliteChance = GetEliteChance(cachedRank);
					if (eliteChance > 0f && Rand.Chance(eliteChance))
					{
						cachedIsElite = true;
						EnsureEliteName();
					}
					EnsureStatsInitialized(MobRankUtility.GetRankString(cachedRank));
				}
				isInitialized = true;
			}
			finally
			{
				MobRankStatPatches.SetCalculatingRank(value: false);
			}
		}

		private static float GetEliteChance(MobRankTier rank)
		{
			return rank switch
			{
				MobRankTier.C => 0.05f, 
				MobRankTier.B => 0.06f, 
				MobRankTier.A => 0.07f, 
				MobRankTier.S => 0.05f, 
				MobRankTier.SS => 0.04f, 
				MobRankTier.SSS => 0.03f, 
				MobRankTier.Nation => 0.03f, 
				_ => 0f, 
			};
		}

		private void EnsureStatsInitialized(string rankStringOverride = null)
		{
			if (statsInitialized)
