	[StaticConstructorOnStartup]
	public static class PlayerCreatureScaling
	{
		public static float Retention => Mathf.Clamp(IsekaiLevelingSettings.TamedAnimalBonusRetention, 0f, 1f);

		public static bool IsPlayerScalableCreature(Pawn pawn)
		{
			if (pawn == null || pawn.Dead)
			{
				return false;
			}
			if (((Thing)pawn).Faction == null || !((Thing)pawn).Faction.IsPlayer)
			{
				return false;
			}
			if (pawn.RaceProps == null)
			{
				return false;
			}
			if (pawn.RaceProps.Humanlike)
			{
				return false;
			}
			if (pawn.RaceProps.IsMechanoid)
			{
				return false;
			}
			if (MobRankInjector.IsExcludedFromRanking(pawn))
			{
				return false;
			}
			return true;
		}

		public static MobRankComponent GetComp(Pawn pawn)
		{
			MobRankComponent comp = ((ThingWithComps)pawn).GetComp<MobRankComponent>();
			if (comp == null || !comp.IsInitialized || comp.stats == null)
			{
				return null;
			}
			return comp;
		}

		private static float ScaledMult(float statValue, float perPoint)
		{
			float num = 1f + Mathf.Max(0f, statValue) * perPoint;
			return 1f + (num - 1f) * Retention;
		}

		private static float ScaledOffset(float statValue, float perPoint)
		{
			return Mathf.Max(0f, statValue) * perPoint * Retention;
		}

		public static float ScaledMultPublic(float statValue, float perPoint)
		{
			return ScaledMult(statValue, perPoint);
		}

		public static float GetRangedDamageMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.dexterity, IsekaiLevelingSettings.DEX_RangedDamage);
		}

		public static float GetMeleeDamageMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.strength, IsekaiLevelingSettings.STR_MeleeDamage);
		}

		public static float GetCarryCapacityMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.strength, IsekaiLevelingSettings.STR_CarryCapacity);
		}

		public static float GetMoveSpeedMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.dexterity, IsekaiLevelingSettings.DEX_MoveSpeed);
		}

		public static float GetMeleeDodgeOffset(MobRankComponent c)
		{
			return ScaledOffset(c.stats.dexterity, IsekaiLevelingSettings.DEX_MeleeDodge);
		}

		public static float GetMeleeHitOffset(MobRankComponent c)
		{
			return ScaledOffset(c.stats.dexterity, IsekaiLevelingSettings.DEX_MeleeHitChance);
		}

		public static float GetHealthRegenMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.vitality, IsekaiLevelingSettings.VIT_HealthRegen);
		}

		public static float GetImmunityGainMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.vitality, IsekaiLevelingSettings.VIT_ImmunityGain);
		}

		public static float GetRestRateMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.vitality, IsekaiLevelingSettings.VIT_RestRate);
		}

		public static float GetSharpArmorOffset(MobRankComponent c)
		{
			return ScaledOffset(c.stats.vitality, 0.008f);
		}

		public static float GetBluntArmorOffset(MobRankComponent c)
		{
			return ScaledOffset(c.stats.vitality, 0.01f);
		}

		public static float GetHeatArmorOffset(MobRankComponent c)
		{
			return ScaledOffset(c.stats.vitality, 0.007f);
		}

		public static float GetToxicResistOffset(MobRankComponent c)
		{
			return ScaledOffset(c.stats.vitality, IsekaiLevelingSettings.VIT_ToxicResist);
		}

		public static float GetHealthMult(MobRankComponent c)
		{
			return ScaledMult(c.stats.vitality, IsekaiLevelingSettings.VIT_MaxHealth);
		}
	}
