				{
					if (___stat == StatDefOf.MeleeDamageFactor)
					{
						__result *= PlayerCreatureScaling.GetMeleeDamageMult(comp);
					}
					else if (___stat == StatDefOf.MeleeHitChance)
					{
						__result += PlayerCreatureScaling.GetMeleeHitOffset(comp);
					}
					else if (___stat == StatDefOf.MeleeDodgeChance)
					{
						__result += PlayerCreatureScaling.GetMeleeDodgeOffset(comp);
					}
					else if (___stat == StatDefOf.MoveSpeed)
					{
						__result *= PlayerCreatureScaling.GetMoveSpeedMult(comp);
					}
					else if (___stat == StatDefOf.CarryingCapacity)
					{
						__result *= PlayerCreatureScaling.GetCarryCapacityMult(comp);
					}
					else if (___stat == StatDefOf.ArmorRating_Sharp)
					{
						__result += PlayerCreatureScaling.GetSharpArmorOffset(comp);
					}
					else if (___stat == StatDefOf.ArmorRating_Blunt)
					{
						__result += PlayerCreatureScaling.GetBluntArmorOffset(comp);
					}
					else if (___stat == StatDefOf.ArmorRating_Heat)
					{
						__result += PlayerCreatureScaling.GetHeatArmorOffset(comp);
					}
					else if (___stat == StatDefOf.ToxicResistance)
					{
						__result += PlayerCreatureScaling.GetToxicResistOffset(comp);
					}
					else if (___stat == StatDefOf.ImmunityGainSpeed)
					{
						__result *= PlayerCreatureScaling.GetImmunityGainMult(comp);
					}
					else if (___stat == StatDefOf.InjuryHealingFactor)
					{
						__result *= PlayerCreatureScaling.GetHealthRegenMult(comp);
					}
					else if (___stat == StatDefOf.RestRateMultiplier)
					{
						__result *= PlayerCreatureScaling.GetRestRateMult(comp);
					}
				}
			}
			catch
			{
			}
		}
	}
