	public static class RaidRankPatches
	{
		public static float lastRaidPoints = 0f;

		public static Map lastRaidMap = null;

		private static HashSet<int> processedLords = new HashSet<int>();

		public static bool IsRaidLordJob(LordJob lordJob)
		{
			if (lordJob == null)
			{
				return false;
			}
			string name = ((object)lordJob).GetType().Name;
			bool flag = name.Contains("AssaultColony") || name.Contains("Raid") || name.Contains("Siege") || name.Contains("Sapper") || name.Contains("Assault") || name.Contains("Kidnap") || name.Contains("Steal") || name.Contains("Besiege");
			bool flag2 = name.Contains("DefendPoint") || name.Contains("AssistColony") || name.Contains("Defend") || name.Contains("MilitaryAid") || name.Contains("Reinforce");
			return flag || flag2;
		}

		public static bool IsAlliedLordJob(LordJob lordJob)
		{
			if (lordJob == null)
			{
				return false;
			}
			string name = ((object)lordJob).GetType().Name;
			return name.Contains("DefendPoint") || name.Contains("AssistColony") || name.Contains("Defend") || name.Contains("MilitaryAid") || name.Contains("Reinforce");
		}

		public static float EstimateRaidPoints(List<Pawn> pawns)
		{
			float num = 0f;
			foreach (Pawn pawn in pawns)
			{
				num += pawn.kindDef?.combatPower ?? 50f;
			}
			float num2 = num * 0.6f;
			if (Prefs.DevMode && Prefs.DevMode)
			{
				Log.Message($"[Isekai Raid] Using ESTIMATED points (fallback): {num2:F0} from {pawns.Count} pawns");
			}
			return num2;
		}

		public static bool WasLordProcessed(Lord lord)
		{
			if (lord == null)
			{
				return true;
			}
			return processedLords.Contains(((object)lord).GetHashCode());
		}

		public static void MarkLordProcessed(Lord lord)
		{
			if (lord != null)
			{
				processedLords.Add(((object)lord).GetHashCode());
				if (processedLords.Count > 100)
				{
					processedLords.Clear();
				}
			}
		}

		public static void ClearAll()
		{
			processedLords.Clear();
			lastRaidPoints = 0f;
			lastRaidMap = null;
		}
	}
	[HarmonyPatch]
	public static class Patch_IncidentWorker_TryExecute
	{
		private static bool Prepare()
		{
			MethodInfo methodInfo = AccessTools.Method(typeof(IncidentWorker), "TryExecute", (Type[])null, (Type[])null);
			if (methodInfo == null)
			{
				Log.Warning("[Isekai] IncidentWorker.TryExecute not found - raid point tracking patch skipped");
				return false;
			}
			return true;
		}

		private static MethodBase TargetMethod()
		{
			return AccessTools.Method(typeof(IncidentWorker), "TryExecute", (Type[])null, (Type[])null);
		}

		[HarmonyPrefix]
		public static void Prefix(IncidentWorker __instance, IncidentParms parms)
		{
			if (__instance == null || parms == null)
			{
				return;
			}
			bool flag = __instance is IncidentWorker_Raid;
			string name = ((object)__instance).GetType().Name;
			bool flag2 = name.Contains("RaidFriendly") || name.Contains("MilitaryAid") || name.Contains("AllyAid") || name.Contains("Reinforcement");
			if (!flag && !flag2)
			{
				return;
			}
			if (parms.points <= 0f)
			{
				RaidRankPatches.lastRaidPoints = 0f;
				RaidRankPatches.lastRaidMap = null;
				return;
			}
			RaidRankPatches.lastRaidPoints = parms.points;
			IIncidentTarget target = parms.target;
			RaidRankPatches.lastRaidMap = (Map)(object)((target is Map) ? target : null);
			if (Prefs.DevMode)
			{
				string arg = (flag ? "Hostile" : "Allied");
				string[] obj = new string[5]
				{
					$"[Isekai Raid] {arg} group incoming! Points: {parms.points:F0}, ",
					"Faction: ",
					null,
					null,
					null
				};
				Faction faction = parms.faction;
				obj[2] = ((faction != null) ? faction.Name : null) ?? "Unknown";
				obj[3] = ", Type: ";
				obj[4] = ((Def)(parms.raidStrategy?)).defName ?? name;
				Log.Message(string.Concat(obj));
			}
		}
	}
	[HarmonyPatch]
	public static class Patch_LordMaker_MakeNewLord
	{
		private static bool Prepare()
		{
			MethodInfo methodInfo = AccessTools.Method(typeof(LordMaker), "MakeNewLord", (Type[])null, (Type[])null);
			if (methodInfo == null)
			{
				Log.Warning("[Isekai] LordMaker.MakeNewLord not found - raid rank patch skipped");
				return false;
			}
			return true;
		}

		private static MethodBase TargetMethod()
		{
			return AccessTools.Method(typeof(LordMaker), "MakeNewLord", (Type[])null, (Type[])null);
		}

		[HarmonyPostfix]
		public static void Postfix(Lord __result, Faction faction, LordJob lordJob, Map map, IEnumerable<Pawn> startingPawns)
		{
			try
			{
				if (__result == null || faction == null || map == null)
				{
					return;
				}
				bool flag = FactionUtility.HostileTo(faction, Faction.OfPlayer);
				bool flag2 = !flag && (FactionUtility.AllyOrNeutralTo(faction, Faction.OfPlayer) || faction == Faction.OfPlayer);
				bool flag3 = false;
				if (flag)
				{
					flag3 = RaidRankPatches.IsRaidLordJob(lordJob);
				}
				else if (flag2)
				{
					flag3 = RaidRankPatches.IsAlliedLordJob(lordJob) || RaidRankPatches.IsRaidLordJob(lordJob);
				}
				if (!flag3 || RaidRankPatches.WasLordProcessed(__result))
				{
					return;
				}
				RaidRankPatches.MarkLordProcessed(__result);
				List<Pawn> list = null;
				if (__result.ownedPawns != null && __result.ownedPawns.Count > 0)
				{
					list = __result.ownedPawns.Where((Pawn p) => p != null && !p.Dead && p.RaceProps.Humanlike).ToList();
				}
				if ((list == null || list.Count == 0) && startingPawns != null)
				{
					list = startingPawns.Where((Pawn p) => p != null && !p.Dead && p.RaceProps.Humanlike).ToList();
				}
				if (list != null && list.Count != 0)
				{
					float num = ((RaidRankPatches.lastRaidPoints > 0f) ? RaidRankPatches.lastRaidPoints : RaidRankPatches.EstimateRaidPoints(list));
					RaidRankSystem.ProcessRaidPawns(list, num, map);
					if (Prefs.DevMode)
					{
						string arg = (flag ? "hostile" : "allied");
						Log.Message($"[Isekai Raid] Processed {list.Count} {arg} pawns, {num:F0} points, " + "Lord: " + (((object)lordJob)?.GetType().Name ?? "Unknown"));
					}
					RaidRankPatches.lastRaidPoints = 0f;
					RaidRankPatches.lastRaidMap = null;
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Raid] Error processing raid pawns: " + ex.Message);
			}
		}
	}
	public static class RaidRankSystem
	{
		private static readonly Random random = new Random();

		private static readonly (MobRankTier rank, float minPoints)[] RankThresholds = new(MobRankTier, float)[7]
		{
			(MobRankTier.S, 25000f),
			(MobRankTier.A, 14000f),
			(MobRankTier.B, 7000f),
			(MobRankTier.C, 3500f),
			(MobRankTier.D, 1200f),
			(MobRankTier.E, 400f),
			(MobRankTier.F, 0f)
		};

		private static readonly (int offset, float weight)[] BalancedVarianceWeights = new(int, float)[6]
		{
			(-2, 15f),
			(-1, 35f),
			(0, 44f),
			(1, 5f),
			(2, 0.9f),
			(3, 0.1f)
		};

		private static readonly (int offset, float weight)[] ClassicVarianceWeights = new(int, float)[6]
		{
			(-2, 10f),
			(-1, 25f),
			(0, 45f),
			(1, 13f),
			(2, 5f),
			(3, 2f)
		};

		public static float GetEffectiveRaidPoints(float rawPoints, Map map)
		{
			if (map == null)
			{
				return rawPoints;
			}
			float num = 0f;
			int num2 = 0;
			int num3 = 0;
			WealthWatcher wealthWatcher = map.wealthWatcher;
			float num4 = ((wealthWatcher != null) ? wealthWatcher.WealthTotal : 0f);
			foreach (Pawn item in map.mapPawns.FreeColonistsSpawned)
			{
