			if (map == null)
			{
				return mobRankTier;
			}
			foreach (Pawn item in map.mapPawns.FreeColonistsSpawned)
			{
				IsekaiComponent cached = IsekaiComponent.GetCached(item);
				if (cached != null)
				{
					MobRankTier rank = cached.GetRank();
					if (rank > mobRankTier)
					{
						mobRankTier = rank;
					}
				}
			}
			return mobRankTier;
		}

		public static void AssignRaidPawnRank(Pawn pawn, float raidPoints, Map map, bool isLeader = false)
		{
			if (pawn == null || pawn.playerSettings != null || IncidentWorker_IsekaiHunt.IsBountyPawn(pawn))
			{
				return;
			}
			IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
			if (cached == null || cached.forgeLocked)
			{
				return;
			}
			float effectiveRaidPoints = GetEffectiveRaidPoints(raidPoints, map);
			MobRankTier baseRankForPoints = GetBaseRankForPoints(effectiveRaidPoints);
			bool allowHighTier = false;
			MobRankTier mobRankTier = ApplyRankVariance(baseRankForPoints, isLeader, allowHighTier);
			IsekaiSettings settings = IsekaiMod.Settings;
			if (settings != null && settings.AdaptiveRaidRanks)
			{
				MobRankTier colonyBestRank = GetColonyBestRank(map);
				int num = (int)colonyBestRank;
				int val = Math.Max(0, num - 1);
				int val2 = Math.Min(6, num + 1);
				int val3 = IsekaiMod.Settings?.MaxRaidRank ?? 6;
				val2 = Math.Min(val2, val3);
				int num2 = Math.Max(val, Math.Min(val2, (int)mobRankTier));
				if (Prefs.DevMode && num2 != (int)mobRankTier)
				{
					Log.Message("[Isekai Raid] Adaptive clamp: " + MobRankUtility.GetRankString(mobRankTier) + " -> " + MobRankUtility.GetRankString((MobRankTier)num2) + " (colony best: " + MobRankUtility.GetRankString(colonyBestRank) + ", range: ñ1)");
				}
				mobRankTier = (MobRankTier)num2;
			}
			int levelForRank = GetLevelForRank(mobRankTier);
			int levelVarianceForRank = GetLevelVarianceForRank(mobRankTier);
			levelForRank += random.Next(-levelVarianceForRank, levelVarianceForRank + 1);
			levelForRank = Math.Max(1, levelForRank);
			string rankString = MobRankUtility.GetRankString(mobRankTier);
			PawnStatGenerator.GenerateStatsForRank(rankString, cached.stats);
			cached.currentLevel = levelForRank;
			cached.stats.availableStatPoints = 0;
			PawnRoleStats.ApplyRoleDistribution(pawn, cached);
			PawnStatGenerator.UpdateRankTraitFromStats(pawn, cached);
			if (Prefs.DevMode)
			{
				Log.Message("[Isekai Raid] " + ((Entity)pawn).LabelShort + ": Base " + MobRankUtility.GetRankString(baseRankForPoints) + " -> " + string.Format("Final {0} (Lv{1}){2}", rankString, levelForRank, isLeader ? " [LEADER]" : ""));
			}
		}

		private static int GetLevelForRank(MobRankTier rank)
		{
			return rank switch
			{
				MobRankTier.F => 3, 
				MobRankTier.E => 8, 
				MobRankTier.D => 14, 
				MobRankTier.C => 22, 
				MobRankTier.B => 38, 
				MobRankTier.A => 70, 
				MobRankTier.S => 130, 
				MobRankTier.SS => 280, 
				MobRankTier.SSS => 450, 
				_ => 1, 
			};
		}

		private static int GetLevelVarianceForRank(MobRankTier rank)
		{
			return rank switch
			{
				MobRankTier.F => 1, 
				MobRankTier.E => 2, 
				MobRankTier.D => 3, 
				MobRankTier.C => 4, 
				MobRankTier.B => 6, 
				MobRankTier.A => 10, 
				MobRankTier.S => 15, 
				MobRankTier.SS => 25, 
				MobRankTier.SSS => 30, 
				_ => 1, 
			};
		}

		public static bool IsRaidLeader(Pawn pawn, List<Pawn> allRaidPawns)
		{
			if (pawn == null)
			{
				return false;
			}
			if (((Thing)pawn).Faction?.leader == pawn)
			{
				return true;
			}
			if (allRaidPawns != null && allRaidPawns.Count > 0)
			{
				float num = 0f;
				Pawn val = null;
				foreach (Pawn allRaidPawn in allRaidPawns)
				{
					float num2 = allRaidPawn.kindDef?.combatPower ?? 0f;
					if (num2 > num)
					{
						num = num2;
						val = allRaidPawn;
					}
				}
				if (val == pawn)
				{
					return true;
				}
			}
			return false;
		}

		public static void ProcessRaidPawns(List<Pawn> raidPawns, float raidPoints, Map map)
		{
			if ((IsekaiMod.Settings != null && !IsekaiMod.Settings.EnableRaidRanking) || raidPawns == null || raidPawns.Count == 0)
			{
				return;
			}
			foreach (Pawn raidPawn in raidPawns)
			{
				if (raidPawn != null && !raidPawn.Dead && raidPawn.RaceProps.Humanlike && !IsEstablishedPawn(raidPawn))
				{
					bool isLeader = IsRaidLeader(raidPawn, raidPawns);
					AssignRaidPawnRank(raidPawn, raidPoints, map, isLeader);
				}
			}
		}

		private static bool IsEstablishedPawn(Pawn pawn)
		{
			if (pawn.playerSettings != null)
			{
				return true;
			}
			return false;
		}
	}
	public static class RangedDamageScaling
	{
		private const float HumanRangedCap = 3f;

		public static float GetCreatureRangedMult(MobRankComponent c)
		{
			if (c?.stats == null)
			{
				return 1f;
			}
			return PlayerCreatureScaling.ScaledMultPublic(c.stats.dexterity, IsekaiLevelingSettings.DEX_RangedDamage);
		}

		public static float GetMechRangedMult(Pawn mech)
		{
			IsekaiComponent mechanitorComp = MechScalingSystem.GetMechanitorComp(mech);
			if (mechanitorComp?.stats == null)
			{
				return 1f;
			}
			return 1f + (float)Math.Max(0, mechanitorComp.stats.dexterity - 5) * IsekaiLevelingSettings.DEX_RangedDamage;
		}

		public static float GetHumanRangedMult(Pawn pawn, IsekaiComponent comp)
		{
			if (comp?.stats == null)
			{
				return 1f;
			}
			float num = comp.stats.dexterity;
			float statEffectiveness = IsekaiTraitHelper.GetStatEffectiveness(pawn, IsekaiStatType.Dexterity, comp.currentLevel);
			if (statEffectiveness != 1f)
			{
				num = 5f + (num - 5f) * statEffectiveness;
			}
			float num2 = 1f + Mathf.Max(0f, num - 5f) * IsekaiLevelingSettings.DEX_RangedDamageHuman;
			if (float.IsNaN(num2) || float.IsInfinity(num2))
			{
				return 1f;
			}
			return SoftCap(num2, 1f, 3f);
		}

		private static float SoftCap(float value, float min, float cap)
		{
			if (value < min)
			{
				return min;
			}
			if (value <= cap)
			{
				return value;
			}
			float num = Mathf.Max(0.5f, cap * 0.5f);
			return cap + num * Mathf.Log(1f + (value - cap) / num);
		}

		public static float MultiplierFor(Thing launcher)
		{
			Pawn val = (Pawn)(object)((launcher is Pawn) ? launcher : null);
			if (val == null || val.Dead || val.RaceProps == null)
			{
				return 1f;
			}
			if (val.RaceProps.Humanlike)
			{
				if (IsekaiLevelingSettings.DEX_RangedDamageHuman <= 0f)
				{
					return 1f;
				}
				IsekaiComponent cached = IsekaiComponent.GetCached(val);
				return (cached == null) ? 1f : GetHumanRangedMult(val, cached);
			}
			if (((Thing)val).Faction == null || !((Thing)val).Faction.IsPlayer)
			{
				return 1f;
			}
			if (val.RaceProps.IsMechanoid)
			{
				if (!IsekaiLevelingSettings.EnableMechanitorXP)
				{
					return 1f;
				}
				if (!MechScalingSystem.IsPlayerMech(val))
				{
					return 1f;
				}
				return GetMechRangedMult(val);
			}
			if (!PlayerCreatureScaling.IsPlayerScalableCreature(val))
			{
				return 1f;
			}
			return GetCreatureRangedMult(PlayerCreatureScaling.GetComp(val));
		}
	}
