			if (compForgeEnhancement == null)
			{
				return;
			}
			maxRefinement = Mathf.Clamp(maxRefinement, 0, 10);
			minRefinement = Mathf.Clamp(minRefinement, 1, maxRefinement);
			maxRuneRank = Mathf.Clamp(maxRuneRank, 1, 5);
