							RuneDef rune = GenCollection.RandomElement<RuneDef>((IEnumerable<RuneDef>)list);
							int weightedRuneRank = GetWeightedRuneRank(maxRuneRank);
							compForgeEnhancement.TryAddRune(rune, weightedRuneRank);
