	public class StatPart_RuneEffect : StatPart_ForgeBase
	{
		public RuneEffectType targetEffect;

		public bool isMultiplier = false;

		public bool isReduction = false;

		protected override void TransformValueCore(StatRequest req, ref float val)
		{
			//IL_0010: Unknown result type (might be due to invalid IL or missing references)
			if (!IsekaiLevelingSettings.EnableForgeSystem)
			{
				return;
			}
			float totalRuneBonus = GetTotalRuneBonus(req);
			if (totalRuneBonus != 0f)
			{
				if (isMultiplier)
				{
					val *= (isReduction ? (1f - totalRuneBonus) : (1f + totalRuneBonus));
				}
				else
				{
					val += (isReduction ? (0f - totalRuneBonus) : totalRuneBonus);
				}
			}
		}

		protected override string ExplanationPartCore(StatRequest req)
		{
			//IL_0015: Unknown result type (might be due to invalid IL or missing references)
			//IL_0055: Unknown result type (might be due to invalid IL or missing references)
			//IL_005a: Unknown result type (might be due to invalid IL or missing references)
			//IL_0098: Unknown result type (might be due to invalid IL or missing references)
			//IL_009d: Unknown result type (might be due to invalid IL or missing references)
			if (!IsekaiLevelingSettings.EnableForgeSystem)
			{
				return null;
			}
			float totalRuneBonus = GetTotalRuneBonus(req);
			if (totalRuneBonus == 0f)
			{
				return null;
			}
			if (isReduction)
			{
				return TaggedString.op_Implicit(TranslatorFormattedStringExtensions.Translate("Isekai_StatExp_RuneEnchant", NamedArgument.op_Implicit($"-{totalRuneBonus * 100f:F0}%")));
			}
			string arg = ((totalRuneBonus > 0f) ? "+" : "");
			return TaggedString.op_Implicit(TranslatorFormattedStringExtensions.Translate("Isekai_StatExp_RuneEnchant", NamedArgument.op_Implicit($"{arg}{totalRuneBonus * 100f:F0}%")));
		}

		private float GetTotalRuneBonus(StatRequest req)
		{
			if (!((StatRequest)(ref req)).HasThing)
			{
				return 0f;
			}
			Thing thing = ((StatRequest)(ref req)).Thing;
			Pawn val = (Pawn)(object)((thing is Pawn) ? thing : null);
			if (val != null)
			{
				float num = 0f;
				Pawn_EquipmentTracker equipment = val.equipment;
				if (((equipment != null) ? equipment.Primary : null) != null)
				{
					num += GetRuneBonusFromThing((Thing)(object)val.equipment.Primary);
				}
				Pawn_ApparelTracker apparel = val.apparel;
				if (((apparel != null) ? apparel.WornApparel : null) != null)
				{
					foreach (Apparel item in val.apparel.WornApparel)
					{
						num += GetRuneBonusFromThing((Thing)(object)item);
					}
				}
				return num;
			}
			return GetRuneBonusFromThing(((StatRequest)(ref req)).Thing);
		}

		private float GetRuneBonusFromThing(Thing thing)
		{
			CompForgeEnhancement compForgeEnhancement = ((thing != null) ? ThingCompUtility.TryGetComp<CompForgeEnhancement>(thing) : null);
			if (compForgeEnhancement == null)
			{
				return 0f;
			}
			float num = 0f;
			List<(RuneDef, int)> appliedRunesWithRanks = compForgeEnhancement.GetAppliedRunesWithRanks();
			foreach (var (runeDef, rank) in appliedRunesWithRanks)
			{
				if (runeDef.effectType == targetEffect)
				{
					num += runeDef.GetMagnitudeForRank(rank);
				}
			}
			return num;
		}
	}
	public class StatPart_ForgeMarketValue : StatPart_ForgeBase
	{
		private const float RefinementValuePerLevel = 0.25f;

		private const float RuneValuePerRank = 0.4f;

		protected override void TransformValueCore(StatRequest req, ref float val)
		{
			if (!IsekaiLevelingSettings.EnableForgeSystem || !((StatRequest)(ref req)).HasThing)
			{
				return;
			}
			CompForgeEnhancement compForgeEnhancement = ThingCompUtility.TryGetComp<CompForgeEnhancement>(((StatRequest)(ref req)).Thing);
			if (compForgeEnhancement != null)
			{
				float valueMultiplier = GetValueMultiplier(compForgeEnhancement);
				if (valueMultiplier != 1f)
				{
					val *= valueMultiplier;
				}
			}
		}

		protected override string ExplanationPartCore(StatRequest req)
		{
			//IL_00f8: Unknown result type (might be due to invalid IL or missing references)
			//IL_0112: Unknown result type (might be due to invalid IL or missing references)
			//IL_0117: Unknown result type (might be due to invalid IL or missing references)
			//IL_0121: Unknown result type (might be due to invalid IL or missing references)
			//IL_0126: Unknown result type (might be due to invalid IL or missing references)
			//IL_015c: Unknown result type (might be due to invalid IL or missing references)
			//IL_0161: Unknown result type (might be due to invalid IL or missing references)
			//IL_0166: Unknown result type (might be due to invalid IL or missing references)
			if (!IsekaiLevelingSettings.EnableForgeSystem)
			{
				return null;
			}
			if (!((StatRequest)(ref req)).HasThing)
			{
				return null;
			}
			CompForgeEnhancement compForgeEnhancement = ThingCompUtility.TryGetComp<CompForgeEnhancement>(((StatRequest)(ref req)).Thing);
			if (compForgeEnhancement == null)
			{
				return null;
			}
			float num = (float)compForgeEnhancement.refinementLevel * 0.25f;
			float num2 = 0f;
			List<(RuneDef, int)> appliedRunesWithRanks = compForgeEnhancement.GetAppliedRunesWithRanks();
			foreach (var item3 in appliedRunesWithRanks)
			{
				RuneDef item = item3.Item1;
				int item2 = item3.Item2;
				num2 += (float)item2 * 0.4f;
			}
			if (num == 0f && num2 == 0f)
			{
				return null;
			}
			string text = "";
			if (num > 0f)
			{
				text = TaggedString.op_Implicit(text + (TranslatorFormattedStringExtensions.Translate("Isekai_StatExp_RefineMarket", NamedArgument.op_Implicit(compForgeEnhancement.refinementLevel.ToString()), NamedArgument.op_Implicit((num * 100f).ToString("F0"))) + "\n"));
			}
			if (num2 > 0f)
			{
				text = TaggedString.op_Implicit(text + TranslatorFormattedStringExtensions.Translate("Isekai_StatExp_RuneMarket", NamedArgument.op_Implicit((num2 * 100f).ToString("F0"))));
			}
			return text.TrimEnd();
		}

		private float GetValueMultiplier(CompForgeEnhancement comp)
		{
			float num = (float)comp.refinementLevel * 0.25f;
			List<(RuneDef, int)> appliedRunesWithRanks = comp.GetAppliedRunesWithRanks();
			foreach (var item3 in appliedRunesWithRanks)
			{
				RuneDef item = item3.Item1;
				int item2 = item3.Item2;
				num += (float)item2 * 0.4f;
			}
			return 1f + num;
		}
	}
	public static class ForgeUtility
	{
		public struct RefineCost
		{
			public ThingDef coreDef;

			public int coreCount;

			public ThingDef secondaryCoreDef;

			public int secondaryCoreCount;

			public int steel;

			public int components;

			public bool RequiresReinforcementCore => coreDef == _reinforcementCore || secondaryCoreDef == _reinforcementCore;
		}

		public enum RefineResult
		{
			Success,
			Failed,
			Downgrade
		}

		private static ThingDef _smallManaCore;

		private static ThingDef _manaCore;

		private static ThingDef _bigManaCore;

		private static ThingDef _hugeManaCore;

		private static ThingDef _reinforcementCore;

		private static ThingDef _steel;

		private static ThingDef _component;

		private static bool _defsResolved;

		private static ThingDef _manaEssence;

		public static ThingDef RefinementComponent
		{
			get
			{
				ResolveDefsIfNeeded();
				return _component;
			}
		}

		private static ThingDef ManaEssenceDef
		{
			get
			{
				if (_manaEssence == null)
				{
					_manaEssence = DefDatabase<ThingDef>.GetNamedSilentFail("Isekai_ManaEssence");
				}
				return _manaEssence;
			}
		}

		private static void ResolveDefsIfNeeded()
		{
			if (!_defsResolved)
			{
				_smallManaCore = DefDatabase<ThingDef>.GetNamedSilentFail("Isekai_SmallManaCore");
				_manaCore = DefDatabase<ThingDef>.GetNamedSilentFail("Isekai_ManaCore");
				_bigManaCore = DefDatabase<ThingDef>.GetNamedSilentFail("Isekai_BigManaCore");
				_hugeManaCore = DefDatabase<ThingDef>.GetNamedSilentFail("Isekai_HugeManaCore");
				_reinforcementCore = DefDatabase<ThingDef>.GetNamedSilentFail("Isekai_ReinforcementCore");
				_steel = ThingDefOf.Steel;
				_component = ResolveRefinementComponent();
				_defsResolved = true;
			}
		}

		private static ThingDef ResolveRefinementComponent()
		{
			string refinementComponentDefName = IsekaiLevelingSettings.RefinementComponentDefName;
			if (!string.IsNullOrEmpty(refinementComponentDefName))
			{
				ThingDef namedSilentFail = DefDatabase<ThingDef>.GetNamedSilentFail(refinementComponentDefName);
				if (namedSilentFail != null)
				{
					return namedSilentFail;
				}
			}
			return ThingDefOf.ComponentIndustrial;
		}

		public static void RefreshRefinementComponent()
		{
			_component = ResolveRefinementComponent();
		}

		public static float GetBaseSuccessChance(int targetLevel)
		{
			return targetLevel switch
			{
				1 => 1f, 
				2 => 1f, 
				3 => 0.95f, 
				4 => 0.9f, 
				5 => 0.8f, 
				6 => 0.65f, 
				7 => 0.55f, 
				8 => 0.45f, 
				9 => 0.35f, 
				10 => 0.25f, 
				_ => 0f, 
			};
		}

		public static float GetSuccessChance(int targetLevel, Pawn crafter)
		{
			float num = GetBaseSuccessChance(targetLevel);
			float refinementSuccessMultiplier = IsekaiLevelingSettings.RefinementSuccessMultiplier;
			if (crafter != null)
			{
				Pawn_SkillTracker skills = crafter.skills;
				int? obj;
				if (skills == null)
				{
					obj = null;
				}
				else
				{
					SkillRecord skill = skills.GetSkill(SkillDefOf.Crafting);
					obj = ((skill != null) ? new int?(skill.Level) : ((int?)null));
				}
				int? num2 = obj;
				int valueOrDefault = num2.GetValueOrDefault();
				int num3 = Mathf.Max(0, valueOrDefault - 10);
				num += (float)num3 * 0.01f;
			}
			return Mathf.Clamp01(num * refinementSuccessMultiplier);
		}

		public static float GetDowngradeChance(int targetLevel)
		{
			return targetLevel switch
			{
				6 => 0.1f, 
				7 => 0.2f, 
				8 => 0.3f, 
				9 => 0.35f, 
				10 => 0.45f, 
				_ => 0f, 
			};
		}

		public static float GetFailChance(int targetLevel, Pawn crafter = null)
		{
			float successChance = GetSuccessChance(targetLevel, crafter);
			float num = Mathf.Min(GetDowngradeChance(targetLevel), 1f - successChance);
			return Mathf.Max(0f, 1f - successChance - num);
		}

		public static RefineCost GetRefineCost(int targetLevel)
		{
			ResolveDefsIfNeeded();
			switch (targetLevel)
			{
			case 1:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _smallManaCore;
				result.coreCount = 1;
				result.steel = 20;
				return result;
			}
			case 2:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _smallManaCore;
				result.coreCount = 2;
				result.steel = 30;
				return result;
			}
			case 3:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _manaCore;
				result.coreCount = 1;
				result.steel = 40;
				result.components = 1;
				return result;
			}
			case 4:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _manaCore;
				result.coreCount = 1;
				result.steel = 60;
				result.components = 1;
				return result;
			}
			case 5:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _bigManaCore;
				result.coreCount = 1;
				result.steel = 80;
				result.components = 2;
				return result;
			}
			case 6:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _reinforcementCore;
				result.coreCount = 1;
				result.secondaryCoreDef = _manaCore;
				result.secondaryCoreCount = 1;
				result.steel = 100;
				return result;
			}
			case 7:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _reinforcementCore;
				result.coreCount = 1;
				result.secondaryCoreDef = _bigManaCore;
				result.secondaryCoreCount = 1;
				result.steel = 125;
				return result;
			}
			case 8:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _reinforcementCore;
				result.coreCount = 1;
				result.secondaryCoreDef = _bigManaCore;
				result.secondaryCoreCount = 1;
				result.steel = 150;
				return result;
			}
			case 9:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _reinforcementCore;
				result.coreCount = 1;
				result.secondaryCoreDef = _hugeManaCore;
				result.secondaryCoreCount = 1;
				result.steel = 200;
				return result;
			}
			case 10:
			{
				RefineCost result = default(RefineCost);
				result.coreDef = _reinforcementCore;
				result.coreCount = 1;
				result.secondaryCoreDef = _hugeManaCore;
				result.secondaryCoreCount = 2;
				result.steel = 250;
				return result;
			}
			default:
				return default(RefineCost);
			}
		}

		public static bool HasMaterials(Map map, RefineCost cost)
		{
			if (map == null)
			{
				return false;
			}
			if (cost.coreDef != null && cost.coreCount > 0 && CountOnMap(map, cost.coreDef) < cost.coreCount)
			{
				return false;
			}
			if (cost.secondaryCoreDef != null && cost.secondaryCoreCount > 0 && CountOnMap(map, cost.secondaryCoreDef) < cost.secondaryCoreCount)
			{
				return false;
			}
			if (cost.steel > 0 && CountOnMap(map, _steel) < cost.steel)
			{
				return false;
			}
			if (cost.components > 0 && CountOnMap(map, _component) < cost.components)
			{
				return false;
			}
			return true;
		}

		public static void ConsumeMaterials(Map map, RefineCost cost)
		{
			if (map != null)
			{
				if (cost.coreDef != null && cost.coreCount > 0)
				{
					ConsumeFromMap(map, cost.coreDef, cost.coreCount);
				}
				if (cost.secondaryCoreDef != null && cost.secondaryCoreCount > 0)
				{
					ConsumeFromMap(map, cost.secondaryCoreDef, cost.secondaryCoreCount);
				}
				if (cost.steel > 0)
				{
					ConsumeFromMap(map, _steel, cost.steel);
				}
				if (cost.components > 0)
				{
					ConsumeFromMap(map, _component, cost.components);
				}
			}
		}

		internal static int CountOnMap(Map map, ThingDef def)
		{
			if (def == null || map == null)
			{
				return 0;
			}
			int num = 0;
			foreach (Thing item in map.listerThings.ThingsOfDef(def))
			{
				if (!ForbidUtility.IsForbidden(item, Faction.OfPlayer) && StoreUtility.IsInValidStorage(item))
				{
					num += item.stackCount;
				}
			}
			return num;
		}

		private static void ConsumeFromMap(Map map, ThingDef def, int count)
		{
			if (def == null || count <= 0)
			{
				return;
			}
			int num = count;
			List<Thing> list = map.listerThings.ThingsOfDef(def).ToList();
			foreach (Thing item in list)
			{
				if (num <= 0)
				{
					break;
				}
				if (!ForbidUtility.IsForbidden(item, Faction.OfPlayer) && StoreUtility.IsInValidStorage(item))
				{
					int num2 = Mathf.Min(item.stackCount, num);
					item.SplitOff(num2).Destroy((DestroyMode)0);
					num -= num2;
				}
			}
		}

