		public static RefineResult AttemptRefinement(Thing item, Map map, Pawn crafter)
		{
			CompForgeEnhancement compForgeEnhancement = ((item != null) ? ThingCompUtility.TryGetComp<CompForgeEnhancement>(item) : null);
			if (compForgeEnhancement == null || !compForgeEnhancement.CanRefine())
			{
				return RefineResult.Failed;
			}
			int num = compForgeEnhancement.refinementLevel + 1;
			RefineCost refineCost = GetRefineCost(num);
			if (!Prefs.DevMode || !DebugSettings.godMode)
			{
				if (!HasMaterials(map, refineCost))
				{
					return RefineResult.Failed;
				}
				ConsumeMaterials(map, refineCost);
			}
			float successChance = GetSuccessChance(num, crafter);
			float value = Rand.Value;
			float conditionFrac = (float)item.HitPoints / (float)Mathf.Max(1, LiveMaxHitPoints(item));
			if (value < successChance)
			{
				compForgeEnhancement.refinementLevel = num;
				ApplyCondition(item, conditionFrac);
				return RefineResult.Success;
			}
			float num2 = Mathf.Min(GetDowngradeChance(num), 1f - successChance);
			if (value >= successChance + num2)
			{
				return RefineResult.Failed;
			}
			if (compForgeEnhancement.refinementLevel > 0)
			{
				compForgeEnhancement.refinementLevel--;
				ApplyCondition(item, conditionFrac);
			}
			return RefineResult.Downgrade;
		}

		public static int LiveMaxHitPoints(Thing item)
		{
			if (item == null)
			{
				return 1;
			}
			return Mathf.Max(1, Mathf.RoundToInt(StatExtension.GetStatValue(item, StatDefOf.MaxHitPoints, true, -1)));
		}

		public static void FillToMaxCondition(Thing item)
		{
			if (item != null && item.def != null && item.def.useHitPoints)
			{
				item.HitPoints = LiveMaxHitPoints(item);
			}
		}

		private static void ApplyCondition(Thing item, float conditionFrac)
		{
			if (item != null)
			{
				int num = LiveMaxHitPoints(item);
				item.HitPoints = Mathf.Clamp(Mathf.RoundToInt((float)num * conditionFrac), 1, num);
			}
		}

		public static int GetRepairEssenceCost(Thing item)
		{
			if (item == null)
			{
				return 0;
			}
			int num = LiveMaxHitPoints(item);
			if (item.HitPoints >= num)
			{
				return 0;
			}
			float num2 = 1f - (float)item.HitPoints / (float)num;
			return Mathf.Max(1, Mathf.CeilToInt(num2 * 5f));
		}

		public static bool NeedsRepair(Thing item)
		{
			return item != null && !item.Destroyed && item.HitPoints < LiveMaxHitPoints(item);
		}

		public static bool RepairItem(Thing item, Map map)
		{
			if (!NeedsRepair(item))
			{
				return false;
			}
			if (ManaEssenceDef == null)
			{
				return false;
			}
			int repairEssenceCost = GetRepairEssenceCost(item);
			if (!Prefs.DevMode || !DebugSettings.godMode)
			{
				if (CountOnMap(map, ManaEssenceDef) < repairEssenceCost)
				{
					return false;
				}
				ConsumeFromMap(map, ManaEssenceDef, repairEssenceCost);
			}
			item.HitPoints = LiveMaxHitPoints(item);
			return true;
		}
	}
