		Grandmaster
	}
	public class WeaponMasteryTracker : IExposable
	{
		public Dictionary<string, int> masteryXP = new Dictionary<string, int>();

		private static readonly int[] TierThresholds = new int[7] { 0, 100, 300, 700, 1500, 3000, 6000 };

		private static readonly float[][] TierBonuses = new float[7][]
		{
			new float[3],
			new float[3] { 0.08f, 0.04f, 0.03f },
			new float[3] { 0.15f, 0.08f, 0.06f },
			new float[3] { 0.22f, 0.12f, 0.1f },
			new float[3] { 0.3f, 0.18f, 0.15f },
			new float[3] { 0.4f, 0.25f, 0.22f },
			new float[3] { 0.5f, 0.3f, 0.3f }
		};

		public void ExposeData()
		{
			Scribe_Collections.Look<string, int>(ref masteryXP, "masteryXP", (LookMode)1, (LookMode)1);
			if (masteryXP == null)
			{
				masteryXP = new Dictionary<string, int>();
			}
		}

		public void AddMasteryXP(string weaponDefName, int amount, Pawn pawn = null)
		{
			if (!string.IsNullOrEmpty(weaponDefName) && amount > 0)
			{
				MasteryTier masteryTier = ((pawn != null) ? GetMasteryTier(weaponDefName) : MasteryTier.Novice);
				if (masteryXP.TryGetValue(weaponDefName, out var value))
				{
					masteryXP[weaponDefName] = value + amount;
				}
				else
				{
					masteryXP[weaponDefName] = amount;
				}
				if (pawn != null && GetMasteryTier(weaponDefName) != masteryTier)
				{
					IsekaiMoods.Gain(pawn, "Isekai_WeaponMastery");
				}
			}
		}

		public int GetXP(string weaponDefName)
		{
			if (string.IsNullOrEmpty(weaponDefName))
			{
				return 0;
			}
			int value;
			return masteryXP.TryGetValue(weaponDefName, out value) ? value : 0;
		}

		public MasteryTier GetMasteryTier(string weaponDefName)
		{
			int xP = GetXP(weaponDefName);
			MasteryTier result = MasteryTier.Novice;
			for (int num = TierThresholds.Length - 1; num >= 0; num--)
			{
				if (xP >= TierThresholds[num])
				{
					result = (MasteryTier)num;
					break;
				}
			}
			return result;
		}

		public int GetXPForNextTier(string weaponDefName)
		{
			MasteryTier masteryTier = GetMasteryTier(weaponDefName);
			int num = (int)(masteryTier + 1);
			if (num >= TierThresholds.Length)
			{
				return -1;
			}
			return TierThresholds[num];
		}

		public void GetMasteryBonuses(string weaponDefName, out float hitChance, out float attackSpeed, out float damage)
		{
			MasteryTier masteryTier = GetMasteryTier(weaponDefName);
			int num = (int)masteryTier;
			hitChance = TierBonuses[num][0];
			attackSpeed = TierBonuses[num][1];
			damage = TierBonuses[num][2];
		}

		public static string GetTierLabel(MasteryTier tier)
		{
			return tier switch
			{
				MasteryTier.Novice => "Novice", 
				MasteryTier.Apprentice => "Apprentice", 
				MasteryTier.Skilled => "Skilled", 
				MasteryTier.Adept => "Adept", 
				MasteryTier.Expert => "Expert", 
				MasteryTier.Master => "Master", 
				MasteryTier.Grandmaster => "Grandmaster", 
				_ => "Unknown", 
			};
		}
	}
