			foreach (Thing allThing in map.listerThings.AllThings)
			{
				if ((int)allThing.def.category == 2 && (allThing.def.IsWeapon || allThing.def.IsApparel) && !allThing.def.IsStuff && ThingCompUtility.TryGetComp<CompForgeEnhancement>(allThing) != null)
				{
					list.Add(allThing);
				}
			}
