		private List<Thing> GetAvailableRuneItems(CompForgeEnhancement comp)
		{
			//IL_0066: Unknown result type (might be due to invalid IL or missing references)
			//IL_006c: Invalid comparison between Unknown and I4
			List<Thing> list = new List<Thing>();
			if (map == null || comp == null)
			{
				return list;
			}
			RuneCategory runeCategory = ((!((Thing)((ThingComp)comp).parent).def.IsWeapon) ? RuneCategory.Armor : RuneCategory.Weapon);
			foreach (Thing allThing in map.listerThings.AllThings)
			{
				if ((int)allThing.def.category == 2 && ((Def)allThing.def).defName.StartsWith("Isekai_Rune_"))
				{
					RuneDef item = FindRuneDefAndRankForItem(((Def)allThing.def).defName).runeDef;
					if (item != null && item.category == runeCategory)
					{
						list.Add(allThing);
					}
				}
			}
			return list;
		}

		private static (RuneDef runeDef, int rank) FindRuneDefAndRankForItem(string itemDefName)
		{
			if (!itemDefName.StartsWith("Isekai_Rune_"))
			{
				return (runeDef: null, rank: 1);
			}
			string text = itemDefName.Substring("Isekai_Rune_".Length);
			for (int i = 0; i < RankSuffixes.Length; i++)
			{
				if (text.EndsWith(RankSuffixes[i]))
				{
					string text2 = text.Substring(0, text.Length - RankSuffixes[i].Length);
					RuneDef namedSilentFail = DefDatabase<RuneDef>.GetNamedSilentFail("Isekai_RuneDef_" + text2);
					if (namedSilentFail != null)
					{
						return (runeDef: namedSilentFail, rank: RankValues[i]);
					}
				}
			}
			RuneDef namedSilentFail2 = DefDatabase<RuneDef>.GetNamedSilentFail("Isekai_RuneDef_" + text);
			return (runeDef: namedSilentFail2, rank: 1);
		}

