						num6 = num7 * num7 * num3;
					}
					val.SetPixel(i, j, new Color(1f, 1f, 1f, num6));
				}
			}
			val.Apply();
			((Texture)val).wrapMode = (TextureWrapMode)1;
			return val;
		}
