	public class AuraPressureFxManager : MapComponent
	{
		private struct Impulse
		{
			public Vector3 pos;

			public float start;

			public float radius;

			public Color color;
		}

		private readonly List<Impulse> active = new List<Impulse>();

		public AuraPressureFxManager(Map map)
			: base(map)
		{
		}

		public void Add(Vector3 pos, float radius, Color color)
		{
			//IL_0031: Unknown result type (might be due to invalid IL or missing references)
			//IL_0032: Unknown result type (might be due to invalid IL or missing references)
			//IL_0057: Unknown result type (might be due to invalid IL or missing references)
			//IL_0058: Unknown result type (might be due to invalid IL or missing references)
			if (active.Count > 12)
			{
				active.RemoveAt(0);
			}
			active.Add(new Impulse
			{
				pos = pos,
				start = Time.time,
				radius = Mathf.Max(1f, radius),
				color = color
			});
		}

		public override void MapComponentUpdate()
		{
			//IL_008b: Unknown result type (might be due to invalid IL or missing references)
			//IL_00a0: Unknown result type (might be due to invalid IL or missing references)
			if (active.Count == 0)
			{
				return;
			}
			if (base.map != Find.CurrentMap)
			{
				active.Clear();
				return;
			}
			float time = Time.time;
			for (int num = active.Count - 1; num >= 0; num--)
			{
				Impulse impulse = active[num];
				if (time - impulse.start > 1.2f)
				{
					active.RemoveAt(num);
				}
				else
				{
					AuraPressureFX.Draw(impulse.pos, impulse.start, impulse.radius, impulse.color, time);
				}
			}
		}
	}
