		public bool HasAnyCustomTexture => !string.IsNullOrEmpty(customTexturePathTier1) || !string.IsNullOrEmpty(customTexturePathTier2) || !string.IsNullOrEmpty(customTexturePathTier3);

		public MobRankTier MinAuraRank => MobRankTier.D;

		public string GetTexturePathForRank(MobRankTier rank)
		{
			if (rank >= MobRankTier.S)
			{
				if (!string.IsNullOrEmpty(customTexturePathTier3))
				{
					return customTexturePathTier3;
				}
				if (!string.IsNullOrEmpty(customTexturePathTier2))
				{
					return customTexturePathTier2;
				}
				if (!string.IsNullOrEmpty(customTexturePathTier1))
				{
					return customTexturePathTier1;
				}
				return null;
			}
			if (rank >= MobRankTier.B)
			{
				if (!string.IsNullOrEmpty(customTexturePathTier2))
				{
					return customTexturePathTier2;
				}
				if (!string.IsNullOrEmpty(customTexturePathTier1))
				{
					return customTexturePathTier1;
				}
				return null;
			}
			if (rank >= MobRankTier.D)
			{
				return customTexturePathTier1;
			}
			return null;
		}
	}
	public static class AuraStyleResolver
	{
		private static readonly Dictionary<string, AuraStyle> StyleByTree = BuildStyles();

		public static AuraStyle Resolve(Pawn pawn)
		{
			if (pawn == null)
			{
				return null;
			}
			IsekaiComponent cached = IsekaiComponent.GetCached(pawn);
			if (cached == null)
			{
				return null;
			}
			string text = cached.auraConstellation;
			if (!string.IsNullOrEmpty(text))
			{
				PassiveTreeTracker passiveTree = cached.passiveTree;
				if (passiveTree == null || !passiveTree.HasEnteredTreeByName(text))
				{
					text = null;
				}
			}
			if (string.IsNullOrEmpty(text))
			{
				text = cached.passiveTree?.assignedTree;
			}
			if (string.IsNullOrEmpty(text))
			{
				return null;
			}
			StyleByTree.TryGetValue(text, out var value);
			return value;
		}

		public static AuraStyle ResolveByName(string treeName)
		{
			if (string.IsNullOrEmpty(treeName))
			{
				return null;
			}
			StyleByTree.TryGetValue(treeName, out var value);
			return value;
		}

