		}

		private static float ShapeAlpha(AuraFlameShape shape, float nx, float ny)
		{
			return shape switch
			{
				AuraFlameShape.Wavy => WavyAlpha(nx, ny), 
				AuraFlameShape.Shield => ShieldAlpha(nx, ny), 
				AuraFlameShape.SharpTip => SharpTipAlpha(nx, ny), 
				AuraFlameShape.Arrow => ArrowAlpha(nx, ny), 
				AuraFlameShape.Blade => BladeAlpha(nx, ny), 
				AuraFlameShape.Anvil => AnvilAlpha(nx, ny), 
				AuraFlameShape.Cross => CrossAlpha(nx, ny), 
				AuraFlameShape.Lotus => LotusAlpha(nx, ny), 
				AuraFlameShape.Banner => BannerAlpha(nx, ny), 
				AuraFlameShape.Ragged => RaggedAlpha(nx, ny), 
				AuraFlameShape.Lightning => LightningAlpha(nx, ny), 
				AuraFlameShape.Flask => FlaskAlpha(nx, ny), 
				AuraFlameShape.Claw => ClawAlpha(nx, ny), 
