		}

		private static float WavyAlpha(float nx, float ny)
		{
			float num = (1f - ny * ny) * 0.9f;
			float num2 = Mathf.Sin(ny * (float)Math.PI * 4f) * 0.16f;
			float num3 = Mathf.Abs(nx - num2);
			if (num3 >= num || num < 0.001f)
			{
				return 0f;
			}
			float num4 = 1f - num3 / num;
			float num5 = 1f - ny * ny * 0.8f;
			return num4 * num4 * num5;
		}

		private static float ShieldAlpha(float nx, float ny)
		{
			float num;
			if (ny < 0.4f)
			{
				num = 0.85f;
			}
			else
			{
				float num2 = (ny - 0.4f) / 0.6f;
				num = Mathf.Sqrt(Mathf.Max(0f, 1f - num2 * num2)) * 0.85f;
			}
			float num3 = Mathf.Abs(nx);
			if (num3 >= num || num < 0.001f)
			{
				return 0f;
			}
			float num4 = 1f - num3 / num;
			return num4 * num4;
		}

		private static float SharpTipAlpha(float nx, float ny)
		{
			float num = Mathf.Pow(1f - ny, 1.4f) * 0.7f;
			float num2 = Mathf.Abs(nx);
			if (num2 >= num || num < 0.001f)
			{
				return 0f;
			}
			return 1f - num2 / num;
		}

		private static float ArrowAlpha(float nx, float ny)
		{
			float num = Mathf.Sin(ny * (float)Math.PI) * 0.4f;
			float num2 = Mathf.Abs(nx);
