			{
				return 0f;
			}
			return 1f - num2 / num;
		}

		private static float BladeAlpha(float nx, float ny)
		{
			float num = ((!(ny < 0.85f)) ? (0.144f * (1f - (ny - 0.85f) / 0.15f)) : (0.32f * (1f - ny / 0.85f * 0.55f)));
