			}
			float num3 = 1f - num2 / num;
			return Mathf.Pow(num3, 0.7f);
		}

		private static float AnvilAlpha(float nx, float ny)
		{
			float num;
			if (ny >= 0.85f)
			{
				num = 0.95f;
			}
			else if (ny >= 0.75f)
			{
				float num2 = (ny - 0.75f) / 0.1f;
