		private static float CrossAlpha(float nx, float ny)
		{
			float num = 0f;
			if (Mathf.Abs(nx) < 0.18f)
			{
				num = 1f - Mathf.Abs(nx) / 0.18f;
			}
			float num2 = 0f;
