		}

		private static float LotusAlpha(float nx, float ny)
		{
			float num = Mathf.Sin(Mathf.Pow(ny, 0.6f) * (float)Math.PI) * 0.55f;
			float num2 = Mathf.Abs(nx);
			if (num2 >= num || num < 0.001f)
