		}

		private static float BannerAlpha(float nx, float ny)
		{
			float num = 0f;
			float num2 = Mathf.Abs(nx - -0.55f);
			if (num2 < 0.1f)
			{
				num = 1f - num2 / 0.1f;
			}
			float num3 = 0f;
			if (ny > 0.2f && ny < 0.95f)
			{
				float num4 = (ny - 0.2f) / 0.75f;
				float num5 = Mathf.Lerp(0.85f, -0.3f, num4);
