			float num5 = Mathf.Abs(nx - num4);
			if (num5 >= num3)
			{
				return 0f;
			}
			float num6 = 1f - num5 / num3;
			return num6 * num6;
		}

		private static float LightningAlpha(float nx, float ny)
		{
			float num2;
			float num3;
			if (ny >= 0.55f)
			{
				float num = (ny - 0.55f) / 0.45f;
				num2 = Mathf.Lerp(0.03f, 0.48f, num);
				num3 = Mathf.Lerp(-0.33f, 0.12f, num);
