			{
				float num4 = (ny - 0.45f) / 0.1f;
				num2 = Mathf.Lerp(0.33f, 0.03f, num4);
				num3 = Mathf.Lerp(-0.03f, -0.33f, num4);
			}
			else
			{
				float num5 = ny / 0.45f;
				num2 = Mathf.Lerp(-0.12f, 0.33f, num5);
				num3 = Mathf.Lerp(-0.48f, -0.03f, num5);
			}
			if (nx < num3 || nx > num2)
			{
				return 0f;
			}
			float num6 = (num2 - num3) * 0.5f;
			if (num6 < 0.001f)
			{
