			}
			float num3 = Mathf.Abs(nx);
			if (num3 >= num2 || num2 < 0.001f)
			{
				return 0f;
			}
			return 1f - num3 / num2;
		}

		private static float ClawAlpha(float nx, float ny)
		{
			float num = Mathf.Sin(ny * (float)Math.PI * 0.5f) * 0.45f;
