		public static void ClearCaches()
		{
			foreach (Dictionary<Color, Material> value in FlameMaterialsByShape.Values)
			{
				value.Clear();
			}
			foreach (Dictionary<Color, Material> value2 in FlameMaterialsByShapeMirrored.Values)
			{
				value2.Clear();
			}
			foreach (Dictionary<Color, Material> value3 in CustomFlameMaterials.Values)
			{
				value3.Clear();
			}
			foreach (Dictionary<Color, Material> value4 in CustomFlameMaterialsMirrored.Values)
			{
				value4.Clear();
			}
			foreach (Dictionary<Color, Material> value5 in ArmorGlowMaterials.Values)
			{
				value5.Clear();
			}
			ArmorGlowMaterials.Clear();
			GlowMaterials.Clear();
			MoteMaterials.Clear();
			LeafMaterials.Clear();
			PawnAuraStates.Clear();
		}
	}
