		public static float GetMeleeCounterParryMultiplier(IsekaiComponent comp)
		{
			if (comp?.stats == null)
			{
				return 1f;
			}
			int strength = comp.stats.strength;
			float num = (float)(strength - 5) * 0.02f;
			return 1f + Mathf.Clamp(num, -0.08f, 2f);
		}

