		public static void SetLevelDirectly(IsekaiComponent comp, int newLevel)
		{
			FieldInfo field = typeof(IsekaiComponent).GetField("currentLevel", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
			if (field != null)
			{
				field.SetValue(comp, newLevel);
				RecalculateAvailablePoints(comp);
			}
		}

		public static void RecalculateAvailablePoints(IsekaiComponent comp)
		{
			int num = comp.Level * IsekaiLevelingSettings.skillPointsPerLevel;
			int totalAllocatedPoints = comp.stats.TotalAllocatedPoints;
			comp.stats.availableStatPoints = num - totalAllocatedPoints;
		}

		public static void AutoDistributePoints(IsekaiComponent comp)
		{
			while (comp.stats.availableStatPoints > 0)
			{
				comp.stats.strength++;
				comp.stats.availableStatPoints--;
				if (comp.stats.availableStatPoints <= 0)
				{
					break;
				}
				comp.stats.dexterity++;
				comp.stats.availableStatPoints--;
				if (comp.stats.availableStatPoints <= 0)
				{
					break;
				}
				comp.stats.vitality++;
				comp.stats.availableStatPoints--;
				if (comp.stats.availableStatPoints <= 0)
				{
					break;
				}
				comp.stats.intelligence++;
				comp.stats.availableStatPoints--;
				if (comp.stats.availableStatPoints <= 0)
				{
					break;
				}
				comp.stats.wisdom++;
				comp.stats.availableStatPoints--;
				if (comp.stats.availableStatPoints <= 0)
				{
					break;
				}
				comp.stats.charisma++;
				comp.stats.availableStatPoints--;
			}
		}

		public static void ApplyStatEffects(Pawn pawn, IsekaiComponent comp)
		{
			if (pawn == null || comp == null)
			{
				return;
			}
			Pawn_HealthTracker health = pawn.health;
			if (health != null)
			{
				PawnCapacitiesHandler capacities = health.capacities;
				if (capacities != null)
				{
					capacities.Notify_CapacityLevelsDirty();
				}
			}
			Pawn_NeedsTracker needs = pawn.needs;
			if (needs == null)
			{
				return;
			}
			Need_Mood mood = needs.mood;
			if (mood == null)
			{
				return;
			}
			ThoughtHandler thoughts = mood.thoughts;
			if (thoughts != null)
			{
				SituationalThoughtHandler situational = thoughts.situational;
				if (situational != null)
				{
					situational.Notify_SituationalThoughtsDirty();
				}
			}
		}
	}
