			psionicBaseMax.Clear();
			magicMaxMPTracker.Clear();
			magicRegenTracker.Clear();
			mightMaxSPTracker.Clear();
			mightRegenTracker.Clear();
		}

		public static float GetMaxManaMultiplier(IsekaiComponent comp)
		{
			if (comp?.stats == null)
			{
				return 1f;
			}
			int intelligence = comp.stats.intelligence;
			float num = (float)(intelligence - 5) * 0.02f;
			float num2 = 1f + Mathf.Clamp(num, -0.08f, 2f);
			return num2 * (1f + GetPassiveBonus(comp, PassiveBonusType.RoM_MaxMana));
		}

