		public static void TryApply(Pawn pawn, IsekaiComponent comp)
		{
			try
			{
				if (pawn == null || comp == null || pawn.Dead || ((Thing)pawn).Destroyed || pawn.RaceProps == null || !pawn.RaceProps.Humanlike || (((Thing)pawn).Faction != null && ((Thing)pawn).Faction.IsPlayer) || !IsekaiLevelingSettings.VPEPsycastRankBonusEnabled || comp.forgeLocked)
				{
					return;
				}
				MobRankTier mobRankTier = MobRankUtility.TierFromLevel(comp.currentLevel);
				if (mobRankTier < MobRankTier.B || comp.psycastBonusTier >= (int)mobRankTier)
				{
					return;
				}
				Resolve();
				if (available)
				{
					comp.psycastBonusTier = (int)mobRankTier;
					RankBonus bonus = BonusFor(mobRankTier);
					if (!(bonus.chance <= 0f) && Rand.Chance(bonus.chance))
					{
						Apply(pawn, bonus);
					}
				}
