		public static void TryApplyForced(Pawn pawn, IsekaiComponent comp)
		{
			try
			{
				if (pawn == null || comp == null || pawn.Dead || ((Thing)pawn).Destroyed || pawn.RaceProps == null || !pawn.RaceProps.Humanlike || !ModCompatibility.VanillaPsycastsExpandedActive)
				{
					return;
				}
				MobRankTier mobRankTier = MobRankUtility.TierFromLevel(comp.currentLevel);
				if (mobRankTier < MobRankTier.B || comp.psycastBonusTier >= (int)mobRankTier)
				{
					return;
				}
				Resolve();
				if (available)
				{
					comp.psycastBonusTier = (int)mobRankTier;
					RankBonus bonus = BonusFor(mobRankTier);
					if (!(bonus.chance <= 0f) && Rand.Chance(bonus.chance))
					{
						Apply(pawn, bonus);
					}
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] Forced psycast bonus failed for " + ((pawn != null) ? ((Entity)pawn).LabelShortCap : null) + ": " + ex.Message);
			}
		}

		private static void Apply(Pawn pawn, RankBonus bonus)
		{
			object orCreatePsycastHediff = GetOrCreatePsycastHediff(pawn);
			if (orCreatePsycastHediff == null)
			{
				return;
			}
			object abilitiesComp = GetAbilitiesComp(pawn);
			if (abilitiesComp == null)
			{
				return;
			}
			Hediff_Level val = (Hediff_Level)((orCreatePsycastHediff is Hediff_Level) ? orCreatePsycastHediff : null);
			if (val == null)
			{
				return;
			}
			int num = MaxPsycastLevel();
			int num2 = Rand.RangeInclusive(bonus.minLevels, bonus.maxLevels);
			int num3 = Mathf.Clamp(num - val.level, 0, num2);
			if (num3 > 0)
			{
				mChangeLevel.Invoke(orCreatePsycastHediff, new object[2] { num3, false });
			}
			OpenPaths(pawn, orCreatePsycastHediff, bonus.paths);
			int num5 = ((fPoints.GetValue(orCreatePsycastHediff) is int num4) ? num4 : 0);
			if (num5 > 0)
			{
				int budget = Mathf.Max(1, Mathf.RoundToInt((float)num5 * 0.6f));
				int num6 = GrantAbilities(pawn, orCreatePsycastHediff, abilitiesComp, budget);
				int num7 = Mathf.Max(0, num5 - num6);
				if (num7 > 0)
				{
					mImproveStats.Invoke(orCreatePsycastHediff, new object[1] { num7 });
					fPoints.SetValue(orCreatePsycastHediff, Mathf.Max(0, num5 - num6 - num7));
				}
			}
		}

		private static int MaxPsycastLevel()
		{
			try
			{
				Type type = AccessTools.TypeByName("VanillaPsycastsExpanded.PsycastsMod");
				object obj = ((type != null) ? AccessTools.Field(type, "Settings") : null)?.GetValue(null);
				if (((obj != null) ? AccessTools.Field(obj.GetType(), "maxLevel") : null)?.GetValue(obj) is int num && num > 0)
				{
					return num;
				}
			}
			catch
			{
			}
			return 30;
		}

		private static object GetOrCreatePsycastHediff(Pawn pawn)
		{
			if (pawn.health?.hediffSet == null)
			{
				return null;
			}
			BodyPartRecord brain = pawn.health.hediffSet.GetBrain();
			if (brain == null)
			{
				return null;
			}
			Hediff firstHediffOfDef = pawn.health.hediffSet.GetFirstHediffOfDef(HediffDefOf.PsychicAmplifier, false);
			Hediff_Psylink val = (Hediff_Psylink)(object)((firstHediffOfDef is Hediff_Psylink) ? firstHediffOfDef : null);
			if (val == null)
			{
				Hediff obj = HediffMaker.MakeHediff(HediffDefOf.PsychicAmplifier, pawn, brain);
				val = (Hediff_Psylink)(object)((obj is Hediff_Psylink) ? obj : null);
				if (val == null)
				{
					return null;
				}
				pawn.health.AddHediff((Hediff)(object)val, brain, (DamageInfo?)null, (DamageResult)null);
			}
			Hediff val2 = pawn.health.hediffSet.GetFirstHediffOfDef(implantDef, false);
			if (val2 == null)
			{
				val2 = HediffMaker.MakeHediff(implantDef, pawn, brain);
				if (val2 == null)
				{
					return null;
				}
				pawn.health.AddHediff(val2, brain, (DamageInfo?)null, (DamageResult)null);
			}
			if (!tPsycastHediff.IsInstanceOfType(val2))
			{
				return null;
			}
			if (fPsylink.GetValue(val2) == null)
			{
				mInitFromPsylink.Invoke(val2, new object[1] { val });
			}
			return val2;
		}

		private static object GetAbilitiesComp(Pawn pawn)
		{
			List<ThingComp> allComps = ((ThingWithComps)pawn).AllComps;
			if (allComps == null)
			{
				return null;
			}
			for (int i = 0; i < allComps.Count; i++)
			{
				if (tCompAbilities.IsInstanceOfType(allComps[i]))
				{
					return allComps[i];
				}
			}
			return null;
		}

		private static void OpenPaths(Pawn pawn, object hediff, int count)
		{
			if (count <= 0)
			{
				return;
			}
			IList list = fUnlockedPaths.GetValue(hediff) as IList;
			if (!(pAllPathDefs.GetValue(null) is IList list2))
			{
				return;
			}
			List<object> list3 = new List<object>();
			bool flag = default(bool);
			for (int i = 0; i < list2.Count; i++)
			{
				object obj = list2[i];
				if (obj == null || (list != null && list.Contains(obj)))
				{
					continue;
				}
				try
				{
					object obj2 = mCanPawnUnlock.Invoke(obj, new object[1] { pawn });
					int num;
					if (obj2 is bool)
					{
						flag = (bool)obj2;
						num = 1;
					}
					else
					{
						num = 0;
					}
					if (((uint)num & (flag ? 1u : 0u)) != 0)
					{
						list3.Add(obj);
					}
				}
				catch
				{
				}
			}
			for (int j = 0; j < count; j++)
			{
				if (list3.Count <= 0)
				{
					break;
				}
				int index = Rand.Range(0, list3.Count);
				mUnlockPath.Invoke(hediff, new object[1] { list3[index] });
				list3.RemoveAt(index);
			}
		}

		private static int GrantAbilities(Pawn pawn, object hediff, object comp, int budget)
		{
			if (budget <= 0)
			{
				return 0;
			}
			if (!(fUnlockedPaths.GetValue(hediff) is IList { Count: not 0 } list))
			{
				return 0;
			}
			object obj = fBlankAbility?.GetValue(null);
			Def val = (Def)((obj is Def) ? obj : null);
			HashSet<string> hashSet = KnownAbilityDefs(comp);
			int num = 0;
			foreach (object item in list)
			{
				if (num >= budget)
				{
					break;
				}
				if (item == null || !(fAbilityLevels.GetValue(item) is Array array))
				{
					continue;
				}
				for (int i = 0; i < array.Length; i++)
				{
					if (num >= budget)
					{
						break;
					}
					if (!(array.GetValue(i) is Array array2))
					{
						continue;
					}
					for (int j = 0; j < array2.Length; j++)
					{
						if (num >= budget)
						{
							break;
						}
						object value = array2.GetValue(j);
						Def val2 = (Def)((value is Def) ? value : null);
						if (val2 != null && (val == null || val2 != val) && !hashSet.Contains(val2.defName))
						{
							try
							{
								mGiveAbility.Invoke(comp, new object[1] { val2 });
								hashSet.Add(val2.defName);
								num++;
							}
							catch
							{
							}
						}
					}
				}
			}
			if (num > 0 && fPoints.GetValue(hediff) is int num2)
			{
				fPoints.SetValue(hediff, Mathf.Max(0, num2 - num));
			}
			return num;
		}

		public static void CopyPsycasts(Pawn source, Pawn target)
		{
			try
			{
				Resolve();
				if (!available || source?.health?.hediffSet == null || target?.health == null)
				{
					return;
				}
				Hediff firstHediffOfDef = source.health.hediffSet.GetFirstHediffOfDef(implantDef, false);
				if (firstHediffOfDef == null)
				{
					return;
				}
				object orCreatePsycastHediff = GetOrCreatePsycastHediff(target);
				if (orCreatePsycastHediff == null)
				{
					return;
				}
				Hediff_Level val = (Hediff_Level)(object)((firstHediffOfDef is Hediff_Level) ? firstHediffOfDef : null);
				if (val != null)
				{
					Hediff_Level val2 = (Hediff_Level)((orCreatePsycastHediff is Hediff_Level) ? orCreatePsycastHediff : null);
					if (val2 != null && val.level > val2.level)
					{
						mChangeLevel.Invoke(orCreatePsycastHediff, new object[2]
						{
							val.level - val2.level,
							false
						});
					}
				}
				if (fUnlockedPaths.GetValue(firstHediffOfDef) is IList list && fUnlockedPaths.GetValue(orCreatePsycastHediff) is IList list2)
				{
					list2.Clear();
					foreach (object item in list)
					{
						list2.Add(item);
					}
				}
				object abilitiesComp = GetAbilitiesComp(source);
				object abilitiesComp2 = GetAbilitiesComp(target);
				if (abilitiesComp != null && abilitiesComp2 != null)
				{
					PropertyInfo propertyInfo = AccessTools.Property(tCompAbilities, "LearnedAbilities");
					HashSet<string> hashSet = KnownAbilityDefs(abilitiesComp2);
					if (propertyInfo?.GetValue(abilitiesComp) is IList list3)
					{
						foreach (object item2 in list3)
						{
							if (item2 == null)
							{
								continue;
							}
							object obj = AccessTools.Field(item2.GetType(), "def")?.GetValue(item2);
							Def val3 = (Def)((obj is Def) ? obj : null);
							if (val3 != null && !hashSet.Contains(val3.defName))
							{
								try
								{
									mGiveAbility.Invoke(abilitiesComp2, new object[1] { val3 });
									hashSet.Add(val3.defName);
								}
								catch
								{
								}
							}
						}
					}
				}
				if (fPoints.GetValue(firstHediffOfDef) is int num)
				{
					fPoints.SetValue(orCreatePsycastHediff, num);
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] CopyPsycasts failed for " + ((target != null) ? ((Entity)target).LabelShortCap : null) + ": " + ex.Message);
			}
		}

		public static void GrantFullPath(Pawn pawn, string pathDefName, int psylinkLevel)
		{
			try
			{
				Resolve();
				if (!available || pawn == null || string.IsNullOrEmpty(pathDefName))
				{
					return;
				}
				object orCreatePsycastHediff = GetOrCreatePsycastHediff(pawn);
				object abilitiesComp = GetAbilitiesComp(pawn);
				if (orCreatePsycastHediff == null || abilitiesComp == null)
				{
					return;
				}
				Hediff_Level val = (Hediff_Level)((orCreatePsycastHediff is Hediff_Level) ? orCreatePsycastHediff : null);
				if (val != null)
				{
					int num = Mathf.Min(psylinkLevel, MaxPsycastLevel());
					if (num > val.level)
					{
						mChangeLevel.Invoke(orCreatePsycastHediff, new object[2]
						{
							num - val.level,
							false
						});
					}
				}
				object obj = null;
				if (pAllPathDefs.GetValue(null) is IList list)
				{
					for (int i = 0; i < list.Count; i++)
					{
						object obj2 = list[i];
						Def val2 = (Def)((obj2 is Def) ? obj2 : null);
						if (val2 != null && val2.defName == pathDefName)
						{
							obj = list[i];
							break;
						}
					}
				}
				if (obj == null)
				{
					Log.Warning("[Isekai Leveling] GrantFullPath: no VPE path named '" + pathDefName + "'.");
					return;
				}
				if (!(fUnlockedPaths.GetValue(orCreatePsycastHediff) is IList list2) || !list2.Contains(obj))
				{
					mUnlockPath.Invoke(orCreatePsycastHediff, new object[1] { obj });
				}
				HashSet<string> hashSet = KnownAbilityDefs(abilitiesComp);
				if (fAbilityLevels.GetValue(obj) is Array array)
				{
					for (int j = 0; j < array.Length; j++)
					{
						if (!(array.GetValue(j) is Array array2))
						{
							continue;
						}
						object obj3 = fBlankAbility?.GetValue(null);
						Def val3 = (Def)((obj3 is Def) ? obj3 : null);
						for (int k = 0; k < array2.Length; k++)
						{
							object value = array2.GetValue(k);
							Def val4 = (Def)((value is Def) ? value : null);
							if (val4 != null && (val3 == null || val4 != val3) && !hashSet.Contains(val4.defName))
							{
								try
								{
									mGiveAbility.Invoke(abilitiesComp, new object[1] { val4 });
									hashSet.Add(val4.defName);
								}
								catch
								{
								}
							}
						}
					}
				}
				if (fPoints.GetValue(orCreatePsycastHediff) is int num2 && num2 > 0)
				{
					mImproveStats.Invoke(orCreatePsycastHediff, new object[1] { num2 });
					fPoints.SetValue(orCreatePsycastHediff, 0);
				}
			}
			catch (Exception ex)
			{
				Log.Warning("[Isekai Leveling] GrantFullPath failed for " + ((pawn != null) ? ((Entity)pawn).LabelShortCap : null) + ": " + ex.Message);
			}
		}

		private static HashSet<string> KnownAbilityDefs(object comp)
		{
			HashSet<string> hashSet = new HashSet<string>();
			try
			{
				if (AccessTools.Property(tCompAbilities, "LearnedAbilities")?.GetValue(comp) is IList list)
				{
					foreach (object item in list)
					{
						if (item != null)
						{
							object obj = AccessTools.Field(item.GetType(), "def")?.GetValue(item);
							Def val = (Def)((obj is Def) ? obj : null);
							if (val != null)
							{
								hashSet.Add(val.defName);
							}
						}
					}
				}
			}
			catch
			{
			}
			return hashSet;
		}
	}
