		public static bool IsComaImmuneCaster(Pawn pawn)
		{
			if (!TitleRead.TryGet(pawn, out var archetypeId, out var tier))
			{
				return false;
			}
			if (tier < TitleTier.Saint)
			{
				return false;
			}
			IsekaiBuildTitles.Archetype archetype = IsekaiBuildTitles.ById(archetypeId);
			if (archetype == null)
			{
				return false;
			}
			return archetype.Involves(IsekaiStatType.Intelligence) || archetype.Involves(IsekaiStatType.Wisdom);
		}
	}
