		private static T ResolveDef<T>(string defName, string fieldLabel) where T : Def
		{
			if (string.IsNullOrEmpty(defName))
			{
				return default(T);
			}
			T namedSilentFail = DefDatabase<T>.GetNamedSilentFail(defName);
			if (namedSilentFail == null)
			{
				Log.Warning("[Isekai Forge] Unknown " + fieldLabel + " def '" + defName + "' - field skipped.");
			}
			return namedSilentFail;
		}

		private static Faction ResolveFaction(string factionDefName)
		{
			if (factionDefName == "player")
			{
				return Faction.OfPlayer;
			}
			if (!string.IsNullOrEmpty(factionDefName))
			{
				FactionDef namedSilentFail = DefDatabase<FactionDef>.GetNamedSilentFail(factionDefName);
				Faction val = ((namedSilentFail != null) ? Find.FactionManager.FirstFactionOfDef(namedSilentFail) : null);
				if (val != null)
				{
					return val;
				}
				Log.Warning("[Isekai Forge] Faction '" + factionDefName + "' not found in this world - using a hostile faction.");
			}
			return IncidentWorker_IsekaiHunt.GetHostileFactionForBounty();
		}

		private static Thing MakeGear(GearSpec gs, string fieldLabel)
		{
			//IL_009a: Unknown result type (might be due to invalid IL or missing references)
			ThingDef val = ResolveDef<ThingDef>(gs?.def, fieldLabel);
			if (val == null)
			{
				return null;
			}
			ThingDef val2 = null;
			if (gs.stuff != null)
			{
				val2 = ResolveDef<ThingDef>(gs.stuff, fieldLabel + ".stuff");
			}
			if (val2 == null && ((BuildableDef)val).MadeFromStuff)
			{
				val2 = GenStuff.DefaultStuffFor((BuildableDef)(object)val);
			}
			Thing val3 = ThingMaker.MakeThing(val, val2);
			if (gs.quality != null && Enum.TryParse<QualityCategory>(gs.quality, ignoreCase: true, out QualityCategory result))
			{
				CompQuality obj = ThingCompUtility.TryGetComp<CompQuality>(val3);
				if (obj != null)
				{
					obj.SetQuality(result, (ArtGenerationContext?)(ArtGenerationContext)0);
				}
			}
			return val3;
		}
