							if (node != null && node.nodeId != null && !nodeLabels.ContainsKey(node.nodeId))
							{
								nodeLabels[node.nodeId] = node.label ?? node.nodeId;
							}
						}
					}
				}
				return nodeLabels;
			}
		}

