		private int DeriveLevelPreview()
		{
			IsekaiStatAllocation stats = StagedStats();
			return PawnStatGenerator.CalculateLevelFromStats(stats);
		}

		private void RescaleStatsToLevel()
		{
			int skillPointsPerLevel = IsekaiLevelingSettings.skillPointsPerLevel;
			int num = Mathf.Max(0, (valLevel - 1) * skillPointsPerLevel);
			int num2 = 5;
			int[] array = new int[6]
			{
				Mathf.Max(0, valStr - num2),
				Mathf.Max(0, valDex - num2),
				Mathf.Max(0, valVit - num2),
				Mathf.Max(0, valInt - num2),
				Mathf.Max(0, valWis - num2),
				Mathf.Max(0, valCha - num2)
			};
			int num3 = array.Sum();
			int[] array2 = new int[6];
			if (num3 <= 0)
			{
				for (int i = 0; i < 6; i++)
				{
					array2[i] = num / 6;
				}
				array2[0] += num - array2.Sum();
			}
			else
			{
				for (int j = 0; j < 6; j++)
				{
					array2[j] = Mathf.FloorToInt((float)array[j] * (float)num / (float)num3);
				}
				int num4 = 0;
				for (int k = 1; k < 6; k++)
				{
					if (array[k] > array[num4])
					{
						num4 = k;
					}
				}
				array2[num4] += num - array2.Sum();
			}
			valStr = num2 + array2[0];
			valDex = num2 + array2[1];
			valVit = num2 + array2[2];
			valInt = num2 + array2[3];
			valWis = num2 + array2[4];
			valCha = num2 + array2[5];
			RefreshBuffers();
		}

		private IsekaiStatAllocation StagedStats()
		{
			return new IsekaiStatAllocation
			{
				strength = valStr,
				dexterity = valDex,
				vitality = valVit,
				intelligence = valInt,
				wisdom = valWis,
				charisma = valCha
			};
		}

		private string PreviewTitle()
		{
			return IsekaiBuildTitles.NameFor(IsekaiBuildTitles.Classify(StagedStats()));
		}

		private string NodesText(List<string> nodes)
		{
			if (nodes == null || nodes.Count == 0)
			{
				return "Nodes: none unlocked.";
			}
			string value;
			IEnumerable<string> values = nodes.Select((string id) => NodeLabels.TryGetValue(id, out value) ? value : id);
			string arg = ((importedNodes != null) ? "imported preset" : "current build");
			return $"Nodes ({nodes.Count}, {arg}): " + string.Join(", ", values);
		}

		private IsekaiCharacterSpec BuildStagedSpec()
		{
			if (statsFromLevel)
			{
				RescaleStatsToLevel();
			}
			IsekaiCharacterSpec isekaiCharacterSpec = new IsekaiCharacterSpec
			{
				strength = valStr,
				dexterity = valDex,
				vitality = valVit,
				intelligence = valInt,
				wisdom = valWis,
				charisma = valCha,
				level = (deriveLevel ? ((int?)null) : new int?(valLevel)),
				constellation = treeClasses[treeIndex],
				inventorySilver = ((valSilver > 0) ? new int?(valSilver) : ((int?)null))
			};
			if (importedNodes != null && treeClasses[treeIndex] == importedTree)
			{
				isekaiCharacterSpec.constellationNodes = new List<string>(importedNodes);
			}
			return isekaiCharacterSpec;
		}

		private void DoApply()
		{
			IsekaiCharacterForge.Apply(pawn, BuildStagedSpec(), lockOnApply);
			if (!lockOnApply)
			{
				IsekaiCharacterForge.SetLocked(pawn, locked: false);
			}
			Messages.Message("Applied to " + ((Entity)pawn).LabelShortCap + ".", LookTargets.op_Implicit((Thing)(object)pawn), MessageTypeDefOf.TaskCompletion, false);
		}

		private void DoImport()
		{
			IsekaiCharacterSpec isekaiCharacterSpec = IsekaiCharacterForge.ParseSpecXml(GUIUtility.systemCopyBuffer);
			if (isekaiCharacterSpec == null)
			{
				importStatus = "Import failed: clipboard holds no readable <spec>. See the log.";
				return;
			}
			if (isekaiCharacterSpec.strength.HasValue)
			{
				valStr = isekaiCharacterSpec.strength.Value;
			}
			if (isekaiCharacterSpec.dexterity.HasValue)
			{
				valDex = isekaiCharacterSpec.dexterity.Value;
			}
			if (isekaiCharacterSpec.vitality.HasValue)
			{
				valVit = isekaiCharacterSpec.vitality.Value;
			}
			if (isekaiCharacterSpec.intelligence.HasValue)
			{
				valInt = isekaiCharacterSpec.intelligence.Value;
			}
			if (isekaiCharacterSpec.wisdom.HasValue)
			{
				valWis = isekaiCharacterSpec.wisdom.Value;
			}
			if (isekaiCharacterSpec.charisma.HasValue)
			{
				valCha = isekaiCharacterSpec.charisma.Value;
			}
			if (isekaiCharacterSpec.level.HasValue)
			{
				valLevel = isekaiCharacterSpec.level.Value;
			}
			if (isekaiCharacterSpec.inventorySilver.HasValue)
			{
				valSilver = isekaiCharacterSpec.inventorySilver.Value;
				bufSilver = valSilver.ToString();
			}
			RefreshBuffers();
			deriveLevel = false;
			statsFromLevel = false;
			if (!string.IsNullOrEmpty(isekaiCharacterSpec.constellation))
			{
				int num = treeClasses.IndexOf(isekaiCharacterSpec.constellation);
				if (num >= 0)
				{
					treeIndex = num;
				}
			}
			if (isekaiCharacterSpec.constellationNodes != null && isekaiCharacterSpec.constellationNodes.Count > 0)
			{
				importedNodes = isekaiCharacterSpec.constellationNodes;
				importedTree = isekaiCharacterSpec.constellation;
				importStatus = $"Imported build: {importedNodes.Count} nodes" + (string.IsNullOrEmpty(importedTree) ? " (WARNING: no tree named - nodes will be skipped)" : (" on " + importedTree + "."));
			}
			else
			{
				importedNodes = null;
				importStatus = "Imported stats (no node preset in the XML).";
			}
		}

		private void DoExport()
		{
			IsekaiCharacterSpec isekaiCharacterSpec = IsekaiCharacterForge.Capture(pawn);
			IsekaiCharacterSpec isekaiCharacterSpec2 = BuildStagedSpec();
			isekaiCharacterSpec.strength = isekaiCharacterSpec2.strength;
			isekaiCharacterSpec.dexterity = isekaiCharacterSpec2.dexterity;
			isekaiCharacterSpec.vitality = isekaiCharacterSpec2.vitality;
			isekaiCharacterSpec.intelligence = isekaiCharacterSpec2.intelligence;
			isekaiCharacterSpec.wisdom = isekaiCharacterSpec2.wisdom;
			isekaiCharacterSpec.charisma = isekaiCharacterSpec2.charisma;
			isekaiCharacterSpec.level = isekaiCharacterSpec2.level ?? isekaiCharacterSpec.level;
			if (isekaiCharacterSpec2.inventorySilver.HasValue)
			{
				isekaiCharacterSpec.inventorySilver = isekaiCharacterSpec2.inventorySilver;
			}
			isekaiCharacterSpec.constellation = isekaiCharacterSpec2.constellation;
			if (isekaiCharacterSpec2.constellationNodes != null)
			{
				isekaiCharacterSpec.constellationNodes = isekaiCharacterSpec2.constellationNodes;
			}
			else if (isekaiCharacterSpec.constellation != captured.constellation)
			{
				isekaiCharacterSpec.constellationNodes = null;
			}
			Name name = pawn.Name;
			NameTriple val = (NameTriple)(object)((name is NameTriple) ? name : null);
			string defName = "MyMod_" + ((val != null && !GenText.NullOrEmpty(val.First)) ? val.First : ((Entity)pawn).LabelShort).Replace(" ", "");
			string text2 = (GUIUtility.systemCopyBuffer = IsekaiCharacterForge.ExportXml(isekaiCharacterSpec, defName));
			Log.Message("[Isekai Forge] Exported character def:\n" + text2);
			Messages.Message("Character def copied to clipboard (and written to the log).", MessageTypeDefOf.TaskCompletion, false);
		}

