namespace IsekaiLeveling.Audio
{
	public static class IsekaiOST
	{
		public const string DefNamePrefix = "Isekai_OST_";

		private const float FadeSeconds = 3f;

		private const int MaxHistory = 3;

		private static List<SongDef> pool;

		private static readonly Queue<SongDef> recent = new Queue<SongDef>();

		public static List<SongDef> Pool
		{
			get
			{
				if (pool == null || pool.Count == 0)
				{
					pool = DefDatabase<SongDef>.AllDefsListForReading.Where(IsOurs).ToList();
				}
				return pool;
			}
		}

		public static bool IsOurs(SongDef song)
		{
			return song != null && ((Def)song).defName != null && ((Def)song).defName.StartsWith("Isekai_OST_", StringComparison.Ordinal);
		}

		public static void SyncTense(bool tense)
		{
			List<SongDef> list = Pool;
			for (int i = 0; i < list.Count; i++)
			{
				list[i].tense = tense;
			}
		}

		public static SongDef PickNext()
		{
			List<SongDef> list = Pool;
			if (list.Count == 0)
			{
				return null;
			}
			List<SongDef> list2 = list.Where((SongDef s) => (Object)(object)s.clip != (Object)null).ToList();
			if (list2.Count == 0)
			{
				return null;
			}
			List<SongDef> list3 = list2.Where((SongDef s) => !recent.Contains(s)).ToList();
			if (list3.Count == 0)
			{
				SongDef last = ((recent.Count > 0) ? recent.Last() : null);
				list3 = list2.Where((SongDef s) => s != last).ToList();
				if (list3.Count == 0)
				{
					list3 = list2;
				}
				recent.Clear();
			}
			SongDef val = GenCollection.RandomElementByWeight<SongDef>((IEnumerable<SongDef>)list3, (Func<SongDef, float>)((SongDef s) => Mathf.Max(0.0001f, s.commonality)));
			if (val == null)
			{
				return null;
			}
			recent.Enqueue(val);
			int num = Mathf.Min(3, list2.Count - 1);
			while (recent.Count > num)
			{
				recent.Dequeue();
			}
			return val;
		}

		public static float EnvelopeAt(float time, float duration)
		{
			if (duration <= 0f)
			{
				return 1f;
			}
			float num = Mathf.Min(3f, duration * 0.25f);
			if (num <= 0.01f)
			{
				return 1f;
			}
			float num2 = Mathf.Clamp01(time / num);
			float num3 = Mathf.Clamp01((duration - time) / num);
			return Mathf.Clamp01(Mathf.Min(num2, num3));
		}

		public static void ResetHistory()
		{
			recent.Clear();
			pool = null;
